L["Manners commands:"] = "Manners命令："
L["|cffffd100/mnr|r works in place of |cffffd100/manners|r in all of them."] = "以上所有命令中都可以用|cffffd100/mnr|r代替|cffffd100/manners|r。"
L["try cleared -- the normal cast takes effect when this fight ends; until then a press runs the macro already on the button."] = "try已清除——正常施法将在本场战斗结束后生效；在此之前按下仍会运行按钮上现有的宏。"
L["try cleared -- back to the normal cast."] = "try已清除——恢复正常施法。"
L["try armed: |cff80ff80%s|r"] = "try已就绪：|cff80ff80%s|r"
L["|cffff8080not armed for now:|r %s."] = "|cffff8080暂未就绪：|r%s。"
L["expands to: |cffffffff%s|r"] = "展开为：|cffffffff%s|r"
L["%d characters -- %d over the %d a macro body holds. The client will cut it, and what runs is not what is printed above."] = "共%d个字符——超出%d个（宏正文最多%d个）。客户端会截断它，实际运行的内容与上面显示的不同。"
L["It takes effect when this fight ends; until then a press runs the macro already on the button. |cffffd100/manners try|r with nothing clears it."] = "它将在本场战斗结束后生效；在此之前按下仍会运行按钮上现有的宏。不带参数输入|cffffd100/manners try|r可清除。"
L["The prompt arms it once they have one. |cffffd100/manners try|r with nothing clears it."] = "等对方有了单位标识，提示框就会让它就绪。不带参数输入|cffffd100/manners try|r可清除。"
L["Click the prompt to run it. |cffffd100/manners try|r with nothing clears it."] = "点击提示框即可运行。不带参数输入|cffffd100/manners try|r可清除。"
L["Targeting forms, for /manners try:"] = "目标选择写法（用于/manners try）："
L["(on yourself)"] = "（对自己）"
L["Tokens: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} is what a debt is filed under, {aim} is what a targeting line wants. Use \\n for a new line."] = "占位符：|cffffd100{unit} {name} {aim} {first} {spell} {id}|r。{name}是记录人情时用的名字，{aim}是目标选择行需要的写法。用\\n换行。"
L["the favour ledger did not load -- reinstalling Manners should bring it back."] = "人情账本没有加载——重新安装Manners应该可以恢复。"
L["unlocked -- it can be dragged once this fight ends; until then a press still casts what the fight froze. Then |cffffd100/manners lock|r."] = "已解锁——本场战斗结束后才能拖动；在此之前按下仍会施放战斗中冻结的内容。拖好后输入|cffffd100/manners lock|r。"
L["unlocked -- it can be dragged once this fight ends; nothing is armed meanwhile. Then |cffffd100/manners lock|r."] = "已解锁——本场战斗结束后才能拖动；在此期间没有就绪的施法。拖好后输入|cffffd100/manners lock|r。"
L["unlocked -- drag the prompt, then |cffffd100/manners lock|r."] = "已解锁——拖动提示框，然后输入|cffffd100/manners lock|r。"
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- |cffffd100/manners on|r first."] = "已解锁，但插件已|cffff8080关闭|r，所以没有可拖动的提示框——请先输入|cffffd100/manners on|r。"
L["locked."] = "已锁定。"
L["hand your target back after buffing: |cff00ff00on|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "加增益后恢复目标：|cff00ff00开启|r——本场战斗结束后生效；在此之前按下仍会运行按钮上现有的宏。"
L["hand your target back after buffing: |cffff0000off|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "加增益后恢复目标：|cffff0000关闭|r——本场战斗结束后生效；在此之前按下仍会运行按钮上现有的宏。"
L["hand your target back after buffing: |cff00ff00on|r"] = "加增益后恢复目标：|cff00ff00开启|r"
L["hand your target back after buffing: |cffff0000off|r"] = "加增益后恢复目标：|cffff0000关闭|r"
L["click logging: |cff00ff00on|r"] = "点击记录：|cff00ff00开启|r"
L["click logging: |cffff0000off|r"] = "点击记录：|cffff0000关闭|r"
L["verbose: |cff00ff00on|r -- a line in your own chat when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed"] = "详细提示：|cff00ff00开启|r——有人给你加增益、人情算作已还，以及点击失败、被跳过或仍欠着人情时，会在你自己的聊天框里显示一行"
L["verbose: |cffff0000off|r"] = "详细提示：|cffff0000关闭|r"
L["enabled."] = "已开启。"
L["disabled."] = "已关闭。"
L["nobody is on your never-offer list. Shift-right-click the prompt to put whoever it is showing on it."] = "你的永不推荐名单是空的。Shift+右键点击提示框，可把上面显示的人加入名单。"
L["never offered anything unless they buff you: %s"] = "除非对方给你加增益，否则永不推荐：%s"
L["say who: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lists everybody on the list."] = "请指明是谁：|cffffd100/manners allow Name|r。输入|cffffd100/manners never|r可列出名单上的所有人。"
L["|cffffffff%s|r can be offered again."] = "|cffffffff%s|r可以再次被推荐了。"
L["nobody called %s is on your never-offer list."] = "你的永不推荐名单中没有叫%s的人。"
L["snooze takes a number of minutes from 1 to %d, or off -- for example |cffffd100/manners snooze 15|r or |cffffd100/manners snooze 1h|r."] = "snooze后面要跟1到%d之间的分钟数，或者off——例如|cffffd100/manners snooze 15|r或|cffffd100/manners snooze 1h|r。"
L["your settings are in the box under |cffffd100Share as text|r on the Profiles tab of the options -- click in it, select all and copy."] = "你的设置在选项“配置文件”标签页|cffffd100以文本分享|r下的文本框中——点击文本框，全选并复制。"
L["this string is too long to be imported back -- a very long phrase box under What I say is the usual cause. Shorten it if you want to share these settings."] = "这个字符串太长，无法再导入回来——通常是因为“我说什么”标签页中的台词文本框内容过长。如果想分享这些设置，请缩短其中的台词。"
L["paste the settings string into the box under |cffffd100Share as text|r on the Profiles tab, or type |cffffd100/manners import|r followed by it."] = "把设置字符串粘贴到“配置文件”标签页|cffffd100以文本分享|r下的文本框中，或输入|cffffd100/manners import|r后接该字符串。"
L["type |cffffd100/manners import|r followed by a settings string."] = "输入|cffffd100/manners import|r，后接设置字符串。"
L["Tools for testing Manners on this client:"] = "在这个客户端上测试Manners的工具："
L["nothing has broken this session."] = "本次会话中没有出现任何错误。"
L["|cffffd100the last %d of %d|r |cff808080(%d kept)|r:"] = "|cffffd100最近%d条（共%d条）|r|cff808080（保留%d条）|r："
L["|cffffd100the last %d of %d|r:"] = "|cffffd100最近%d条（共%d条）|r："
L["Flavour.lua did not load -- check the toc's file list"] = "Flavour.lua没有加载——请检查toc的文件列表"
L["your own buff: not offered -- %s is switched off."] = "你自己的增益：不推荐——%s已关闭。"
L["|cffff4040this client has never heard of %s|r -- Manners has the wrong spell ids for %s on %s. Please report this line."] = "|cffff4040此客户端根本不认识%s|r——Manners为%s准备的法术ID在%s上不对。请报告这一行。"
L["owes returning: |cffffffff%s|r (%ds left, buffed you %ds ago)"] = "待还人情：|cffffffff%s|r（剩余%d秒，%d秒前给你加了增益）"
L["not watching for favours -- Manners is switched off."] = "未在留意人情——Manners已关闭。"
L["not watching for favours -- |cffffd100People who buff me|r is switched off."] = "未在留意人情——|cffffd100给我加增益的人|r已关闭。"
L["nobody has buffed you recently."] = "最近没有人给你加增益。"
L["your own buff: offered to you when you are missing it."] = "你自己的增益：你缺少它时会推荐给你。"
L["your own buff: nothing you cast goes on yourself alone."] = "你自己的增益：你没有只对自己施放的增益。"
L["|cffff8080own buffs: last scan not believed (%s)|r -- %d read, baseline %d"] = "|cffff8080自身增益：上次扫描不可信（%s）|r——读取%d个，基线%d个"
L["|cffffd100own buffs: baseline not settled|r -- %d read, waiting for a second scan to agree"] = "|cffffd100自身增益：基线未确定|r——读取%d个，等待第二次扫描确认"
L["own buffs: %d read, baseline %d"] = "自身增益：读取%d个，基线%d个"
L["%d changes to your auras this session, read in %d walks"] = "本次会话你的光环变化了%d次，共读取%d轮"
L["thank with an emote: |cff00ff00on|r"] = "用表情道谢：|cff00ff00开启|r"
L["thank with an emote: |cffff0000off|r"] = "用表情道谢：|cffff0000关闭|r"
L["last thanked: |cffffffff%s|r, %ds ago (the game answered %s)"] = "上次道谢：|cffffffff%s|r，%d秒前（游戏返回%s）"
L["last not thanked: |cffffffff%s|r, %ds ago (%s)"] = "上次未道谢：|cffffffff%s|r，%d秒前（%s）"
L["switched OFF on this profile -- nothing is recorded or offered; /manners on"] = "此配置文件已关闭——不记录也不推荐任何人；输入/manners on"
L["prompt is UNLOCKED -- it will not buff anyone until you /manners lock"] = "提示框已解锁——在你输入/manners lock之前不会给任何人加增益"
L["|cffffd100snoozed until %s|r -- no prompt until then; /manners snooze off ends it"] = "|cffffd100免打扰至%s|r——在此之前不显示提示框；输入/manners snooze off可结束"
L["|cffffd100mounted|r -- Not while mounted keeps the prompt away until you get off"] = "|cffffd100骑乘中|r——“骑乘时不显示”会让提示框在你下坐骑之前保持隐藏"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only your own buff and people who buffed you or asked are offered"] = "|cffffd100节省法力值|r——在法力值回到%d%%之前，只推荐你自己的增益，以及给你加过增益或向你要过增益的人"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only people who buffed you or asked are offered"] = "|cffffd100节省法力值|r——在法力值回到%d%%之前，只推荐给你加过增益或向你要过增益的人"
L["|cffffd100ready check|r -- your party or raid comes first until the pull"] = "|cffffd100就位确认|r——开怪前你的小队或团队优先"
L["|cffffd100raid groups|r -- in a raid, only groups %s are offered unasked"] = "|cffffd100团队小队|r——在团队中，只主动推荐以下小队：%s"
L["|cffffd100raid groups|r -- every group is unticked, so in a raid nobody is offered unasked"] = "|cffffd100团队小队|r——所有小队都未勾选，所以在团队中不会主动推荐任何人"
L["|cffff8080/manners try is armed:|r %s -- clear it with a bare /manners try"] = "|cffff8080/manners try已就绪：|r%s——不带参数输入/manners try可清除"
L["queue now: %d"] = "当前队列：%d"
L["queue if switched on: %d"] = "开启后的队列：%d"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "没有|cffffd100/manners %s|r这个命令——你是想输入|cffffd100/manners %s|r吗？输入|cffffd100/manners help|r可列出全部命令。"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "没有|cffffd100/manners %s|r这个命令——你是想输入|cffffd100/manners %s|r吗？输入|cffffd100/manners dev|r可列出测试工具。"
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "多谢啦，{name}！回到熔炉边，头一轮酒俺请！"
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "承情啦，{name}。山里从此多了你这个朋友！"
L["Thank ye, {name}! I'd have been fine without it, mind. But thank ye."] = "谢啦，{name}！没它俺也扛得住，真的。不过还是谢啦！"
L["Bless ye, {name}! I'd hug ye, but ye'd be needin' a healer after."] = "好人哪，{name}！真想抱你一下，可抱完你得找治疗。"
L["Paid back already, {name}. Quicker than I've ever settled a bar tab."] = "这就还上了，{name}。俺结酒账都没这么快过。"
L["I'll tell this at the Thunderbrew like ye saved me life, {name}. Thank ye!"] = "到了雷酒酿酒厂，这事就成了你救俺一命，{name}！谢啦！"
L["Grand, {name}! I'd carve ye a statue, but this is quicker."] = "痛快，{name}！本想给你刻座石像，还是这个来得快。"
L["The Titans made us of stone, {name}, but that still touched me. Thank ye."] = "泰坦用石头造的俺，{name}，这下石头心也被你捂热了。谢啦！"
L["Thank ye, {name}. Back at ye, before me pride notices I needed it."] = "谢啦，{name}。赶紧还你，别让俺的面子发现俺用得着它。"
L["Thank ye, {name}. Muradin says a debt left unpaid rusts. Here, before it does."] = "谢啦，{name}。穆拉丁说，欠账不还会生锈。给，趁它还没锈。"
L["Thank ye, {name}. I'd give ye a ride on me ram, but he bites strangers. And me."] = "谢啦，{name}。本想让你骑骑俺的山羊，可它咬生人。也咬俺。"
L["The Explorers' League'll ask where ye dug up such manners, {name}. Thanks!"] = "探险者协会准得问，{name}：这么稀罕的礼数，打哪儿出土的？谢啦！"
L["Thank ye, {name}. Me beard's on end. That's dwarven fer 'deeply touched'."] = "谢啦，{name}。俺胡子都竖起来了。矮人话里这叫“感动坏了”。"
L["Mined half o' Khaz Modan, {name}. Never struck a vein that rich. Yer cut."] = "俺挖遍半个卡兹莫丹，{name}，没碰上过这么富的矿脉。这份归你！"
L["Like a Kharanos hearth in a Dun Morogh blizzard, that, {name}. Thank ye."] = "雪中送炭啊，{name}，赛过丹莫罗暴风雪里卡拉诺斯的炉火。谢啦！"
L["Came back to ye like a Wildhammer's stormhammer, {name}. Less painful, mind."] = "像蛮锤的风暴之锤，嗖地飞回你手里，{name}。放心，不砸脸。"
L["Come to Ironforge, {name}. Me mam'll feed ye till ye can't stand. Thank ye!"] = "来铁炉堡吧，{name}。俺娘能把你喂得站不起来。谢啦！"
L["Checked it fer gunpowder out o' habit, {name}. Clean as a whistle. Here's yers!"] = "习惯性查了查有没有火药，{name}。干干净净。这份是你的！"
L["Aye, {name}, ye only had to ask. Hold still now, like a good anvil."] = "好嘞，{name}，开口就成。站着别动，跟块好铁砧似的。"
L["Say no more, {name}. Stone and steel, here it comes."] = "甭多说，{name}。石头和钢铁作证，接好咯！"
L["Ask a dwarf fer help, {name}, and ye'll get it. Loudly."] = "找矮人帮忙，{name}，准帮。就是嗓门大了点。"
L["Right, {name}. Brace yerself; I do everything like I'm swingin' a hammer."] = "行，{name}。站稳咯，俺干啥都跟抡锤子似的。"
L["Aye, {name}, and a story about it ye didn't ask fer. Where to begin..."] = "好嘞，{name}，外加一个你没问的故事。话说当年……"
L["One {buff}, pulled fresh like a proper pint, {name}."] = "{buff}一杯，现打的，跟扎啤一样鲜，{name}！"
L["Done, {name}. Dwarven work: over-built, under-priced and guaranteed."] = "好了，{name}。矮人出品：料超足，价超低，终身保修！"
L["Easy, {name}. Last favour I did was fix a gnome's tank. Cost me both eyebrows."] = "小事，{name}。上回帮忙是修侏儒的坦克，赔进去俺两条眉毛。"
L["Aye, {name}. Mountain kings never refuse. I'm more a foothill, but same rule."] = "好嘞，{name}。山丘之王从不推辞。俺顶多算个小土坡，规矩一样。"
L["Tempered and quenched, {name}. Mind, it's still hot."] = "淬过火了，{name}。当心，还烫手呢。"
L["Done afore ye finished, {name}. Dwarves hear 'please' through solid rock."] = "你话没说完俺就弄好了，{name}。矮人隔着石头都听得见“请”字。"
L["Aye, {name}. In Dun Morogh ye help quick, or ye both freeze standin' there."] = "好嘞，{name}。在丹莫罗，帮忙得趁快，不然俩人都冻成冰棍。"
L["Aye, {name}. Ye'll feel it in yer boots first. That's how ye know it's dwarven."] = "好嘞，{name}。脚底板先热乎起来——那就对了，矮人出品。"
L["Aye, {name}. Say no, and ye'd ask a gnome, and then I'd feel responsible."] = "好嘞，{name}。俺要是不答应，你就得去找侏儒，那俺可良心不安。"
L["Here, {name}, a wee somethin' to keep ye on yer feet. Wee, like me."] = "喏，{name}，一点小意思，保你站得稳。小，跟俺一个样。"
L["Off ye go, {name}, steady as the mountain."] = "去吧，{name}，稳如大山！"
L["Here, {name}. Ale's for after; this is for before."] = "拿着，{name}。麦酒打完再喝，这个开打前用。"
L["Magni turned to diamond fer the cause, {name}. This is the cheaper option."] = "麦格尼为了大业变成了钻石，{name}。这个是平价版。"
L["A dwarf's got yer back, {name}. Well, yer knees. Close enough."] = "矮人给你撑腰，{name}。呃，撑到膝盖。差不多。"
L["If a trogg bothers ye, {name}, tell it a dwarf sent ye. Then run."] = "穴居人找茬，{name}，就报矮人的名号。然后快跑！"
L["If it wears off, {name}, give it a good thump. That's how we fix everything."] = "要是失效了，{name}，就使劲拍两下。俺们修啥都这么修。"
L["Take this, {name}. I'd give ye some stubbornness too, but I'm usin' all mine."] = "拿着，{name}。本想再分你点倔脾气，可俺的全自个儿用着呢。"
L["Mind the wendigos, {name}: big, hairy and grumpy. Like me, but hungrier."] = "当心雪怪，{name}：个大、毛多、脾气臭。跟俺差不多，就是更饿。"
L["Take this, {name}. Me grandad fought three wars with a pickaxe and this."] = "拿着，{name}。俺爷爷就凭一把矿镐和这个，打了三场战争。"
L["Dwarven make, {name}. Drop it off Thandol Span and it'd still work. Don't."] = "矮人出品，{name}。从萨多尔大桥扔下去都照样好使。别扔啊。"
L["Stonewrought Dam holds back all o' Loch Modan, {name}. This'll hold ye an hour."] = "斯通华特大坝拦住了整个洛克莫丹，{name}。这个能撑你一小时。"
L["Won't keep yer boots dry in the Wetlands, {name}. Nothin' does. The rest, aye."] = "在湿地可保不住你靴子干，{name}。啥也保不住。别的都包了。"
L["Old miner's rule, {name}: never go down a hole without a lamp, a mate and this."] = "老矿工的规矩，{name}：下洞得带三样——矿灯、伙计，还有这个。"
L["Brann Bronzebeard went explorin' with less, {name}, and wrote three books."] = "布莱恩·铜须带的比这还少，{name}，照样写了三本书。"
L["Mountaineers swear by it, {name}. Ye'll climb no better, but land softer."] = "巡山人都信这个，{name}。爬得不会更好，摔得倒能轻点。"
L["Ironforge's gates have never fallen, {name}. Neither should ye. Take this."] = "铁炉堡的大门从来没倒过，{name}。你也别倒。拿着。"
L["Me cousins down Blackrock way would've set it alight first, {name}. Fer luck."] = "黑石山那帮老表，{name}，准得先点把火再给你。图个吉利。"
L["Stone and hammer keep ye, cousin {name}!"] = "愿石与锤护着你，老表{name}！"
L["Three Hammers, one round, cousin {name}!"] = "三锤议会，同一轮酒，老表{name}！"
L["Yer cousin's cousin married mine, {name}, I'd wager. It's a small mountain."] = "俺敢打赌，{name}，你表哥的表哥娶了俺表姐。这山可真小。"
L["Two dwarves together, {name}. Pity whatever's standin' in our way."] = "俩矮人凑一块儿了，{name}。挡道的可要倒大霉咯。"
L["Bronzebeard, Wildhammer, Dark Iron, Earthen, {name}: one family, nobody agrees."] = "铜须、蛮锤、黑铁、土灵，{name}：一家人，谁也不服谁。"
L["Between the pair of us, {name}, we could out-stubborn a mountain."] = "咱俩凑一块儿，{name}，论倔能把山都比下去。"
L["Me grandmother'd climb out of her tomb if I did any less fer kin, {name}."] = "对自家人少出一分力，{name}，俺奶奶能从坟里爬出来。"
L["The Titans carved us both from the same rock, {name}. Explains the headaches."] = "泰坦用同一块石头凿出咱俩，{name}。难怪一个比一个头铁。"
L["Proud o' ye, {name}. Don't let it go to yer head; no room under the helmet."] = "俺为你骄傲，{name}。可别得意得脑袋发胀，头盔就戴不上了。"
L["Stand behind me, {name}. Aye, I know. Crouch a bit."] = "站俺后头，{name}。嗯，俺知道。你蹲低点儿。"
L["Right, {name}: I take the front, ye take the loot, and we argue after."] = "说好了，{name}：俺打头阵，你捡战利品，完事再吵。"
L["If I start singin', {name}, the fight's gone well. Or very badly."] = "要是俺唱起歌来，{name}，就是仗打得顺。或者糟透了。"
L["Dwarves never leave a mate behind, {name}. Nor a keg. Mates first, mind."] = "矮人从不丢下兄弟，{name}。酒桶也不丢。当然，兄弟优先。"
L["Beards out, {name}! Them without beards, look fierce. It's nearly as good."] = "亮出胡子来，{name}！没胡子的就摆张凶脸，效果也差不多。"
L["Knocked on the nearest rock, {name}. Solid. No cave-ins fer us today."] = "敲了敲旁边的石头，{name}。结实。今天塌不了方。"
L["No fires near me pack, {name}. It's mostly gunpowder. And a sandwich."] = "别在俺背包旁边生火，{name}。里头大半是火药。还有个三明治。"
L["Dwarves don't retreat, {name}. Our legs aren't built fer it. So forward it is."] = "矮人不撤退，{name}。腿太短，退不利索。那就往前冲！"
L["Stay close, {name}. If it goes dark, follow the cursin'. That'll be me."] = "跟紧，{name}。要是黑了，就循着骂声走。那就是俺。"
L["Dwarves always know which way is down, {name}. Up's yer problem."] = "矮人永远知道哪边是下，{name}。往上走就看你的了。"
L["Anythin' made o' stone, {name}, let me talk to it first. Might be a cousin."] = "碰上石头做的东西，{name}，先让俺跟它聊聊。没准是俺老表。"
L["If the ceilin' creaks, {name}, I'll tell ye. If I go quiet, run."] = "顶上要是嘎吱响，{name}，俺会告诉你。俺要是不吭声了，快跑。"
L["Mornin', {name}! Too early for ale. Almost. Have this first."] = "早啊，{name}！喝麦酒还太早。就差一点。先来这个。"
L["Up with the forge fires, {name}! A dwarf's day starts with a hammer and this."] = "熔炉点火俺就起了，{name}！矮人的一天从锤子和这个开始。"
L["Early, {name}? Nonsense. The mine's been open two hours. Here."] = "早？{name}，瞎说。矿井都开工俩钟头了。给。"
L["Mornin', {name}. Me beard's still asleep. The rest o' me is ready."] = "早啊，{name}。俺胡子还睡着呢，别处都醒了。"
L["Mornin', {name}. Porridge, a pipe and this. The other two are mine."] = "早啊，{name}。一碗粥、一斗烟，外加这个。前两样归俺。"
L["The rams had me up at dawn, {name}. Headbutted the door till I came out. Here."] = "天刚亮山羊就把俺叫起来了，{name}。拿脑袋撞门撞到俺出来。给。"
L["Mornin', {name}. Ears still ringin' from last night's singin'. Here."] = "早啊，{name}。昨晚唱的歌，俺耳朵到现在还嗡嗡响。给。"
L["My thanks, {name}. Let me return the kindness before a bard gets it wrong."] = "多谢，{name}。趁吟游诗人还没把这事唱走样，我先还你。"
L["Kindly done, {name}. Let no one say we forget a friend."] = "有心了，{name}。可别让人说我们忘了朋友。"
L["Thank you, {name}. I'd knight you, but apparently I 'need permission'."] = "谢谢你，{name}。真想封你为骑士，可人家说我“得先批准”。"
L["Repaid on the spot, {name}. In Stormwind that'd take three forms and a stamp."] = "当场还清，{name}。在暴风城，这得填三张表再盖个章。"
L["Thanks, {name}. I'd pay in gold, but Stormwind still owes the stonemasons."] = "谢了，{name}。本想付金币，可暴风城还欠着石匠的工钱呢。"
L["Much obliged, {name}. Mother said always return a kindness. And the dish."] = "多谢，{name}。我娘说过，受人恩惠要还，借的盘子也要还。"
L["Thank you, {name}. Consider the scales balanced, by royal decree. Mine."] = "谢谢你，{name}。这笔账奉旨两清。圣旨是我下的。"
L["You shame me, {name}; I should have thought of it first. Allow me."] = "惭愧，{name}，本该我先想到的。请容我回敬。"
L["Heartier than Westfall Stew, {name}, and I've wept over that stew. Thank you."] = "比西部荒野炖肉还暖心，{name}，那锅炖肉我可是哭过的。谢谢你。"
L["Thank you, {name}. I'll tell Marshal Dughan. He won't care, but I'll tell him."] = "谢谢你，{name}。我会告诉杜汉元帅的。他不会在意，但我会说。"
L["Job's done, {name}! My grandad built half of Stormwind saying that. Thanks."] = "工作完成，{name}！我爷爷喊着这句，盖了半座暴风城。谢了！"
L["Lakeshire will finish its bridge before I forget this, {name}. So, never."] = "要我忘了这事，{name}，除非湖畔镇的桥修好了。所以，永远不会。"
L["Kul Tirans say a kindness goes back on the next tide, {name}. There it goes."] = "库尔提拉斯人说，好意要随下一波潮水送回去，{name}。潮来了。"
L["Thank you, {name}. Northshire's monks would be proud. Of you. They know me."] = "谢谢你，{name}。北郡的修士们会为你骄傲。为我就算了，他们认识我。"
L["Not since Mum packed my Deadmines lunch, {name}, have I felt so looked after."] = "上回这么被人照顾，{name}，还是我娘给我装去死亡矿井的午饭。"
L["Into my memoirs, {name}. Chapter nine: 'Everyone Was Lovely'. Thank you."] = "写进我的回忆录，{name}。第九章：“人人都很可爱”。谢谢你。"
L["I'll toast you at the Pig and Whistle, {name}. Then the pig. Then the whistle."] = "我要在猪和哨子旅馆为你干杯，{name}。再敬猪。再敬哨子。"
L["Of course, {name}. Hold still and look heroic; it helps the bards."] = "当然，{name}。站好，摆出英雄样，方便诗人作歌。"
L["Right away, {name}. Keep your shield high."] = "马上就好，{name}。盾牌举高些！"
L["More work? Gladly, {name}. It beats the lumber mill."] = "又有活儿？乐意之至，{name}。总比去伐木场强。"
L["Of course, {name}. Humans excel at helping and overpromising. This is helping."] = "当然，{name}。人类最擅长两件事：帮忙和夸海口。这回是帮忙。"
L["Certainly, {name}. Humans are quick learners; I learned this one yesterday."] = "没问题，{name}。人类学东西快，这招我昨天才学会。"
L["Hold still, {name}, like a statue in the Valley of Heroes. You'd fit right in."] = "别动，{name}，就像英雄谷里的雕像。你站那儿毫不违和。"
L["Right away, {name}. The Light helps those who ask. So do I, and I'm quicker."] = "马上，{name}。圣光帮助求助之人。我也是，而且我更快。"
L["Sailors' rule, {name}: somebody calls for help, you row. Here."] = "水手的规矩，{name}：有人喊救命，就划过去。给。"
L["Of course, {name}. Stand up straight; my old sergeant is watching, somewhere."] = "当然，{name}。站直了，我那老军士长还在哪儿盯着呢。"
L["Of course, {name}. A polite request is rarer than a quiet night in Duskwood."] = "当然，{name}。客气的请求比暮色森林的安静夜晚还稀罕。"
L["Right away, {name}. I'll play the Archbishop; you pretend to be impressed."] = "马上，{name}。我来扮大主教，你负责假装很感动。"
L["Step into the light, {name}. Not the Light; I just like to see my aim."] = "站到光底下来，{name}。不是圣光，是亮光——方便我瞄准。"
L["Stormwind rose from rubble, {name}. I can manage one {buff}."] = "暴风城都能从废墟里重建，{name}。一个{buff}还能难倒我？"
L["Of course, {name}. Last one I did was a Westfall scarecrow. Long story."] = "当然，{name}。上一个是西部荒野的稻草人。说来话长。"
L["Aye, {name}. Kul Tiran terms: a handshake, and I spare you the shanty."] = "行，{name}。库尔提拉斯的规矩：握个手，我就不唱水手号子了。"
L["The road ahead is long, {name}. This won't shorten it, but it'll help."] = "前路漫长，{name}。这个缩不短路，但能帮上忙。"
L["Fair winds and following seas, {name}."] = "愿你一帆风顺、海不扬波，{name}。"
L["Take this, {name}. Elves have centuries to be generous; I've got fifty years."] = "拿着，{name}。精灵能慷慨几百年，我只有五十年，得抓紧。"
L["A little something, {name}. Don't tell the guards; they'll all want one."] = "一点小意思，{name}。别告诉卫兵，不然人人都要。"
L["Here, {name}. If a kobold asks, you don't have a candle."] = "给，{name}。狗头人要是问起，你就说没带蜡烛。"
L["For you, {name}. A human gift: well meant, hastily made, surprisingly sturdy."] = "给你，{name}。人类的礼物：心意满满，做工匆忙，意外结实。"
L["Mind the murlocs, {name}. Take this; I've seen what they do to a picnic."] = "小心鱼人，{name}。拿着这个，我见过它们怎么祸害野餐。"
L["Every road needs a hero, {name}. Today it's me, apparently. Take this."] = "每条路都需要一位英雄，{name}。今天好像轮到我了。拿着。"
L["Stay out of Duskwood after dark, {name}. It's always dark. Take this."] = "天黑后别进暮色森林，{name}。那儿一直是黑的。拿着。"
L["Redridge gnolls take anything not nailed down, {name}. This is nailed down."] = "赤脊山的豺狼人见啥拿啥，{name}，除非钉死了。这个钉死了。"
L["If you meet Hogger, {name}, take this and a friend. Mostly the friend."] = "要是碰上霍格，{name}，带上这个，再带个朋友。主要是朋友。"
L["The Light and a good pair of boots, {name}. Now you've got one of them."] = "圣光加一双好靴子，{name}。现在你有其中一样了。"
L["Every hero in Stormwind began with a kindness and a borrowed sword, {name}."] = "暴风城的英雄，{name}，都起步于一份好意和一把借来的剑。"
L["Here, {name}. The Defias can't steal this one. They've tried everything else."] = "给，{name}。迪菲亚偷不走这个。别的他们都偷遍了。"
L["Uther blessed strangers on the road, {name}. I've less hammer, same idea."] = "乌瑟尔会为路上的陌生人祝福，{name}。我锤子小点，心意一样。"
L["Take this, {name}. It's a tradition. I just started it, but it's a tradition."] = "拿着，{name}。这是传统。刚被我开创的，但也是传统。"
L["The wolves in Elwynn look friendly, {name}. They are not. Take this."] = "艾尔文森林的狼看着挺友善，{name}。其实不是。拿着。"
L["Arathor's children stand together, {name}."] = "阿拉索的子孙同进同退，{name}。"
L["A fellow human, {name}! Quick, let's found a kingdom before lunch."] = "同为人类，{name}！快，午饭前咱们建个王国。"
L["Stormwind or Boralus, {name}, we'll both complain about the weather."] = "暴风城也好，伯拉勒斯也罢，{name}，咱们都爱抱怨天气。"
L["Human to human, {name}: no, I don't know why everything happens to us either."] = "人类对人类，{name}：不，我也不知道为啥啥事都找上咱们。"
L["Short lives, long to-do lists, {name}. We humans must help each other along."] = "命短，待办清单长，{name}。咱们人类得互相搭把手。"
L["Stormwind stone or Kul Tiran oak, {name}, we outlast everyone's expectations."] = "暴风城的石，库尔提拉斯的木，{name}：咱们总比人料想的耐用。"
L["Humans stick together, {name}. Everyone else is taller, older or furrier."] = "人类得抱团，{name}。别人不是比咱高、比咱老，就是比咱毛多。"
L["Our lot built half the world on bread, stubbornness and bad luck, {name}."] = "咱们靠面包、倔脾气和坏运气，{name}，建起了半个世界。"
L["Don't tell the dwarves, {name}, but it was us humans who invented the tavern."] = "别告诉矮人，{name}，酒馆其实是咱们人类发明的。"
L["Keep close, {name}. Humans have always won by outnumbering things."] = "跟紧点，{name}。人类向来靠人多取胜。"
L["Stay in formation, {name}. We haven't got one, but stay in it anyway."] = "保持阵型，{name}。咱们没有阵型，但也给我保持住。"
L["I'll draw up a plan, {name}, and then we can all ignore it together."] = "我来定个计划，{name}，然后大家一起无视它。"
L["Every hero in the songs had friends, {name}. Nobody sings about them. I will."] = "歌里的英雄都有朋友，{name}，却没人唱他们。我来唱。"
L["Shields up, {name}. Stormwind taught me to march; nobody taught me to stop."] = "举盾，{name}。暴风城教会我行军，可没人教我停下。"
L["If this goes badly, {name}, we regroup at the nearest inn. Human tactics."] = "要是打砸了，{name}，就去最近的旅店集合。人类战术。"
L["I've made us a flag, {name}. It's a handkerchief on a stick, but it's ours."] = "我给咱们做了面旗，{name}。就是根棍子挑块手帕，但它是咱们的。"
L["Keep a torch lit, {name}. Humans can't see in the dark, and we hate it."] = "火把别灭，{name}。人类在黑暗里看不见，而且特别讨厌这样。"
L["Watch my back, {name}; I'll watch yours. The Light has the rest. Better view."] = "你看着我背后，{name}，我看着你的。剩下的交给圣光，它视野好。"
L["Humans always rise to the occasion, {name}. Usually after tripping over it."] = "人类关键时刻总能站起来，{name}。通常是因为刚摔了一跤。"
L["Do this well, {name}. Some elf will be telling the story for a thousand years."] = "好好干，{name}。某个精灵会把这事讲上一千年。"
L["Farmers, sailors, bakers, {name}: every army Stormwind ever raised. Onward!"] = "农夫、水手、面包师，{name}：暴风城的军队向来如此。前进！"
L["Ishnu-alah, {name}. Returned the same day, which for a kaldorei is rushing."] = "Ishnu-alah，{name}。当天就还，对卡多雷来说已经很赶了。"
L["Thank you, {name}. Elune smiles on the generous."] = "谢谢你，{name}。艾露恩眷顾慷慨之人。"
L["Thank you, {name}. Even the wisps glow brighter, and they're hard to impress."] = "谢谢你，{name}。连小精灵都亮了几分，它们可不好打动。"
L["Elune saw that, {name}. She sees everything, so I had best return it."] = "艾露恩看见了，{name}。她什么都看得见，我还是赶紧还上吧。"
L["Thank you, {name}. Returned before I nap for a century or two."] = "谢谢你，{name}。趁我还没睡上一两百年，先还给你。"
L["Thank you, {name}. The Ancients will hear of this. They're dreadful gossips."] = "谢谢你，{name}。古树们会听说这事的，它们最爱嚼舌根。"
L["Thank you, {name}. I'll tell the Sentinels to stop aiming at you."] = "谢谢你，{name}。我会让哨兵们别再瞄着你了。"
L["My people never hurry, {name}. For you, an exception."] = "我族从不着急，{name}。为你破例一次。"
L["Ande'thoras-ethil, {name}. May your troubles be diminished, as mine just were."] = "Ande'thoras-ethil，{name}。愿你烦恼消减，一如我的刚才。"
L["We gave up immortality at Hyjal, {name}. Kindness has been worth double since."] = "我们在海加尔山舍弃了永生，{name}。从那以后，善意就值双倍了。"
L["My ears went a darker purple, {name}. On a kaldorei, that means I'm touched."] = "我的耳朵紫得更深了，{name}。在卡多雷身上，这代表我被感动了。"
L["Azshara's court never gave a thing away, {name}. You've outdone a queen."] = "艾萨拉的宫廷从不白送东西，{name}。你比女王还大方。"
L["The owls turned their heads for that, {name}. All the way round. High praise."] = "猫头鹰都为此扭过头来，{name}。转了一整圈。这可是高度评价。"
L["I outlived the Sundering, {name}. I'll not outlive a debt to you. Here."] = "我熬过了大分裂，{name}。可不能让欠你的人情活得比我长。给。"
L["All those centuries of memories, {name}, and this one goes near the front."] = "几百年的回忆里，{name}，这一段排得很靠前。"
L["I'll tell the moon about you tonight, {name}. She likes a good story."] = "今晚我会跟月亮讲讲你，{name}。她爱听好故事。"
L["Gladly, {name}. Be still, and let the moonlight find you."] = "乐意之至，{name}。静下心来，让月光照拂你。"
L["Of course, {name}. Elune's blessings are meant to be shared."] = "当然，{name}。艾露恩的祝福本就该与人分享。"
L["At last, {name}! I've waited ten thousand years for someone to ask."] = "终于，{name}！等人开口，我等了一万年。"
L["No riddle, no omen from Elune, {name}. Just a plain yes, for once."] = "不打哑谜，不等艾露恩显兆，{name}。就一个字：好。"
L["Of course, {name}. Ask in Darnassian next time and I'll add a bow."] = "当然，{name}。下次用达纳苏斯语问，我再附赠一个鞠躬。"
L["Elune already said yes, {name}. I'm merely catching up."] = "艾露恩早就答应了，{name}。我只是跟上而已。"
L["Of course, {name}. Stand still and pretend you're a tree. It helps."] = "当然，{name}。站着别动，假装自己是棵树。管用的。"
L["Step into the light, {name}. The last kaldorei I did this for Shadowmelded."] = "站到亮处来，{name}。上一个卡多雷，我还没施完他就影遁了。"
L["Certainly, {name}. Ask a kaldorei anything, except how old we are."] = "当然，{name}。问卡多雷什么都行，就别问年龄。"
L["In Darnassus, {name}, this takes a moonwell and a priestess. Out here, just me."] = "在达纳苏斯，{name}，这得有月亮井和女祭司。在外头，就我一个。"
L["The last army to ask me for help was fighting demons, {name}. You're politer."] = "上一支向我求助的军队在打恶魔，{name}。你比他们有礼貌。"
L["Gladly, {name}. Consider it on loan from Elune. She's never once collected."] = "乐意之至，{name}。就当是向艾露恩借的。她从没来收过账。"
L["One moment, {name}. My hair is older than most kingdoms, and it tangles."] = "稍等，{name}。我的头发比大多数王国都老，还爱打结。"
L["Darnassian has nine words for 'yes', {name}. I'll spare you eight of them."] = "达纳苏斯语的“好”有九种说法，{name}。饶你八种。"
L["Of course, {name}. The Sentinels would want a password. I'll accept 'please'."] = "当然，{name}。哨兵会要口令。我嘛，一个“请”字就够了。"
L["Elune-adore, {name}. Walk softly; the trees are light sleepers."] = "Elune-adore，{name}。脚步轻些，树睡得浅。"
L["May the forest shelter you, {name}, wherever you roam."] = "愿森林庇护你，{name}，无论你去往何方。"
L["A gift from the shadows, {name}. No, don't look. You won't find me."] = "来自暗影的礼物，{name}。别找了，你找不到我的。"
L["Elune lights your path, {name}. I'm merely holding the lantern."] = "艾露恩照亮你的路，{name}。我只是提灯的。"
L["The owls pointed you out, {name}. They have strong opinions. Here."] = "猫头鹰指认了你，{name}。它们很有主见。给。"
L["Tyrande would insist, {name}, and nobody argues with Tyrande."] = "泰兰德会坚持的，{name}，没人敢跟泰兰德争。"
L["Take this, {name}. The last one went to a hippogryph. It was less grateful."] = "拿着，{name}。上一份给了角鹰兽，它可没你这么领情。"
L["Mind the wildlife, {name}. Half of it is a druid, and all of it is watching."] = "当心野生动物，{name}。一半是德鲁伊，全都在盯着你。"
L["Walk with Elune, {name}. If she's busy, walk with this."] = "愿艾露恩与你同行，{name}。她要是忙，就带上这个。"
L["Mind the satyrs, {name}. They were Highborne once. You can tell by the sneer."] = "当心萨特，{name}。它们以前是上层精灵。看那副冷笑就知道。"
L["I've watched you from the treeline a while, {name}. Supportively. Here."] = "我在林子边看你有一阵了，{name}。是默默支持的那种。给。"
L["Most furbolgs are friendly, {name}. This is for the other ones."] = "熊怪大多挺友善，{name}。这个是防另外那些的。"
L["Moonwell water would be better, {name}, but it travels badly. This doesn't."] = "月亮井的水更好，{name}，可惜不好带。这个好带。"
L["A gift from Teldrassil, {name}. It's a long way down; I nearly dropped it."] = "来自泰达希尔的礼物，{name}。下来的路太长，我差点把它摔了。"
L["I'd stay to chat, {name}, but kaldorei chats run to the next full moon. Here."] = "本想和你聊聊，{name}，可卡多雷一聊就聊到下个满月。给。"
L["Bandu thoribas, {name}: prepare to fight. There. Now you're prepared."] = "Bandu thoribas，{name}：准备战斗。好了，现在你准备好了。"
L["From the kaldorei, the moon and a very old tree, {name}. Mostly from me."] = "卡多雷、月亮和一棵很老的树送你的，{name}。主要是我送的。"
L["Ishnu-alah, {name}. Elune keeps her children close."] = "Ishnu-alah，{name}。艾露恩从不远离她的孩子。"
L["Of course I saw you, {name}. It takes a kaldorei to spot a kaldorei."] = "我当然看见你了，{name}。卡多雷才看得见卡多雷。"
L["One kaldorei to another, {name}: we lost a tree, never each other."] = "卡多雷之间，{name}：丢过一棵树，从没丢过彼此。"
L["A kaldorei never leaves kin in the dark, {name}. Unless it's for cover."] = "卡多雷从不把同胞丢在黑暗里，{name}。除非是为了影遁。"
L["Two kaldorei, {name}, and still no helmet made that fits either pair of ears."] = "两个卡多雷，{name}，还是没有一顶头盔塞得下我们的耳朵。"
L["Sentinel, druid or simply stubborn, {name}? I'm all three on a good night."] = "哨兵、德鲁伊，还是单纯倔，{name}？状态好的晚上，我三样全占。"
L["Between us, {name}, twenty thousand years of telling everyone 'we tried that'."] = "你我加起来，{name}，已经跟人说了两万年“这个我们试过了”。"
L["Let's Shadowmeld together sometime, {name}, and see who notices."] = "改天一起影遁吧，{name}，看看谁会发现。"
L["Our shan'do sleeps in the Dream, {name}. Let's make his waking worth it."] = "我们的导师沉睡在翡翠梦境中，{name}。让他醒来时觉得值得。"
L["Our people are thin on the ground, {name}, and very thick in the trees."] = "我族在地上人丁稀少，{name}，在树上可密得很。"
L["Quick one, {name}? By kaldorei reckoning we'll be done before we start."] = "速战速决，{name}？按卡多雷的算法，还没开始就结束了。"
L["I'll be the one you can't see, {name}. That's not a mistake; that's the plan."] = "你看不见的那个就是我，{name}。这不是失误，是计划。"
L["Elune watches the whole party, {name}. I'm just the one who waves at her."] = "艾露恩看着整个小队，{name}。我只是那个冲她挥手的。"
L["Ten thousand years of companions, {name}. You lot rank rather high."] = "一万年里结识的同伴，{name}，你们排得相当靠前。"
L["Stay close, {name}. We kaldorei misplaced two World Trees. Not you, though."] = "跟紧点，{name}。我们卡多雷弄丢过两棵世界之树，可不会弄丢你。"
L["If I fall, {name}, don't fret. I'll float about as a wisp, looking wise."] = "我要是倒下，{name}，别慌。我会化作小精灵飘着，一脸高深。"
L["I fought beside Neltharion once, {name}. You're already a better ally."] = "我曾与奈萨里奥并肩作战，{name}。你已经是更好的盟友了。"
L["Follow me, {name}. I know these paths. They were a forest last time, mind."] = "跟我来，{name}。这些路我熟。不过上次来，这里还是森林。"
L["Should we fail, {name}, I'll remember you fondly for several thousand years."] = "万一失败了，{name}，我会深情地记住你几千年。"
L["I've watched heroes charge in blind for millennia, {name}. Let's try eyes open."] = "几千年来我看着英雄们闭着眼往里冲，{name}。我们试试睁着眼。"
L["If anyone asks, {name}, we were always this good. I'll swear to it for ages."] = "有人问起，{name}，就说我们一直这么强。这话我能作证好几个纪元。"
L["I'll take first watch, {name}. And second. A kaldorei barely notices a night."] = "我守第一班，{name}。第二班也归我。卡多雷眨个眼，一夜就过了。"
L["The moon's up, {name}. For a kaldorei, this is the middle of the morning."] = "月亮出来了，{name}。对卡多雷来说，这才刚到上午。"
L["Everyone sensible is asleep, {name}. Elune and I prefer it this way."] = "明白人都睡了，{name}。艾露恩和我就喜欢这样。"
L["Moonlight suits you, {name}. This is merely a second layer."] = "月光很衬你，{name}。这个只是再给你加一层。"
L["Dark at last, {name}. Now I see perfectly and everything else has to guess."] = "终于天黑了，{name}。现在我看得一清二楚，别人只能靠猜。"
L["Same stars I saw ten thousand years ago, {name}. They've aged better than me."] = "还是一万年前那些星星，{name}。它们比我老得体面。"
L["Moonrise, {name}. Every kaldorei just woke up a little, and got a little smug."] = "月亮升起来了，{name}。每个卡多雷都醒了几分，也得意了几分。"
L["Morning, {name}. My people slept through these for millennia. I'm adapting."] = "早，{name}。我族睡过了几千年的早晨，我正在适应。"
L["Dawn, {name}. Elune's gone to bed, so I'm covering for her."] = "天亮了，{name}。艾露恩睡觉去了，我替她值班。"
L["The sun's up, {name}, and so, reluctantly, am I."] = "太阳起来了，{name}，我也不情不愿地起来了。"
L["Too bright, {name}. I'll squint through this one; Elune forgives squinting."] = "太亮了，{name}。我就眯着眼施法吧，艾露恩会原谅眯眼的。"
L["Daybreak, {name}: the one hour a night elf is easy to spot. Quick, take this."] = "破晓了，{name}：暗夜精灵唯一好找的时辰。快，拿着。"
L["Up early, {name}? I'm up late. Let's meet in the middle, with this."] = "起得早，{name}？我是睡得晚。我们在中间碰个头，带上这个。"
L["The shadows remember kindness, {name}. So do I."] = "暗影记得善意，{name}。我也一样。"
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "多谢，{name}。虚空精灵不会忘记恩情。"
L["Thank you, {name}. The voices approve of you, which is frankly alarming."] = "谢谢你，{name}。那些低语很认可你，说实话这有点吓人。"
L["Thank you, {name}. Few give gifts to someone who glows this ominously."] = "谢谢你，{name}。肯给浑身冒着不祥紫光的人送礼的可不多。"
L["Kindness is rare in the Void, {name}. I'll return yours before it notices."] = "虚空里难得有善意，{name}。趁它没发现，我赶紧还你。"
L["Silvermoon threw us out, {name}. People like you make it hard to mind."] = "银月城赶走了我们，{name}。有你在，我都懒得计较了。"
L["Returned in full, {name}. It may be slightly purple. That's normal."] = "如数奉还，{name}。可能有点发紫。正常现象。"
L["The Void only takes, {name}. I, however, give back."] = "虚空只会索取，{name}。而我，懂得回报。"
L["Thank you, {name}. The whispers went quiet. That's how I know it was sincere."] = "谢谢你，{name}。低语都安静了。所以我知道你是真心的。"
L["Thank you, {name}. I'd smile, but people say it's unsettling. So: imagine one."] = "谢谢你，{name}。本想笑一个，可听说我笑起来瘆人。你脑补一下吧。"
L["Returned, {name}: cold hands, warm intentions. That's us in a sentence."] = "还你了，{name}：手是凉的，心是热的。一句话概括我们。"
L["Returned, {name}. You may hear it twice; my spells echo now."] = "还你了，{name}。你可能会听到两遍，我的法术现在有回声。"
L["The Void offered me forbidden knowledge, {name}. Yours was the nicer gift."] = "虚空给过我禁忌的知识，{name}。你的礼物更贴心。"
L["Alleria says the Void can be mastered, {name}. Kindness, I find, is easier."] = "奥蕾莉亚说虚空可以驾驭，{name}。我发现，善意更容易。"
L["Much obliged, {name}. Most people give us a wide berth. You gave me this."] = "多谢，{name}。别人见了我们都让出老远，你却给了我这个。"
L["Thank you, {name}. My shadow bowed as well. It never does. You've impressed it."] = "谢谢你，{name}。我的影子也鞠了个躬。它从不鞠躬。你把它折服了。"
L["As you wish, {name}. The shadows answer kindly today."] = "如你所愿，{name}。今日暗影格外温顺。"
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "交给我，{name}。虚空听我们的，不是反过来。"
L["Certainly, {name}. The whispers said no, so it's an easy yes."] = "当然，{name}。低语说不行，那就一定行。"
L["Of course, {name}. One {buff}, lightly seasoned with the Void."] = "当然，{name}。一份{buff}，撒了点虚空调味。"
L["Of course, {name}. Hold still; the shadows are shy with strangers."] = "当然，{name}。别动，暗影怕生。"
L["Gladly, {name}. Ren'dorei manners: the Void waits its turn."] = "乐意之至，{name}。虚空精灵的礼节：虚空得排队。"
L["Asked so nicely, {name}? The Void never says please. Here."] = "问得这么客气，{name}？虚空可从不说“请”。给。"
L["Of course, {name}. Stand in the light, please; the Void gets ideas in corners."] = "当然，{name}。请站到亮处，虚空在角落里容易动歪心思。"
L["Of course, {name}. The Void asked why. I said 'manners'. It's still puzzled."] = "当然，{name}。虚空问为什么。我说“礼貌”。它还没想明白。"
L["Gladly, {name}. Nobody asks us for anything but 'please stop whispering'."] = "乐意之至，{name}。别人找我们，只会说“求你别再嘀咕了”。"
L["Happy to, {name}. Just let me finish arguing with myself. There. I won."] = "乐意效劳，{name}。等我跟自己吵完。好了，我赢了。"
L["Certainly, {name}. I could rift over there first, but that feels showy."] = "当然，{name}。我可以先开个空间裂隙过去，但那样有点显摆。"
L["Asking questions got us exiled, {name}. Answering one is quite safe, I'm told."] = "我们就是因为多问才被流放的，{name}。听说回答问题倒挺安全。"
L["Of course, {name}. A slight chill and a faint chorus are both perfectly normal."] = "当然，{name}。有点发冷、隐约听见合唱，都属正常现象。"
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "送你一丝暗影，{name}。很安全。大概吧。"
L["Walk carefully in the dark places, {name}."] = "行走在黑暗之地要当心，{name}。"
L["A little something from the Telogrus Rift, {name}. It's cleaner than it sounds."] = "泰洛古斯裂隙的一点心意，{name}。比听起来干净。"
L["Take this, {name}. Any tentacles you see are purely decorative."] = "拿着，{name}。看到的触须纯属装饰。"
L["The shadows asked after you, {name}. I told them to mind their manners."] = "暗影向你问好，{name}。我让它们注意礼貌。"
L["Here, {name}. We walked into the Void so you wouldn't have to."] = "给，{name}。我们替你走进了虚空，你就不必去了。"
L["I checked your shadow, {name}. Nothing lurking. Take this anyway."] = "我查过你的影子了，{name}。没藏东西。不过这个还是拿着。"
L["Umbric sends his regards, {name}. He doesn't, but he would."] = "安布里克向你问好，{name}。他没说，但他会的。"
L["Take this, {name}. It may whisper a compliment. Pretend you didn't hear."] = "拿着，{name}。它也许会低声夸你一句。假装没听见就好。"
L["Here, {name}. Looks sinister, works beautifully. Rather like me."] = "给，{name}。看着阴森，效果极好。跟我挺像。"
L["Take this, {name}. The Void had worse in mind for you. I intercepted."] = "拿着，{name}。虚空给你准备的可没这么好。我半路截下了。"
L["If something in the dark whispers your name, {name}, relax. That was me. Here."] = "要是黑暗里有东西低声叫你名字，{name}，别慌。是我。给。"
L["Here, {name}. We ren'dorei don't often get to be the nice surprise."] = "给，{name}。我们虚空精灵难得当回“惊喜”，而不是“惊吓”。"
L["I left Quel'Thalas with only a knack for the dark, {name}. Here's the knack."] = "离开奎尔萨拉斯时，我就带走一手黑暗本事，{name}。给你露一手。"
L["Here, {name}. Don't thank the shadows; they'll only want something. Thank me."] = "给，{name}。别谢暗影，它们只会找你要东西。谢我就好。"
L["I owe a kindness for every ominous look I've given, {name}. I'm badly behind."] = "我每给人一个阴森的眼神，就欠一份善意，{name}。我欠得太多了。"
L["We ren'dorei look after our own, {name}."] = "我们虚空精灵会照顾自己人，{name}。"
L["Silvermoon's loss, {name}. We're doing splendidly without it."] = "那是银月城的损失，{name}。没有它，我们过得好极了。"
L["Your whispers and mine should really meet sometime, {name}."] = "你的低语和我的低语，真该找时间见个面，{name}。"
L["Two ren'dorei in one place, {name}. Quick, look brooding. It's expected."] = "两个虚空精灵碰面了，{name}。快，摆出忧郁脸，大家都等着看。"
L["Nobody else understands the hair, {name}. It was blond once. I think."] = "只有你懂这头发，{name}。它以前是金色的。我记得是。"
L["Telogrus felt like home in the end, {name}. A very draughty, very dark home."] = "泰洛古斯最后也成了家，{name}。一个漏风又漆黑的家。"
L["Ren'dorei to ren'dorei, {name}: what's yours whispering? Mine's on about soup."] = "虚空精灵对虚空精灵，{name}：你的在低语什么？我的在念叨汤。"
L["Stay close, {name}. The whispers are much quieter in company."] = "跟紧点，{name}。有人作伴，低语会安静很多。"
L["If the shadows start giving orders, {name}, ignore them. I usually do."] = "要是暗影开始发号施令，{name}，别理它们。我一般都不理。"
L["Keep an eye on my shadow, {name}. It wanders off when there's a fight."] = "帮我看着我的影子，{name}。一打架它就乱跑。"
L["If I start glowing purple, {name}, carry on. It only means I'm keen."] = "要是我开始发紫光，{name}，别管。那只说明我干劲十足。"
L["We ren'dorei make fine companions, {name}. We bring our own dark to hide in."] = "虚空精灵是好旅伴，{name}。我们自带黑暗，随时能躲。"
L["If I seem to talk to nobody, {name}, I'm fine. If nobody talks back, worry."] = "要是我对着空气说话，{name}，没事。要是空气回嘴了，再担心。"
L["I'll open a rift if it goes wrong, {name}. Only for me, sadly. But I'll wave."] = "情况不妙我就开裂隙，{name}。可惜只能传我自己。但我会挥手的。"
L["Try to enjoy this, {name}. We ren'dorei rarely get invited anywhere twice."] = "好好享受吧，{name}。我们虚空精灵很少被邀请第二次。"
L["Keep the lanterns lit, {name}. I don't need them; the shadows behave better."] = "灯别灭，{name}。我用不着，但有灯暗影会老实点。"
L["Keep an eye on the corners, {name}. I'll keep an eye on what's in them."] = "你盯着角落，{name}。角落里的东西我来盯。"
L["The Void promised me power, {name}. It never mentioned company this good."] = "虚空许诺给我力量，{name}。可没说还有这么好的同伴。"
L["If you hear whispers mid-fight, {name}, they're cheering. For us, I think."] = "打着打着听见低语，{name}，那是在喝彩。给我们喝彩，大概吧。"
L["Should anything eldritch turn up, {name}, let me talk to it. I speak a little."] = "要是冒出什么不可名状的东西，{name}，让我跟它谈。我会说几句。"
L["Night suits the ren'dorei, {name}. We match the decor."] = "夜晚衬虚空精灵，{name}。我们跟夜色是一套的。"
L["The shadows are longest now, {name}, and in a very generous mood."] = "此时暗影最长，{name}，心情也格外大方。"
L["Late, {name}? The whispers love a late hour. Lately, so do I."] = "夜深了，{name}？低语最爱熬夜，最近我也被带坏了。"
L["Midnight, {name}. The one hour my shadow and I agree on anything."] = "午夜了，{name}。只有这时候，我和我的影子意见一致。"
L["Stars out, {name}. I've seen what's between them, and I prefer the stars."] = "星星出来了，{name}。星星之间有什么我见过，还是星星好看。"
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "谢啦，{name}！好意已接收、归档并返还！"
L["Reciprocity engaged! Much obliged, {name}."] = "互惠模式已启动！多谢啦，{name}。"
L["By my calculations, {name}, you're owed exactly one {buff}."] = "据我计算，{name}，你应得的正好是一份{buff}。"
L["Thanks, {name}! I'd build you a thank-you machine, but it'd explode."] = "谢啦，{name}！本想给你造台感谢机，不过它肯定会炸。"
L["Thank you, {name}! This calls for a celebration. Stand back, I'll build one."] = "谢谢你，{name}！这得庆祝一下。退后，我现造一个。"
L["You're too kind, {name}! Returning the favour took only four schematics."] = "你太好了，{name}！还这个人情只画了四张图纸。"
L["Drat, {name}! I was going to invent gratitude, but you beat me to it."] = "可恶，{name}！我本来要发明“感恩”的，被你抢先了。"
L["Oh, {name}, how kind! My heart's doing that whirring thing again."] = "哎呀，{name}，你真好！我的心又开始嗡嗡转了。"
L["Noted in my lab journal, {name}, page four hundred: 'people are lovely'."] = "已记入实验日志，{name}，第四百页：“人们真可爱”。"
L["Splendid, {name}! Returning it at once, before I'm tempted to improve it."] = "太棒了，{name}！马上还你，免得我忍不住要改进它。"
L["Thanks, {name}! Kindness is a reversible reaction. I checked. Here's yours."] = "谢啦，{name}！善意是可逆反应，我验证过了。这是你的。"
L["My mechanostrider would salute you, {name}, but it only knows falling over."] = "我的机械陆行鸟本想向你敬礼，{name}，可它只会摔倒。"
L["My transporter would've sent this to Gadgetzan, {name}. Hand-delivered instead!"] = "用我的传送器，这个准被送到加基森去，{name}。所以亲手送来！"
L["Oh, thank you, {name}! I haven't felt this good since before the troggs."] = "哎呀，谢谢你，{name}！自打穴居人来了以后，我就没这么开心过。"
L["I'll name my next invention after you, {name}! It's a very small cannon."] = "我的下一个发明要用你命名，{name}！是一门很小很小的炮。"
L["Thanks, {name}! Mind the whistle; that's just my gratitude valve venting."] = "谢啦，{name}！别管那声哨响，是我的感恩阀在泄压。"
L["You're on my list of favourite people, {name}! It's short. Mostly clockwork."] = "你上了我的最爱名单，{name}！名单很短，大多是发条玩意儿。"
L["Request received, {name}! Processing... done!"] = "请求已收到，{name}！处理中……完成！"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "升级马上就来，{name}！别动，正在校准。"
L["Of course, {name}! I built a machine for this. It's in pieces, so: by hand."] = "当然，{name}！我专门造了台机器干这个。它散架了，所以：手工。"
L["Certainly, {name}! Stand on the X. There's no X. Stand anywhere."] = "没问题，{name}！站到X上。没有X。随便站吧。"
L["Right away, {name}! Goggles on. Not for you, I just like them."] = "马上，{name}！戴好护目镜。不是给你的，我就是喜欢戴。"
L["{buff}, {name}? Simple in theory AND practice. Suspicious!"] = "{buff}，{name}？理论上简单，实际上也简单。可疑！"
L["Happy to, {name}! Keep hands, feet and eyebrows well clear."] = "乐意效劳，{name}！手、脚和眉毛都离远点。"
L["Right away, {name}! Stand back three paces. Four. Five. There, perfect."] = "马上，{name}！退后三步。四步。五步。嗯，刚刚好。"
L["Happy to, {name}! It beats sorting springs by size. Though that's fun too."] = "乐意，{name}！总比给弹簧按大小排队强。虽然那也挺好玩。"
L["Excellent request, {name}! No moving parts. I'll try to add some next time."] = "好需求，{name}！零活动部件。下回我争取加几个。"
L["Standard model or deluxe, {name}? They're the same. Deluxe sounds nicer."] = "标准版还是豪华版，{name}？其实一样。豪华版听着气派。"
L["Coming up, {name}! Fresh off the workbench, still warm, only slightly smoking."] = "新鲜出炉，{name}！还热乎，只冒了一点点烟。"
L["Approved, {name}! Stamped, signed and filed under 'obviously'."] = "批准，{name}！已盖章、签字，归入“那还用说”类。"
L["Of course, {name}! Adjust the gyromatic... no, wait, that's the squirrel's."] = "当然，{name}！先调陀螺仪……不对，这是机械松鼠的。"
L["Gnomes never refuse a problem, {name}. Occasionally we cause them. Here!"] = "侏儒从不推掉难题，{name}。偶尔还亲手制造。给！"
L["Hold still, {name}, this is perfectly safe. Probably!"] = "别动，{name}，绝对安全。应该吧！"
L["Science says you need this, {name}. Who am I to argue?"] = "科学表明你需要这个，{name}。我哪敢反驳？"
L["A small upgrade for you, {name}. No cogs required."] = "给你个小升级，{name}。无需齿轮。"
L["Take it, {name}, I've a spare. I've three spares of everything."] = "拿着，{name}，我有备用的。每样东西我都备了三份。"
L["Try this, {name}! Version one had legs. Version two is much better."] = "试试这个，{name}！第一版长了腿。第二版好多了。"
L["The High Tinker says share our genius, {name}. Here's a sample!"] = "大工匠说要分享我们的天才，{name}。这是试用装！"
L["Gnomeregan Forever, {name}! This lasts rather less, but it's free."] = "诺莫瑞根永存，{name}！这个存不了那么久，但它免费。"
L["I'm small, {name}, but my gifts come full-sized. Here!"] = "我个子小，{name}，送的礼可是标准尺寸。给！"
L["Don't worry, {name}! It worked on the chicken, and the chicken's thrilled."] = "放心，{name}！在鸡身上试过了，那只鸡乐坏了。"
L["Field test, {name}! You're the lucky volunteer. Everyone's a volunteer, really."] = "实地测试，{name}！你是幸运志愿者。反正人人都“自愿”。"
L["One size fits all, {name}, gnome to tauren. I measured. The tauren was patient."] = "均码，{name}，侏儒到牛头人都合身。我量过，牛头人很耐心。"
L["Take this, {name}! Unlike my Net-o-Matic, it never lands on me."] = "拿着，{name}！它不像我的撒网器，从不罩住我自己。"
L["The Gnomish Army Knife does twelve things badly, {name}. This does one well."] = "侏儒军刀十二样功能样样不灵，{name}。这个就一样，但好用。"
L["Guarantee void if exposed to troggs, dragonfire or enthusiasm, {name}. Enjoy!"] = "遇穴居人、龙焰或热情即失去保修，{name}。请慢用！"
L["Nothing up my sleeves, {name}! Well, a spanner and two fuses. Nothing sinister."] = "袖里空空，{name}！呃，就一把扳手、两根引信。绝无恶意。"
L["Here, {name}! It's small, but so is a keystone, and look what those hold up."] = "给，{name}！别嫌小，拱心石也不大，整座拱门全靠它撑着。"
L["I'd explain how it works, {name}, but that takes three days and a chalkboard."] = "原理我可以讲，{name}，不过得三天外加一块黑板。"
L["If you hear ticking, {name}, that's my pocket watch. Almost certainly."] = "要是听见滴答声，{name}，那是我的怀表。基本可以肯定。"
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "为了诺莫瑞根，{name}！能平视着聊天真好。"
L["A fellow gnome, {name}! I'll hold the schematic; you hold the bucket."] = "同为侏儒，{name}！我拿图纸，你拎水桶。"
L["Flesh or cogs, {name}, we're all gnomes. Some of us just need oiling."] = "血肉也好，齿轮也罢，{name}，都是侏儒。只是有的得上点油。"
L["One gnome to another, {name}: you did turn the reactor off, didn't you?"] = "侏儒对侏儒，{name}：你真的关了反应堆吧？对吧？"
L["Two gnomes, {name}! Stacked up, we're very nearly a night elf."] = "两个侏儒，{name}！叠起来差不多就是一个暗夜精灵了。"
L["You check my sums, {name}, I check yours, and we're both quietly offended."] = "你验我的算，{name}，我验你的，然后双双暗自生气。"
L["You still owe me a sprocket, {name}. Every gnome owes me a sprocket."] = "你还欠我一个小齿轮，{name}。每个侏儒都欠我一个。"
L["One day, {name}, we'll walk back into Gnomeregan together. With the lights on."] = "总有一天，{name}，我们会一起走回诺莫瑞根。开着灯。"
L["Between gnomes, {name}: we both know it'll explode, and we both want to watch."] = "侏儒之间说实话，{name}：咱俩都知道它会炸，也都想看。"
L["Shall we build something huge, {name}? Just to see the tall folk's faces?"] = "要不要造个巨无霸，{name}？就为了看看高个子们的表情？"
L["Party-wide calibration complete, {name}! Nobody touch anything shiny."] = "全队校准完毕，{name}！谁都别碰亮晶晶的东西。"
L["I've run the numbers, {name}: with you here, we win. I rounded up."] = "我算过了，{name}：有你在，我们赢定了。四舍五入一下。"
L["If I shout 'duck', {name}, don't look for a duck. That went badly last time."] = "我喊“快闪”，{name}，是让你躲，不是跳舞。上回可惨了。"
L["Formation, {name}: tall folk at the front, me somewhere safe and clever."] = "阵型，{name}：高个子站前面，我待在安全又聪明的地方。"
L["Everyone gets one, {name}! Standardised parts are the secret of a good machine."] = "人人有份，{name}！标准化零件是好机器的秘诀。"
L["My plan, {name}: step one, survive. Step two is still in development."] = "我的计划，{name}：第一步，活下来。第二步还在研发中。"
L["Don't panic, {name}. Whatever goes wrong, I'll have a gadget for it. Next week."] = "别慌，{name}。不管出什么岔子，我都会有对应的小发明。下周。"
L["If I vanish, {name}, check under the nearest boot. Politely, please."] = "我要是不见了，{name}，就看看最近的靴子底下。客气点。"
L["When this is over, {name}, I want samples. Of everything. The big one first."] = "打完了，{name}，我要采样。全都要。大家伙优先。"
L["Every explosion today, {name}, is on purpose. I'll decide which ones later."] = "今天每次爆炸都是故意的，{name}。哪些是故意的，我回头再定。"
L["Group trial under way, {name}! No control group. Everybody gets the good stuff."] = "集体试验开始，{name}！没有对照组，人人都有好东西。"
L["If we get separated, {name}, follow the smoke. It'll be me."] = "要是走散了，{name}，就跟着烟走。那就是我。"
L["Everyone keep their fingers, {name}. I've counted. I'll count again after."] = "大家看好自己的手指，{name}。我数过了，完事再数一遍。"
L["Morning, {name}! Up since three. The toaster needed a new engine."] = "早，{name}！我三点就起了，烤面包机得换个新引擎。"
L["Good morning, {name}! The coffee's brewing itself. It learned how. Worrying."] = "早上好，{name}！咖啡在自己煮自己。它学会了。有点担心。"
L["Early start, {name}! Best ideas come before breakfast. So do the explosions."] = "起得早啊，{name}！好点子都在早饭前冒出来。爆炸也是。"
L["Morning, {name}! My alarm clock went off at six. Exploded, I mean. Effective!"] = "早，{name}！闹钟六点就响了。轰的一声那种。叫醒效果一流！"
L["Up early, {name}? I dreamt of a better sprocket and couldn't wait. Here!"] = "起这么早，{name}？我梦见一个更好的齿轮，等不及了。给！"
L["Morning, {name}! The sun's a bit dim today. I've been meaning to fix that."] = "早，{name}！今天太阳有点暗。我一直打算修修它。"
L["The Light rewards kindness, {name}. I'm simply its fastest courier."] = "圣光会回报善意，{name}。我只是它最快的信使。"
L["Archenon poros, {name}. Your gift is returned."] = "Archenon poros，{name}。你的馈赠，我来回报。"
L["Thanks, {name}. I'd offer a lift in the Exodar, but you've seen how it lands."] = "谢了，{name}。本想让你搭埃索达，可你见过它是怎么着陆的。"
L["A gift freely given, {name}. The naaru hum a little louder. Returned."] = "无私的馈赠，{name}。纳鲁的嗡鸣都响了些。回赠你。"
L["Kindly done, {name}. On Argus we'd have carved that in crystal. Here."] = "好心肠，{name}。在阿古斯，这事得刻进水晶里。给。"
L["Across a dozen worlds, {name}, kindness is the one tongue I never had to learn."] = "走过十几个世界，{name}，善意是我唯一不用学的语言。"
L["What a kindness, {name}. It almost makes up for the Legion. Almost."] = "真是好心，{name}。差点就抵得过燃烧军团欠的账了。差点。"
L["Thank you, {name}. I'd say it in Draenei, but that takes eleven minutes."] = "谢谢你，{name}。用德莱尼语说得花十一分钟。"
L["Thank you, {name}. The Exodar crashed; my manners didn't. Here."] = "谢谢你，{name}。埃索达坠了，我的礼数可没坠。给。"
L["Sargeras once offered my people gifts, {name}. We ran. Yours, I'll keep."] = "萨格拉斯也给我族送过礼，{name}。我们跑了。你的，我收下。"
L["Thank you, {name}. I've fled demons across the stars, but never from a debt."] = "谢谢你，{name}。我躲恶魔躲过了星海，但从不躲债。"
L["Thank you, {name}. I'll add you to my prayers. The list goes back to Argus."] = "谢谢你，{name}。我会为你祈祷。名单从阿古斯就开始排了。"
L["The Legion took a world from us, {name}. Folk like you keep giving bits back."] = "燃烧军团抢走一个世界，{name}，好心人正一点点还给我们。"
L["You gave first, {name}. A prophet would call it an omen. I call it manners."] = "你先给的，{name}。先知会说这是预兆，我说这是礼数。"
L["With the Light's compliments, {name}. It asked me to add 'nicely done'."] = "圣光向你致意，{name}。它还让我补一句：“干得漂亮”。"
L["Of course, {name}. The naaru guide your steps; this puts a spring in them."] = "当然，{name}。纳鲁指引你的脚步，这个让它更轻快。"
L["Gladly, {name}. The Light answers those who ask."] = "乐意之至，{name}。圣光会回应祈求之人。"
L["Velen foresaw you asking, {name}. I foresaw saying yes."] = "维伦预见了你会开口，{name}。我预见了我会答应。"
L["The Light is not rationed, {name}. Take as much as you like."] = "圣光不限量供应，{name}。随便拿。"
L["Of course, {name}. I've outrun the Burning Legion; I can manage this."] = "当然，{name}。燃烧军团我都跑赢了，这点事不在话下。"
L["At once, {name}. Hooves planted, crystals humming, here it comes."] = "马上，{name}。蹄子站稳，水晶嗡鸣，来了。"
L["Gladly, {name}. I followed a talking crystal across the stars. This is easy."] = "乐意，{name}。我跟着会说话的水晶穿越星海，这算什么。"
L["Certainly, {name}. Velen taught us patience. Luckily, this takes none."] = "当然，{name}。维伦教会我们耐心。幸好这个用不着。"
L["Gladly, {name}. The naaru never say no. They say 'hmmm', but it means yes."] = "乐意，{name}。纳鲁从不说不，只会“嗡——”，意思是行。"
L["On the Exodar this took three crystals and a prayer, {name}. Here: the prayer."] = "在埃索达，这得三块水晶加一段祷文，{name}。祷文给你。"
L["Of course, {name}. I only refuse demons, and they so rarely say please."] = "当然，{name}。我只拒绝恶魔，而它们几乎从不说“请”。"
L["Gladly, {name}. We were refugees long enough to know what asking costs."] = "乐意之至，{name}。我们流亡太久，知道开口求人有多难。"
L["Of course, {name}. My people crossed the stars looking for friends. Found one."] = "当然，{name}。我族跨越星海寻找朋友。找到一个了。"
L["Ask a draenei, {name}: one yes, one blessing, possibly a history lesson."] = "找德莱尼，{name}：一声好、一份祝福，没准加堂历史课。"
L["The Light is with you, {name}. Go in peace, or at least go prepared."] = "圣光与你同在，{name}。平安前行，至少有备而行。"
L["Walk in the Light, {name}. May it shelter you always."] = "行于圣光之中，{name}。愿它永远庇护你。"
L["Take this, {name}. My people always travel Light."] = "拿着，{name}。我族出门向来轻装：只装圣光。"
L["Take this, {name}. The Legion is always coming. I'd know."] = "拿着，{name}。燃烧军团总会再来。我最清楚。"
L["I'm out of miracles today, {name}. Will {buff} do?"] = "今天的奇迹用完了，{name}。{buff}凑合一下？"
L["For the road, {name}. Mine has been twenty-five thousand years long."] = "路上用吧，{name}。我这条路已经走了两万五千年。"
L["Blessed by a naaru, {name}. Well, I stood near one. It still counts."] = "受过纳鲁祝福，{name}。好吧，我在一位旁边站过。也算。"
L["Take this, {name}. It glows a bit. Everything we own does."] = "拿着，{name}。它有点发光。我们的东西都这样。"
L["Here, {name}. We draenei pack for the end of the world. We've had the practice."] = "给，{name}。我们德莱尼打包都按世界末日准备。练过好几回了。"
L["Take this, {name}. I've stayed a step ahead of demons for ages. Now you're two."] = "拿着，{name}。我一直领先恶魔一步。现在你领先两步。"
L["The naaru shine on all, {name}. They're dreadful at aiming. I'm helping."] = "纳鲁普照众生，{name}。可惜准头太差，我来帮帮忙。"
L["A stranger shared bread with me on Azuremyst, {name}. I'm still paying it back."] = "在秘蓝岛，有个陌生人分过我面包，{name}。我到现在还在还。"
L["Velen sees a thousand futures, {name}. I see one: you, better prepared. Here."] = "维伦能看见千种未来，{name}。我只看见一种：你准备得更好。"
L["Don't drink from the streams on Bloodmyst, {name}. Do take this."] = "秘血岛的溪水别喝，{name}。这个尽管拿。"
L["Eredar magic from before the fall, {name}. We only kept the good kind. Here."] = "堕落之前的艾瑞达魔法，{name}。我们只留下了好的那种。给。"
L["Archenon poros, {name}! The children of Argus look after one another."] = "Archenon poros，{name}！阿古斯的子民互相照应。"
L["Home is wherever two draenei meet, {name}. Today, it's here."] = "两个德莱尼相遇之处便是家，{name}。今天，就是这里。"
L["Horns high, {name}. Two draenei, and nobody's mentioned the Legion. Progress."] = "犄角高昂，{name}。两个德莱尼碰面没提燃烧军团。进步了。"
L["Tails up, {name}. Argus would be proud of what we've made of exile."] = "尾巴翘起来，{name}。我们把流亡过成这样，阿古斯会骄傲的。"
L["Two draenei, {name}, and between us nearly fifty thousand years of worrying."] = "两个德莱尼，{name}，加起来快五万年的操心。"
L["Horns, hooves and hope, {name}. The Legion never found a cure for any of them."] = "犄角、蹄子和希望，{name}。燃烧军团哪样都没治好。"
L["Children of Velen, {name}: exiled, hopeful and dreadfully polite."] = "维伦的子民，{name}：流亡、乐观，还客气得要命。"
L["Third world's the charm, {name}. We draenei are owed one that stays put."] = "事不过三，{name}。我们德莱尼总该有个待得住的世界了。"
L["Stay near, {name}. I lost a world once; I'm keeping hold of this party."] = "靠近点，{name}。我丢过一个世界，这支小队我可要抓牢。"
L["Twenty-five thousand years on the run, {name}. Walking with friends is nicer."] = "逃了两万五千年，{name}。还是和朋友一起走更好。"
L["The naaru would call this a fellowship, {name}. I call it good luck."] = "纳鲁会称之为同道之谊，{name}。我叫它好运气。"
L["I've watched worlds end, {name}. Whatever's ahead of us hardly worries me."] = "我见过世界毁灭，{name}。前面不管有什么，我都不太担心。"
L["Stay together, {name}. The Light finds us easier when we're all in one place."] = "待在一起，{name}。大家聚在一处，圣光找起来更方便。"
L["Stay close, {name}. We draenei are very good at leaving places in a hurry."] = "靠近点，{name}。说到跑路，我们德莱尼可是专家。"
L["We draenei take the long view, {name}. From up here, this fight is very short."] = "我们德莱尼看得长远，{name}。从这个高度看，这场仗很短。"
L["Let me go first, {name}. Anything watching will see a very tall optimist."] = "我打头阵，{name}。暗处的东西只会看见一个很高的乐天派。"
L["We draenei follow prophets, {name}. Today I'll settle for following you."] = "我们德莱尼追随先知，{name}。今天先知请假，我跟你走。"
L["The Exodar carried thousands, {name}, and this little party still feels safer."] = "埃索达载过成千上万人，{name}，可这支小队更让我安心。"
L["Shoulder to shoulder, {name}. Mine's a bit higher, but the principle holds."] = "肩并肩，{name}。我的肩高了点，但道理一样。"
L["A prayer for the party, {name}. The short one. The long one ends next age."] = "为小队祈祷一下，{name}。念短的那篇。长的要念到下个纪元。"
L["Much obliged, {name}. Gilneas never forgets a kindness, and nor does my nose."] = "多谢，{name}。吉尔尼斯永不忘恩，我的鼻子也是。"
L["Thank you, {name}. You have my gratitude, and my best howl."] = "谢谢你，{name}。感激不尽，再送你一声狼嚎！"
L["Thank you, {name}. If worgen had tails, mine would be wagging."] = "谢谢你，{name}。狼人要是有尾巴，我的早摇起来了。"
L["You've made a friend for life, {name}. Loyalty is rather our thing."] = "你交了个一辈子的朋友，{name}。忠诚可是我们的看家本领。"
L["The beast in me wants to growl, {name}. The Gilnean in me insists on thanks."] = "我心里的野兽想咆哮，{name}。我心里的吉尔尼斯人坚持要道谢。"
L["Much appreciated, {name}. I'd shake your hand, but, claws. Here instead."] = "多谢，{name}。本想握手，可是……爪子。给你这个吧。"
L["We walled ourselves off for years, {name}. You make that look silly."] = "我们筑墙自守多年，{name}。你让那堵墙显得真傻。"
L["Obliged, {name}. You've earned a spot by the fire. The good spot."] = "承情，{name}。炉火边有你一个位置。最好的那个。"
L["Thank you, {name}. In return, I'll never chase your mount. Well, rarely."] = "谢谢你，{name}。作为回报，我绝不追你的坐骑。呃，很少追。"
L["Returned, {name}, with a stiff upper lip. The lower one shows teeth; ignore it."] = "如数奉还，{name}，绅士风度不变。至于龇出来的牙，别在意。"
L["Thank you, {name}. I'd tip my hat, but it doesn't fit over the ears these days."] = "谢谢你，{name}。本想脱帽致意，可如今帽子套不下这对耳朵了。"
L["Thank you, {name}. Most folk just scratch my ears and hope for the best."] = "谢谢你，{name}。大多数人只会挠挠我耳朵，然后祈祷别出事。"
L["Returned, {name}. A Gilnean pays debts; a worgen pays them at a sprint."] = "还你，{name}。吉尔尼斯人欠债必还，狼人还得飞快。"
L["Spoiled twice today, {name}, and the first time was a biscuit. Thank you."] = "今天被宠了两回，{name}，头一回是块饼干。谢谢你。"
L["Certainly, {name}. Hold still, I don't bite. Much."] = "当然，{name}。别动，我不咬人。不怎么咬。"
L["Right you are, {name}. Stand steady now."] = "没问题，{name}。站稳了。"
L["Right away, {name}. Stay, now. I've always wanted to say that."] = "马上，{name}。待着，别动。这话我一直想对别人说。"
L["Gladly, {name}. Rain or shine, and in Gilneas it's rain."] = "乐意之至，{name}。风雨无阻，反正吉尔尼斯只有雨。"
L["Certainly, {name}. I'll try not to shed on you."] = "当然，{name}。我尽量不掉毛在你身上。"
L["Say no more, {name}. These ears heard you before you'd decided to ask."] = "不用多说，{name}。你还没决定开口，这对耳朵就听见了。"
L["Of course, {name}. You asked nicer than the last fellow who threw me a stick."] = "当然，{name}。你比上次冲我扔木棍的家伙客气多了。"
L["Glad to, {name}. Few people ask a seven-foot wolf for favours. I love it."] = "乐意，{name}。很少有人找一头七尺高的狼帮忙。我太喜欢了。"
L["Certainly, {name}. I'll stay in this form. The other one causes a scene."] = "当然，{name}。我就保持这个样子。另一个样子容易引起围观。"
L["Tea first? No? Straight to business, {name}. How very un-Gilnean. Here."] = "不先喝茶？直奔正题啊，{name}，太不吉尔尼斯了。给。"
L["Of course, {name}. Excuse the damp. Nothing smells quite like a wet worgen."] = "当然，{name}。见谅，身上有点潮。湿透的狼人，味道独一份。"
L["Of course, {name}. I'll try not to sniff. I will fail, but I'll try."] = "当然，{name}。我尽量不闻你。肯定忍不住，但我尽量。"
L["Of course, {name}. Anything but a bath."] = "当然，{name}。只要别让我洗澡就行。"
L["Stay off the moors after dark, {name}. Take this."] = "天黑后别去荒原，{name}。拿着这个。"
L["Keep your wits about you, {name}. Something is always hunting."] = "保持警惕，{name}。总有东西在狩猎。"
L["I'd have brought this sooner, {name}, but I stopped to chase something."] = "本该早点送来的，{name}，可我半路去追了个东西。"
L["For you, {name}. No, I don't want a treat. Well. Perhaps a small one."] = "给你的，{name}。不，我不要零食。好吧，要一点点。"
L["Gilneans always offer, {name}. The claws are just part of the outfit."] = "吉尔尼斯人向来乐于助人，{name}。爪子只是行头的一部分。"
L["An old Gilnean remedy, {name}. Good for colds, gloom and most curses. Not mine."] = "吉尔尼斯老偏方，{name}。治感冒、郁闷和多数诅咒。我的除外。"
L["Run with this, {name}. Trust me, I know about running."] = "带着它跑吧，{name}。信我，跑这事我懂。"
L["Fetched this for you, {name}. Don't make a thing of it."] = "给你叼回来了，{name}。别当回事。"
L["Here, {name}. That's why I was following you. Honestly. I'll stop now."] = "给，{name}。我跟着你就是为了这个。真的。这就不跟了。"
L["For you, {name}. Not everything that prowls was as well raised as I was."] = "给你的，{name}。在外头游荡的，可不都像我这么有家教。"
L["From a Gilnean of good family, {name}. The fur is new; the manners are old."] = "出自吉尔尼斯名门，{name}。毛是新长的，教养是祖传的。"
L["I thought of this in a dream, {name}. I was also chasing a rabbit. Here."] = "这是我梦里想到的，{name}。当时我还在追兔子。给。"
L["Liam would have cried 'For Gilneas!', {name}. I'll just say: for you."] = "里亚姆会高呼“为了吉尔尼斯！”，{name}。我只说：为了你。"
L["Tal'doren's druids taught me to leash the beast, {name}. Now it fetches. Here."] = "塔尔多伦的德鲁伊教我拴住野兽，{name}。现在它会叼东西了。给。"
L["Be careful out there, {name}. Take it from someone who was bitten once."] = "外面当心，{name}。听听过来人的话：我被咬过。"
L["Here, {name}. I'd leave it on your doorstep, but that frightens people."] = "给，{name}。本想放你家门口，可那样会吓到人。"
L["Take this, {name}. I'd offer my coat, but it's attached."] = "拿着，{name}。本想把大衣给你，可它长在我身上。"
L["Here, {name}. Chin up, hackles down. Words to live by."] = "给，{name}。昂首挺胸，颈毛放平。至理名言。"
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "诅咒缚住我们，{name}，吉尔尼斯缚得更紧。"
L["No need to explain the ears to you, {name}."] = "这对耳朵，就不用跟你解释了，{name}。"
L["Fur, fog and rain, {name}. Only a Gilnean understands all three."] = "毛、雾、雨，{name}。只有吉尔尼斯人三样全懂。"
L["Pack looks after pack, {name}. Always has."] = "狼群照顾狼群，{name}。向来如此。"
L["Do you shed this badly too, {name}? Between us we could knit a third worgen."] = "你也掉毛这么厉害吗，{name}？咱俩的毛够织出第三个狼人了。"
L["Two worgen, {name}. Somewhere, a cat's having a very bad day."] = "两个狼人，{name}。某处有只猫今天要倒大霉了。"
L["Honestly, {name}, do you ever forget which form you left home in?"] = "说真的，{name}，你出门时会忘了自己是哪种形态吗？"
L["Gilnean to Gilnean, {name}: the finest-mannered wolves in all Azeroth."] = "吉尔尼斯人对吉尔尼斯人，{name}：全艾泽拉斯最有礼貌的狼。"
L["Pack rules, {name}: nobody wanders off, and nobody mentions the fleas."] = "狼群规矩，{name}：谁也别乱跑，谁也别提跳蚤。"
L["A pack again, {name}. I hadn't known how much I'd missed one."] = "又有狼群了，{name}。我都不知道自己有多想念。"
L["I'll catch the scent of trouble first, {name}. It's the one perk of the curse."] = "麻烦的味道我先闻到，{name}。这是诅咒唯一的好处。"
L["If I howl, {name}, it's a battle cry. Probably. Don't look at me like that."] = "要是我嚎起来，{name}，那是战吼。大概吧。别那样看我。"
L["Lead on, {name}. I'll trot. It's undignified, but it's much quicker."] = "你带路，{name}。我四脚小跑。不太体面，但快多了。"
L["If I stop and stare at a wall, {name}, something's behind it. Or it's a wall."] = "要是我停下来盯着墙，{name}，那后面有东西。或者只是面墙。"
L["Years on the Greymane Wall, {name}. Holding a line with you is a holiday."] = "我在格雷迈恩之墙守了好多年，{name}。跟你守条防线就像度假。"
L["After this, {name}, a proper cup of tea. Before this, a proper mauling."] = "先好好撕咬一场，{name}，再好好喝杯茶。"
L["If I limp back, {name}, I'll make big sad eyes. Don't fuss. I'm fine."] = "要是我瘸着回来，{name}，会眼巴巴看着你。别管，我没事。"
L["Short rest? I'll curl up, {name}, after three turns. The turns aren't optional."] = "歇一会儿？我先转三圈再趴下，{name}。转圈不能省。"
L["Stay together, {name}. I was a lone wolf once. Dreadful pay, nobody talks."] = "别走散，{name}。我当过独狼。工资太低，没人说话。"
L["Night again, {name}. I'm at my best and my worst. This is the best part."] = "又入夜了，{name}。夜里我最好也最糟。这会儿是最好。"
L["Look at that moon, {name}. Don't mind me; I'm not howling. Much."] = "看那月亮，{name}。别在意，我没在嚎。没怎么嚎。"
L["Gilneas at night was fog and footsteps, {name}. These days I'm the footsteps."] = "夜里的吉尔尼斯只有雾和脚步声，{name}。如今，我就是那脚步声。"
L["Curfew in Gilneas was sundown, {name}. For good reason, as it turned out."] = "吉尔尼斯日落就宵禁，{name}。事后看来，理由很充分。"
L["Something out there keeps rustling, {name}. I'm not going to look. I'm looking."] = "外面有东西一直在沙沙响，{name}。我不看。我在看了。"
L["Past dark, {name}: ears up, nose working, manners on. Two out of three will do."] = "天黑了，{name}：竖耳朵，开鼻子，讲礼貌。三样占两样就行。"
L["Morning, {name}. I'd have been up sooner, but the rug by the fire was so warm."] = "早，{name}。本该早起的，可炉火边的地毯太暖和了。"
L["Smells like rain this morning, {name}. Everything in Gilneas smelled like rain."] = "今早有雨的味道，{name}。吉尔尼斯的一切都是雨的味道。"
L["Up already, {name}? I've chased two rabbits. For exercise. Purely."] = "起这么早，{name}？我已经追了两只兔子。纯属锻炼。"
L["Morning, {name}. Tea, toast, a shave. The shave takes rather longer now."] = "早，{name}。喝茶、吃吐司、刮胡子。刮胡子现在可费工夫了。"
L["Morning, {name}. The birds woke me, so I woke the birds. It seemed only fair."] = "早，{name}。鸟把我吵醒了，我也把鸟吵醒了。礼尚往来嘛。"
L["Morning, {name}. The squirrels are taunting me. Quickly, before I'm distracted."] = "早，{name}。松鼠在挑衅我。快点，趁我还没分心。"
L["Throm-ka, {name}! Honour is repaid."] = "Throm-ka，{name}！恩义已还。"
L["You give freely, {name}. I return the favour."] = "你慷慨相助，{name}。这个人情我还你。"
L["Orcs keep their thanks short, {name}. Thanks."] = "兽人道谢从不啰嗦，{name}。谢了。"
L["Orcs return every blow twice, {name}. The kind ones too."] = "兽人挨一下还两下，{name}。好意也一样。"
L["You helped me, I help you. Orc poetry, {name}. It doesn't rhyme."] = "你帮我，我帮你。兽人的诗，{name}。不押韵。"
L["In the old days I'd have repaid you with a boar, {name}. This keeps better."] = "放在从前，我会拿头野猪还你，{name}。这个更耐放。"
L["Owing somebody itches worse than Durotar sand, {name}. There. Itch gone."] = "欠人情比杜隆塔尔的沙子还痒，{name}。好了，不痒了。"
L["Strong stuff, {name}. I could wrestle a kodo now. So can you."] = "好东西，{name}。我现在能摔倒一头科多兽。你也行。"
L["Ambushed by kindness, {name}. No orc trains for that. Returned in full."] = "被好意伏击了，{name}。兽人可没练过这个。如数奉还。"
L["Honour is a debt, {name}. Orcs pay on the spot, before we forget what for."] = "荣誉是一笔债，{name}。兽人当场就还，免得忘了为啥欠。"
L["An orc remembers a kindness like a scar, {name}: fondly, and for good."] = "兽人记恩情跟记伤疤一样，{name}：好了也不忘，还挺怀念。"
L["I'd give you my axe, {name}, but we're not that close yet. Take this."] = "本想把斧子送你，{name}，可咱俩还没那么熟。拿这个吧。"
L["Thanks, {name}. My wolf growled at you. That's how he says it."] = "谢了，{name}。我的狼冲你吼了一声。那是它在道谢。"
L["I've had gifts from shamans, chieftains and one lost kodo, {name}. Yours wins."] = "萨满、酋长和一头迷路的科多兽都送过我礼，{name}。你的最好。"
L["We once took strength from demons, {name}. Yours comes on far better terms."] = "我们从恶魔那儿拿过力量，{name}。你给的条件可好多了。"
L["The spirits saw that, {name}. My shaman says they approve. Of you, anyway."] = "先祖之灵看见了，{name}。我的萨满说它们很满意。至少对你是。"
L["I'll carve that on my axe handle, {name}. Next to the notches. Thank you."] = "我会把这事刻在斧柄上，{name}。就刻在那排刻痕旁边。谢了。"
L["A kindness, {name}? Hm. My face is doing something. I think it's a smile."] = "好意，{name}？嗯。我脸上有点动静。应该是在笑。"
L["In my clan a gift gets a bigger one back, {name}. Don't make me escalate."] = "在我们氏族，收了礼要回个更大的，{name}。别逼我升级。"
L["Dabu, {name}. It is done."] = "Dabu，{name}。办妥了。"
L["Hold still, {name}. Strength for the fight ahead."] = "别动，{name}。为前方的战斗添些力量。"
L["Ask an orc for help and you get it, {name}. Ask for subtlety and you wait."] = "找兽人帮忙，{name}，马上就有。找兽人讲委婉，慢慢等吧。"
L["Help, yes. Hugging, no. Hold still, {name}."] = "帮忙，行。拥抱，不行。别动，{name}。"
L["You want {buff}? You have {buff}, {name}. Next."] = "要{buff}？给你{buff}，{name}。下一个。"
L["Don't flinch, {name}. My helping face looks exactly like my fighting face."] = "别躲，{name}。我帮忙时的脸和打架时一模一样。"
L["Short question, short answer, {name}: yes."] = "问得短，答得也短，{name}：行。"
L["Work complete, {name}. I started out as a peon; the words never leave you."] = "工作完成，{name}。我是苦工出身，这句话一辈子忘不掉。"
L["A challenge, {name}? Oh, a request. Close enough. I accept either way."] = "挑战，{name}？哦，是请求。差不多。反正我都接。"
L["Yes, {name}. I was sharpening my axe, but it'll keep. It always keeps."] = "行，{name}。斧子正磨着呢，不急。磨斧不误帮忙工。"
L["In the Valley of Honor this would cost you a duel, {name}. For you, a nod."] = "在荣誉谷，这得跟你决斗一场，{name}。对你嘛，点个头就行。"
L["Now, {name}? Now. Orcs never learned the word 'later'."] = "现在？就现在，{name}。兽人不懂“待会儿”。"
L["One {buff}, {name}. Orc style: fast, direct, a bit too hard."] = "一份{buff}，{name}。兽人风格：快、直接、下手稍重。"
L["Stand still, {name}. I aim this like a throwing axe, and I rarely miss."] = "站好别动，{name}。我瞄这个跟扔飞斧一样，很少失手。"
L["Lok'tar, {name}. It means 'victory'. Today it also means 'yes'."] = "Lok'tar，{name}。意为“胜利”。今天也意为“行”。"
L["Lok'tar ogar, {name}! Take this into battle. A tavern brawl also counts."] = "Lok'tar ogar，{name}！带着它上战场！酒馆斗殴也算。"
L["Blood and thunder, {name}! Go and earn your glory."] = "鲜血与雷霆，{name}！去挣你的荣耀吧！"
L["Among orcs, {name}, making you stronger is how we say we like you."] = "在兽人这儿，{name}，让你变强就是在说喜欢你。"
L["An orc giving gifts unasked? Tell no one, {name}. It ruins the image."] = "兽人主动送礼？别告诉别人，{name}。有损形象。"
L["I was told to be more diplomatic, {name}. This is me being diplomatic."] = "有人叫我讲究点外交，{name}。这就是我的外交。"
L["Go hit something for me, {name}. Or set it on fire. Orcs aren't fussy."] = "替我去揍点什么，{name}。或者放把火。兽人不挑。"
L["Don't thank me, {name}. Just win, and do it loudly."] = "别谢我，{name}。赢就行，赢得响亮点。"
L["I'd make a speech, {name}, but it's mostly shouting. Just take it."] = "本想发表演讲，{name}，可基本都是吼。直接拿着吧。"
L["You looked like you needed an orc, {name}. Everybody does, sooner or later."] = "你看起来需要一个兽人，{name}。谁都有这一天，早晚而已。"
L["'Strike first,' Grom always said, {name}. So: here, before you could ask."] = "格罗姆常说“先下手为强”，{name}。所以：给，趁你还没开口。"
L["Take it, {name}. A grunt who walks past a comrade gets a talking-to. From me."] = "拿着，{name}。步兵对战友视而不见，是要挨训的。我来训。"
L["Frostwolves share the hunt, {name}. I caught nothing today, so share this."] = "霜狼分享猎物，{name}。今天我什么都没打到，就分你这个吧。"
L["Walk the Durotar way, {name}: head up, sun on your neck, scorpid underfoot."] = "走杜隆塔尔的路子，{name}：抬起头，晒着脖子，脚下踩蝎子。"
L["Here, {name}. The spirits love generosity. My axe says nothing; it sulks."] = "给，{name}。先祖之灵喜欢慷慨。我的斧子不吭声，在生闷气。"
L["Orcs give two things freely, {name}: advice and this. Skip the advice."] = "兽人有两样东西白送，{name}：建议和这个。建议就免了。"
L["The Barrens don't end, {name}. They just get more zhevra. Take this."] = "贫瘠之地没有尽头，{name}，只有越来越多的斑马。拿着。"
L["Strength for your arm, {name}. The honour, I see, you brought yourself."] = "给你的胳膊添点力气，{name}。至于荣誉，看得出你自带了。"
L["My wolf wanted you to have his bone, {name}. I talked him down to this."] = "我的狼想把它的骨头送你，{name}。我劝它换成了这个。"
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "Throm-ka，{name}！氏族之血在你身上奔涌！"
L["An orc, {name}! Finally, somebody who shouts at my volume."] = "兽人，{name}！终于有人跟我一个嗓门了。"
L["Frostwolf, Warsong or Blackrock, {name}, we all argue like family."] = "霜狼、战歌还是黑石，{name}，吵起来都像一家人。"
L["Between orcs no words are needed, {name}. Good. I was out of them."] = "兽人之间无需多言，{name}。正好，我也没词了。"
L["Green skin or brown, {name}, it's the same stubborn blood."] = "绿皮也好棕皮也罢，{name}，流的都是一样倔的血。"
L["Two orcs, {name}, and nobody's shouted yet. The shamans will call it an omen."] = "两个兽人，{name}，居然还没人吼。萨满会说这是个兆头。"
L["Our clans probably feuded once, {name}. Everybody's did. Let's call it settled."] = "咱们的氏族八成结过仇，{name}。谁家都结过。就当两清了。"
L["Between orcs, {name}, 'victory or death' is just how we say 'see you later'."] = "兽人之间，{name}，“胜利或死亡”就是“回头见”。"
L["Your tusks and mine have seen worse days, {name}. This is a better one."] = "你我的獠牙都见过更糟的日子，{name}。今天算好的。"
L["The plan, {name}: we hit it. Questions? No? Good plan."] = "计划，{name}：揍它。有问题吗？没有？好计划。"
L["A true warband, {name}. Loud, angry, and all on the same side for once."] = "真正的战团，{name}。又吵又凶，而且难得都站在一边。"
L["Stay with the warband, {name}. Strength in numbers. And in axes."] = "跟紧战团，{name}。人多力量大。斧子多力量更大。"
L["If you fall, {name}, I carry you out. Complaining the whole way, but I carry."] = "你要是倒下，{name}，我扛你出去。一路抱怨，但一定扛。"
L["Fight well, {name}, and tonight you share our fire. And our boasting."] = "好好打，{name}，今晚篝火有你一份。吹牛也有你一份。"
L["Nobody runs, {name}. Walking briskly away is allowed. Barely."] = "谁都不许跑，{name}。快步走开可以。勉强可以。"
L["I'll go first, {name}. I have the thickest skull here, and I'm proud of it."] = "我先上，{name}。这儿就数我头最铁，我骄傲。"
L["When the war drums start, {name}, charge. We have no drums. I'll hum."] = "战鼓一响，{name}，就冲。我们没鼓，我来哼。"
L["Watch my back, {name}. The front I can see; that's the part I hit."] = "看好我背后，{name}。前面我看得见，那是我负责砸的。"
L["One clan today, {name}: the Clan of Whoever Showed Up. Finest there is."] = "今天只有一个氏族，{name}：到场氏族。天下第一。"
L["Anything big comes through that door, {name}, it's mine. Anything bigger, ours."] = "从那扇门进来的大家伙，{name}，归我。更大的，归咱们。"
L["Scars are stories, {name}. Let's all come out of this with short ones."] = "伤疤就是故事，{name}。这次咱们都只带短篇回去。"
L["Old chieftains had war councils, {name}. We have me pointing at things."] = "老酋长有作战会议，{name}。我们有我：指哪打哪。"
L["If I charge early, {name}, it isn't impatience. It's tradition."] = "要是我提前冲锋，{name}，那不是急躁。是传统。"
L["Thank you, {name}. It would warm my heart, if it still beat."] = "谢谢，{name}。这颗心要是还会跳，准会一暖。"
L["Such warmth, for one so cold? Returned in full, {name}."] = "给冰冷之人这般温暖？如数奉还，{name}。"
L["Thank you, {name}. I'd blush, but the blood stopped reaching my face."] = "谢谢你，{name}。我倒想脸红，可血早就流不到脸上了。"
L["My undying gratitude, {name}. For once, the phrase is accurate."] = "对你的感激至死不渝，{name}。我死过一回，确实没变。"
L["Most kind, {name}. You've lifted me from 'deceased' to 'mildly deceased'."] = "太好心了，{name}。你让我从“已故”升级成了“有点已故”。"
L["You've added years to my life, {name}. Shame it already ended."] = "你给我延寿了好几年，{name}。可惜我的命早到头了。"
L["I felt that, {name}, and I don't feel much these days. Here, feel this."] = "我感觉到了，{name}，我最近可没什么知觉。来，你也感受一下。"
L["I'd shake your hand, {name}, but I'm not sure mine is still attached."] = "本想和你握手，{name}，可我不确定我的手还连着。"
L["Thank you, {name}. I'd send a bat with a proper note, but they eat the notes."] = "谢谢，{name}。本想派蝙蝠送张谢帖，可它们会把帖子吃了。"
L["You've spoiled me, {name}. The pleasant kind of spoiled, for once."] = "你把我宠坏了，{name}。难得这回的“坏”是好的那种。"
L["The last gift I got was the plague, {name}. Yours is a big improvement."] = "我上次收到的礼物是瘟疫，{name}。你这份强多了。"
L["Thank you, {name}. Nothing this fresh has touched me since Lordaeron fell."] = "谢谢，{name}。洛丹伦陷落后，还没这么新鲜的东西碰过我。"
L["Sylvanas says we repay every debt, {name}. She rarely means the nice ones."] = "希尔瓦娜斯说有债必还，{name}。她一般指的是血债。"
L["My posture's improved, {name}. It's been slumping since the Third War. Thanks."] = "我腰板都直了，{name}。从第三次大战起就一直驼着。谢了。"
L["Repaid at once, {name}. We Forsaken never carry debts. They rot."] = "马上还你，{name}。被遗忘者从不拖欠，拖久了就成烂账。"
L["Thank you, {name}. Unpaid debts in Undercity end up in the canal. Not yours."] = "谢谢，{name}。在幽暗城，赖账的都进了运河。你不会。"
L["Thank you, {name}. I'll keep this somewhere safe. My ribcage has room."] = "谢谢，{name}。我会把它收好。我的肋骨里有空位。"
L["Thank you, {name}. I'd bake you something, but everything I touch goes off."] = "谢谢，{name}。本想给你烤点东西，可我一碰什么都会馊。"
L["I'll mention you to the Dark Lady, {name}. She won't care, but I will."] = "我会跟黑暗女王提起你，{name}。她不会在意，但我会。"
L["Kindness returned, {name}. Even the flies around me look impressed."] = "好意回赠，{name}。连我身边的苍蝇都看呆了。"
L["In all my years with the Scourge, nobody once said this, {name}. Thank you."] = "在天灾军团那些年，从没人对我说过这句，{name}：谢谢你。"
L["I'll drink to you tonight, {name}. It all leaks out, but it's the thought."] = "今晚我为你干一杯，{name}。虽然会全漏出来，但心意到了。"
L["The Dark Lady says trust no gift, {name}. I'll risk it, and send one back."] = "黑暗女王说别信任何礼物，{name}。我冒个险，还你一份。"
L["Thank you, {name}. You've made my list of reasons to keep going. It's short."] = "谢谢，{name}。你上了我“撑下去的理由”清单。清单很短。"
L["Thank you, {name}. No contract, no fine print. Varimathras should take notes."] = "谢谢，{name}。没合同，没小字条款。瓦里玛萨斯该学学。"
L["Grave dirt and gratitude, {name}: all I own. You'll prefer the gratitude."] = "坟土和感激，{name}：我的全部家当。你会更喜欢感激的。"
L["Thank you, {name}. Eternity drags; this was the best bit of the decade."] = "谢谢，{name}。永生太漫长，这是这十年里最好的一刻。"
L["Faranell would want notes on that reaction, {name}. I'll just return it."] = "法拉尼尔会想记录这个反应，{name}。我就直接回赠了。"
L["Thank you, {name}. Lordaeron had manners once. Glad somebody kept them."] = "谢谢，{name}。洛丹伦也曾讲礼数。幸好还有人留着。"
L["The Deathguard would salute you, {name}, but it's hard on their arms. Thanks."] = "死亡守卫本想向你敬礼，{name}，可一敬礼胳膊就掉。谢了。"
L["I'd have Lordaeron's bells rung for you, {name}, but they only do funerals now."] = "本想为你敲响洛丹伦的钟，{name}，可如今它们只敲丧钟。"
L["Thank you, {name}. Next time I'm in Brill, I'll name a pumpkin after you."] = "谢谢，{name}。下回到布瑞尔，我挑个南瓜叫你的名字。"
L["Thank you, {name}. My afterlife had rather let itself go. You've tidied it up."] = "谢谢，{name}。我的来世早已破罐破摔，倒被你拾掇整齐了。"
L["Certainly, {name}. Try not to die. It's overrated."] = "当然，{name}。尽量别死，死亡被高估了。"
L["You need only ask, {name}. The dead are patient."] = "开口就行，{name}。死人最有耐心。"
L["Ask the dead for a favour, {name}. We rarely have other plans."] = "有事尽管找亡者，{name}。我们一般没别的安排。"
L["Certainly, {name}. Stand clear; I'd hate to drop anything on you."] = "当然，{name}。站远点，我可不想有零件掉你身上。"
L["A moment, {name}. Rigor mortis is hard on the casting hand."] = "稍等，{name}。尸僵对施法的手不太友好。"
L["Nice to be asked for something, {name}, besides the way to the graveyard."] = "难得有人找我帮忙，{name}，而不是问墓地怎么走。"
L["Gladly, {name}. It takes my mind off the smell. Mine, I mean."] = "好，{name}。忙起来就闻不到那股味儿了。我身上的。"
L["Certainly, {name}. Hold still. My aim drifts when my eye does."] = "当然，{name}。别动。我眼珠一飘，准头也跟着飘。"
L["In Undercity nobody says please, {name}. Mostly they gurgle. Here you are."] = "在幽暗城没人说“请”，{name}。大多只会咕噜咕噜。给。"
L["Just {buff}, {name}? The apothecaries always want a sample too."] = "只要{buff}吗，{name}？换药剂师，还得顺手取个样。"
L["I always rise when called, {name}. Unfortunate history. Here you are."] = "随叫随起，{name}。当年诈尸落下的毛病。给。"
L["Anything for you, {name}. Within reason, and what's left of mine."] = "什么都行，{name}。在理智范围内——就我剩下那点理智。"
L["Of course, {name}. I'd say 'over my dead body', but that's been tried."] = "当然，{name}。本想说“除非从我尸体上踏过去”，可早有人踏过了。"
L["Right away, {name}. The dead don't dawdle. We shamble with purpose."] = "马上，{name}。死人从不磨蹭，我们蹒跚得很有目标。"
L["Of course, {name}. Free will is a gift. I spend mine on things like this."] = "当然，{name}。自由意志来之不易，我就花在这种事上。"
L["Coming up, {name}. Quicker than a bat out of Undercity, and it doesn't bite."] = "马上好，{name}。比幽暗城飞出的蝙蝠还快，而且不咬人。"
L["Of course, {name}. After a winter in the Plaguelands, this counts as a holiday."] = "当然，{name}。在瘟疫之地熬过一个冬天，这点活儿就算度假。"
L["{buff}, {name}? Sorry, my good ear's in my other pocket."] = "{buff}，{name}？抱歉，我那只好耳朵揣在另一个兜里。"
L["Of course, {name}. No sleep, no meals, no plans. I'm extremely available."] = "当然，{name}。不睡不吃没安排，闲得要命——反正命也没了。"
L["I'm dying to help, {name}. Figure of speech. I've done the real one."] = "我想帮你想得要死，{name}。修辞而已，真死我已经死过了。"
L["Stay among the living a little longer, {name}."] = "在活人堆里多待一阵吧，{name}。"
L["Take this, {name}. The grave can wait."] = "拿着，{name}。坟墓可以再等等。"
L["I was a physician in Lordaeron, {name}. Old habits die harder than I did."] = "我在洛丹伦当过医生，{name}。老习惯比我还难死。"
L["No charge, {name}. The apothecaries would have made you sign something."] = "免费，{name}。换药剂师来，得先让你签个字。"
L["A gift from the grave, {name}. Don't worry, I washed it."] = "来自坟墓的礼物，{name}。放心，洗过了。"
L["Every body needs a little help, {name}. Mine mostly needs stitches."] = "每副身躯都需要一点帮助，{name}。我的主要需要针线。"
L["I've seen where heroes end up, {name}. I live there. Take this."] = "我见过英雄们的归宿，{name}。我就住那儿。拿着。"
L["Take this, {name}. I learned the hard way you can't take it with you."] = "拿着，{name}。我用亲身经历学到：生不带来，死不带去。"
L["Take this, {name}. It's the only thing I own that isn't slightly damp."] = "拿着，{name}。我所有东西里，就它不潮。"
L["Hold on to yourself, {name}. Trust me, the pieces are hard to find later."] = "看好你自己，{name}。信我，散了架零件很难找齐。"
L["Take this, {name}. The Plaguelands are full of people who didn't."] = "拿着，{name}。瘟疫之地到处都是没拿的人。"
L["A small kindness, {name}. My bat got the last one, and it never said thanks."] = "一点小心意，{name}。上一份给了我的蝙蝠，它连声谢都没说。"
L["Tirisfal fog gets into everything, {name}. So does this, but pleasantly."] = "提瑞斯法的雾无孔不入，{name}。这个也是，不过舒服多了。"
L["Here, {name}. I kept it cool for you. I keep everything cool. Can't help it."] = "给，{name}。帮你冰镇过了。我碰什么都冰镇，没办法。"
L["I've outlived everyone I knew, {name}. I'd rather not outlive you. Take this."] = "认识的人我全熬走了，{name}。可不想再熬走你。拿着。"
L["Pardon me, {name}. I'm told I lurk. I'm trying to lurk helpfully."] = "打扰，{name}。听说我老爱鬼鬼祟祟，我尽量鬼祟得热心点。"
L["Out of my own pocket, {name}. What's left of the pocket, anyway."] = "自掏腰包，{name}。好吧，是腰包剩下的那部分。"
L["I've already had the worst day there is, {name}. Let's spare you yours."] = "最糟的那一天我已经过过了，{name}。你的就免了吧。"
L["Wind's off the Plaguelands, {name}. Take this, and breathe through your mouth."] = "风从瘟疫之地吹来，{name}。拿着这个，用嘴呼吸。"
L["The crows have been watching you, {name}. Let's disappoint them."] = "乌鸦一直盯着你，{name}。咱们让它们失望一回。"
L["Here, {name}. Tirisfal grows nothing but pumpkins and grudges. This is neither."] = "给，{name}。提瑞斯法只长南瓜和怨恨。这个两样都不是。"
L["Take this, {name}. The only thing in Undercity that needn't be boiled first."] = "拿着，{name}。幽暗城里唯一不用先煮开的东西。"
L["Eternity is long, {name}, and I've spent a fair bit of it practising this."] = "永恒很漫长，{name}，我花了不少时间练这一手。"
L["For the road, {name}. Undercity-made, so do keep it away from open flame."] = "路上用，{name}。幽暗城出品，务必远离明火。"
L["Take this, {name}. It's odourless, which I'm told makes it my best feature."] = "拿着，{name}。它没味道，据说这让它成了我全身最大的优点。"
L["Forsaken are famously patient, {name}. I just couldn't wait to give you this."] = "被遗忘者出了名的有耐心，{name}。可这个我实在等不及要给你。"
L["No strings attached, {name}. I cut mine when the Lich King lost his grip."] = "白送，无牵无挂，{name}。巫妖王一松手，我的提线就剪了。"
L["Fresh from Tirisfal, {name}. Well, fresh for Tirisfal."] = "提瑞斯法新鲜直送，{name}。嗯，按提瑞斯法的标准算新鲜。"
L["Take this, {name}. I was saving it, but I'm bad at keeping things. Look at me."] = "拿着，{name}。本想留着，可我不擅长保存东西。瞧瞧我。"
L["We Forsaken must look after each other, {name}."] = "我们被遗忘者得互相照应，{name}。"
L["Between us corpses, {name}, you're remarkably well preserved."] = "咱们尸体之间说句实话，{name}，你保存得真不错。"
L["Lose a finger, {name}, and I've a spare. Forsaken share."] = "掉了手指，{name}，我有备用的。被遗忘者有福同享。"
L["Is your jaw clicking too, {name}, or is that just me?"] = "你的下巴也咔咔响吗，{name}，还是只有我？"
L["Victory for Sylvanas, {name}. A small one this time, but it's ours."] = "希尔瓦娜斯必胜，{name}。这回赢得不大，但是咱们的。"
L["Brill or Deathknell, {name}? We all woke up somewhere. I got the damp crypt."] = "布瑞尔还是丧钟镇，{name}？谁都得在哪儿醒来。我分到了潮墓穴。"
L["When the Scourge comes calling, {name}, we won't be home. Not ever again."] = "天灾军团再来敲门，{name}，咱们都不在家。永远不在。"
L["The Bulwark still holds, {name}, and so do we. Held together, but holding."] = "壁垒还守得住，{name}，我们也是。缝缝补补，但还撑得住。"
L["Lordaeron raised us twice, {name}: once as children, once as Forsaken."] = "洛丹伦拉了我们两把，{name}：一把拉扯长大，一把拉出坟墓。"
L["Somewhere in Northrend, {name}, the Lich King is sulking about us. Good."] = "此刻在诺森德，{name}，巫妖王正为我们生闷气。很好。"
L["The Dark Lady needs us whole, {name}. Near enough will do."] = "黑暗女王要我们完完整整，{name}。差不多完整也行。"
L["You smell of Tirisfal, {name}. From one of us, that's a compliment."] = "你身上有提瑞斯法的味道，{name}。自己人说这话，是在夸你。"
L["We've both got forever, {name}. Let's not spend it all waiting for the lift."] = "咱俩都有永生，{name}。别全耗在等升降梯上。"
L["One Forsaken to another, {name}: the sewer shortcut is not a shortcut."] = "被遗忘者之间说句实话，{name}：下水道那条近路，根本不近。"
L["If the Deathguard ask, {name}, we're on patrol. A very, very slow patrol."] = "亡灵卫士要是问起，{name}，就说我们在巡逻。非常、非常慢的巡逻。"
L["Our kind don't get many kindnesses, {name}. Let's keep them in the family."] = "咱们这号人难得被善待，{name}。肥水不流外人田。"
L["The bats in the Trade Quarter know us both by now, {name}. That's fame, nearly."] = "商业区的蝙蝠都认得咱俩了，{name}。差不多算出名了。"
L["Keep the faith, {name}. In each other, I mean. It answers more often."] = "要有信仰，{name}。信彼此就行，比圣光回话勤快。"
L["The dead look after the dead, {name}. The living could learn a thing or two."] = "死人照顾死人，{name}。活人该学着点。"
L["We've both seen the inside of a grave, {name}. Dreadful service. No view."] = "咱俩都住过坟墓，{name}。差评：服务糟糕，毫无景观。"
L["Stay alive, {name}. Undercity's housing list is already very long."] = "好好活着，{name}。幽暗城分房的队已经排很长了。"
L["If I fall down, {name}, give it a minute. Old habit."] = "要是我倒下了，{name}，等一会儿。老毛病了。"
L["I'll take the front, {name}. What's the worst that could happen? Again?"] = "我打头阵，{name}。最坏能怎样？再死一次？"
L["Keep upwind of me, {name}. It's better for morale."] = "站我上风口，{name}。有利于士气。"
L["The last party I joined, {name}, I woke up in a crypt. Let's improve on that."] = "上次组队，{name}，我是在墓穴里醒来的。这次争取好点。"
L["Anything that bites, {name}, point it at me. There's nothing left worth eating."] = "会咬人的东西，{name}，都往我这儿引。我身上没啥能吃的了。"
L["Spare the heals for the others, {name}. I run on spite and embalming fluid."] = "治疗留给别人吧，{name}。我靠怨气和防腐液就能跑。"
L["If this goes badly, {name}, don't worry. I know the way back. Intimately."] = "搞砸了也别慌，{name}。回来的路我熟，跑尸跑惯了。"
L["I've fought the Scourge from both sides, {name}. This side's better company."] = "天灾军团我两边都待过，{name}。还是这边的人好相处。"
L["Stay close, {name}. I'm the one who won't scream at the ghouls. Old neighbours."] = "跟紧我，{name}。见了食尸鬼我不会尖叫，老邻居了。"
L["I've walked the Plaguelands at night, {name}. This is a stroll by comparison."] = "我夜里走过瘟疫之地，{name}。比起来这就是散步。"
L["The corpse at the back is me, {name}. Please don't loot it."] = "后面那具尸体是我，{name}。请勿拾取。"
L["Stay together, {name}. It's easier than putting somebody back together."] = "大家待在一起，{name}。总比把人拼回一起容易。"
L["Don't wait for me, {name}. I shamble, but I shamble forever. I'll catch up."] = "别等我，{name}。我走得蹒跚，可能蹒跚到永远。准能追上。"
L["Keep the torches clear of me, {name}. I'm old, dry and very flammable."] = "火把离我远点，{name}。我又老又干，一点就着。"
L["Don't check me for a pulse after, {name}. It only worries people."] = "打完别摸我的脉搏，{name}。只会让人担心。"
L["Mind the green puddles, {name}. I've seen what they do. I'm what they do."] = "当心绿水坑，{name}。我知道它们能把人变成啥样——就我这样。"
L["Send anything scary to me, {name}. I've been dead; it's got nothing."] = "吓人的都交给我，{name}。死我都死过了，还怕啥。"
L["Stick together, {name}. The apothecaries pay well for strays."] = "别掉队，{name}。药剂师收购落单的，出价很高。"
L["If this ends underwater, {name}, don't mind me. Breathing's optional now."] = "要是打到水下去了，{name}，别管我。呼吸对我是可选项。"
L["The Dark Lady trusts no one, {name}. I've made an exception for this party."] = "黑暗女王谁都不信，{name}。我为这支小队破个例。"
L["When we win, {name}, drinks at the Gallows' End in Brill. My treat. Your risk."] = "赢了，{name}，去布瑞尔的旅店喝一杯。我请客，风险自负。"
L["Don't mind the bats, {name}. They follow me everywhere. They think I'm a cave."] = "别管那些蝙蝠，{name}。它们走哪儿跟哪儿，以为我是个山洞。"
L["I'll watch the rear, {name}. Nothing sneaks up on someone who can't blink."] = "我来盯后面，{name}。我眼都不会眨，谁也偷袭不了。"
L["Any blood on the floor after, {name}, it isn't mine. I stopped carrying any."] = "打完地上要是有血，{name}，肯定不是我的。我早不随身带血了。"
L["The dead keep terrible hours, {name}. Nice to have company for once."] = "死人作息很糟，{name}。难得有人作陪。"
L["Midnight, {name}: the best hour to be up and about when you shouldn't be."] = "午夜，{name}：最适合不该起来的人起来走走。"
L["The living are all asleep, {name}. We Forsaken call this the quiet shift."] = "活人都睡了，{name}。我们被遗忘者管这叫清闲夜班。"
L["Late, {name}? In Undercity, this is lunchtime."] = "晚了，{name}？在幽暗城，这是午饭时间。"
L["This is the hour the Scourge used to walk, {name}. Now it's ours."] = "这曾是天灾军团出没的时辰，{name}。现在归我们了。"
L["Night, {name}. The one time nobody can tell I'm pale."] = "入夜了，{name}。唯一没人看得出我脸色苍白的时候。"
L["Dark as the Undercity, {name}. Finally, some proper lighting."] = "黑得跟幽暗城一样，{name}。总算有像样的照明了。"
L["Fog, moonlight and a hint of mildew, {name}. Proper Tirisfal weather."] = "雾气、月光，外加一丝霉味，{name}。地道的提瑞斯法天气。"
L["The banshees start singing about now, {name}. Relax. They're only practising."] = "女妖差不多该开嗓了，{name}。放心，她们只是在练声。"
L["Stars over Tirisfal, {name}. The one thing up there that never rotted."] = "提瑞斯法上空的星星，{name}。唯一从没腐烂的东西。"
L["Past midnight, {name}. The graveyards are quiet. The good ones, anyway."] = "过午夜了，{name}。墓地都安静了。像样的那些是。"
L["An owl just saw me and left, {name}. They're sensible birds."] = "有只猫头鹰看了我一眼就飞走了，{name}。明智的鸟。"
L["Morning already, {name}? I've been up all night. And all of last decade."] = "已经早上了，{name}？我通宵没睡。上个十年也是。"
L["The sun's up, {name}. I'll stand in the shade, if you don't mind. Things peel."] = "太阳出来了，{name}。我站阴凉处，不介意吧。会脱皮的。"
L["Early start, {name}. The dead never sleep in. Or at all, really."] = "起得早，{name}。死人从不赖床。其实压根不睡。"
L["Sunrise, {name}. My least favourite colour. I'm off to find some shade."] = "日出了，{name}。我最讨厌的颜色。我找阴凉去了。"
L["Dawn over Tirisfal, {name}: grey, then slightly less grey. Glorious."] = "提瑞斯法的黎明，{name}：先是灰，然后没那么灰。壮观。"
L["Morning, {name}. The Gallows' End porridge moved again. Have this instead."] = "早，{name}。布瑞尔旅店的粥又自己动了。还是拿这个吧。"
L["The roosters in Brill still crow, {name}. Nobody's had the heart to tell them."] = "布瑞尔的公鸡还在打鸣，{name}。没人忍心告诉它们。"
L["Morning, {name}. The Deathguard change shifts now. They just turn round."] = "早，{name}。亡灵卫士换班了。转个身就算换完。"
L["Take the lift slowly, {name}. The last man who rushed it is still coming down."] = "升降梯慢慢坐，{name}。上一个抢着上的，到现在还在往下掉。"
L["Undercity has it all, {name}: a bank, an inn, and opinions in the sewers."] = "幽暗城应有尽有，{name}：银行、旅店，还有下水道里的各路高见。"
L["Even the rats bow to the Dark Lady here, {name}. Take this before one asks."] = "在这儿连老鼠都向黑暗女王鞠躬，{name}。拿着，别等老鼠来讨。"
L["Mind the canal, {name}. It's green for a reason, and the reason isn't moss."] = "当心运河，{name}。它绿是有原因的，而且原因不是青苔。"
L["Undercity's lovely this time of year, {name}. It's always this time of year."] = "每年这时候的幽暗城都很美，{name}。这里永远是这时候。"
L["We moved into Lordaeron's cellar, {name}, and kept the good silver."] = "我们搬进了洛丹伦的地窖，{name}，好银器都留着呢。"
L["The Royal Quarter's that way, {name}. Bow low; the banshees keep score."] = "皇家区在那边，{name}。鞠躬要低，女妖会打分。"
L["The bat handler swears they're friendly, {name}. Take this before you test it."] = "蝙蝠管理员发誓它们很友善，{name}。亲自验证前，先拿着这个。"
L["Magic Quarter's that way, {name}. The glowing puddles aren't for drinking."] = "魔法区在那边，{name}。发光的水坑不是给你喝的。"
L["The throne room's just upstairs, {name}. Nobody sits in it. Bad memories."] = "王座厅就在楼上，{name}。没人去坐。回忆不好。"
L["Most folk greet a Forsaken with holy water, {name}. You're a welcome change."] = "见了被遗忘者，多数人先泼圣水，{name}。你真叫人耳目一新。"
L["Few stop for a Forsaken, {name}. You did, and I noticed. Thank you."] = "很少有人为被遗忘者停步，{name}。你停了，我记下了。谢谢。"
L["Contrary to rumour, {name}, not everything a Forsaken hands out is a plague."] = "谣言归谣言，{name}，被遗忘者送出的东西，不全是瘟疫。"
L["Forsaken can't be charmed, {name}, they say. Asking nicely works, though."] = "都说被遗忘者不受魅惑，{name}。不过好好说话还是管用的。"
L["Take this instead of small talk, {name}. Mine tends to unsettle people."] = "拿这个代替寒暄吧，{name}。我一寒暄，别人就发毛。"
L["They say the Forsaken have no friends, {name}. I'm recruiting."] = "都说被遗忘者没朋友，{name}。我正在招人。"
L["Take this, {name}. If anyone asks, the Forsaken were perfectly charming."] = "拿着，{name}。有人问起，就说被遗忘者可讨人喜欢了。"
L["Stay alive, {name}. I've tried the alternative, and I can't recommend it."] = "好好活着，{name}。另一种选项我试过了，不推荐。"
L["The Earth Mother saw your kindness, {name}. She nudged me. Quite hard."] = "大地母亲看见了你的善意，{name}。她推了我一把。挺用力的。"
L["Thank you, {name}. May the winds guide you."] = "谢谢你，{name}。愿风指引你。"
L["Thank you, {name}. I'm deeply moved, and it takes a lot to move a tauren."] = "谢谢你，{name}。我很感动。要让牛头人动一动，可不容易。"
L["It's a long way up to a tauren's heart, {name}. You found it."] = "牛头人的心长得老高，{name}。你还是找到了。"
L["I felt that from horn to hoof, {name}. Returned, hoof to horn."] = "从角到蹄都感受到了，{name}。回敬你，从蹄到角。"
L["A gift given is a seed planted, {name}. Here is the harvest."] = "送出的礼物是播下的种子，{name}。这是收成。"
L["That deserves a feast, {name}. The feast can wait; {buff} can't."] = "这值得摆一桌宴席，{name}。宴席可以等，{buff}不能等。"
L["Thank you, {name}. Should you ever need a wall to hide behind, I'm free."] = "谢谢你，{name}。哪天需要一堵墙躲着，我有空。"
L["I'd dance for joy, {name}, but last time Bloodhoof lost a roof. This instead."] = "本想乐得跳支舞，{name}，可上回把血蹄村跳塌了屋顶。送你这个。"
L["Returned faster than a wind rider, {name}, and with much less screeching."] = "比双足飞龙还快地还你，{name}，还少了一路尖叫。"
L["Returned, {name}. The quilboar never learned to give back, and look at them."] = "还你，{name}。野猪人从没学会回礼，你看看他们。"
L["Thank you, {name}. My ancestors are all nodding. It's a great deal of nodding."] = "谢谢你，{name}。我的祖先们都在点头。点得可多了。"
L["In Mulgore we return a gift before the grass under it grows back, {name}."] = "在莫高雷，收了礼要赶在底下的草长回来前回礼，{name}。"
L["Thank you, {name}. I'll name my next kodo calf after you. They're lovely."] = "谢谢你，{name}。下一头小科多兽就叫你的名字。它们可爱着呢。"
L["Kindness is rarer than shade in the Barrens, {name}. Here's some back."] = "善意比贫瘠之地的树荫还稀罕，{name}。还你一些。"
L["I'll carve this on a totem, {name}. Tauren carve slowly; expect it by spring."] = "我要把这事刻上图腾，{name}。牛头人刻得慢，开春见。"
L["Folk give directions by me, {name}: 'left at the tauren.' You gave me a gift."] = "大家指路拿我当地标，{name}：“牛头人那儿左拐。”你却送我礼物。"
L["Cairne taught us to honour every kindness, {name}. I'd been hoping for one."] = "凯恩教导我们珍视每一份善意，{name}。我正盼着有一份呢。"
L["Of course, {name}. Stand tall and be at peace. I'll handle the tall part."] = "当然，{name}。昂首站立，心平气和。高的部分交给我。"
L["Ask and it is given, {name}. The herd shares what it has."] = "有求必予，{name}。族人有福同享。"
L["Of course, {name}. Stand back a pace; I do this with my whole body."] = "当然，{name}。退后一步，我施法用的是全身。"
L["Gladly, {name}. Mind the tail."] = "乐意之至，{name}。当心尾巴。"
L["The Earth Mother gives freely, {name}, and so do her largest children."] = "大地母亲慷慨给予，{name}，她个头最大的孩子们也是。"
L["Gladly, {name}. Tauren are slow to anger and quick to help. Quick-ish."] = "乐意之至，{name}。牛头人发火慢，帮忙快。相对快。"
L["Refuse you, {name}? My ancestors would never let me hear the end of it."] = "拒绝你，{name}？祖先们会念叨我一辈子。"
L["Of course, {name}. A tauren says yes the way the plains grow grass: easily."] = "当然，{name}。牛头人说“好”，就像草原长草：毫不费力。"
L["Of course, {name}. One moment; my hands are big and the spell is small."] = "当然，{name}。稍等，我手大，法术小。"
L["After a season herding kodo, {name}, a polite request is a holiday. Here."] = "赶了一季科多兽，{name}，有人客气地请求，简直像过节。给。"
L["The Earth Mother says share, {name}. My stomach says lunch. She outranks it."] = "大地母亲说要分享，{name}。我的肚子说要吃午饭。她说了算。"
L["Of course, {name}. You get the help and a tauren proverb. Proverb: hold still."] = "当然，{name}。帮忙外加一句牛头人谚语。谚语：别动。"
L["Spirits of the plains, lend me a hand. ...Ah, I have two. Here, {name}."] = "草原之灵啊，助我一臂之力……哦，我自己有两臂。给，{name}。"
L["Magatha would want a favour for it, {name}. Baine would just say yes. So: yes."] = "换玛加萨，得让你欠个人情，{name}。贝恩会直接答应。所以：好。"
L["Hold still, {name}. I've practised on kodo, and they're far less polite."] = "别动，{name}。我在科多兽身上练过，它们可没你这么有礼貌。"
L["Of course, {name}. A shu'halo never refuses a traveller. Or a second helping."] = "当然，{name}。牛头人从不拒绝旅人。也不拒绝再来一碗。"
L["Walk with the Earth Mother, {name}. She's everywhere, so you can't get lost."] = "与大地母亲同行吧，{name}。她无处不在，所以你迷不了路。"
L["May An'she light your path, {name}."] = "愿安舍照亮你的道路，{name}。"
L["You looked like you could use a friend, {name}. I'm a very big one."] = "你看着像需要个朋友，{name}。我是特大号的。"
L["Take this, {name}. The Earth Mother would scold me if I walked past."] = "拿着，{name}。要是我就这么走过去，大地母亲会骂我的。"
L["Tread lightly, {name}. Take it from someone who never has."] = "脚步放轻，{name}。这话出自一个从没轻过的人。"
L["The wind said you'd pass this way, {name}. The wind is a terrible gossip."] = "风说你会路过这儿，{name}。风是个大嘴巴。"
L["Take this, {name}. I'd lend you my kodo too, but he's less generous than me."] = "拿着，{name}。本想把科多兽也借你，可它没我大方。"
L["The shu'halo say carry what you can for others, {name}. I can carry a lot."] = "牛头人说，能替别人扛多少就扛多少，{name}。我能扛很多。"
L["Take this, {name}. If the centaur trouble you, say Thunder Bluff sends regards."] = "拿着，{name}。半人马找你麻烦，就说雷霆崖向他们问好。"
L["Here, {name}. Plainstriders run from me for no reason at all. You needn't."] = "给，{name}。陆行鸟见我就跑，莫名其妙。你不用跑。"
L["For you, {name}. Visit Mulgore sometime. The grass is soft and nobody hurries."] = "给你，{name}。有空来莫高雷，草软软的，没人赶时间。"
L["Here, {name}. Grandmother blessed travellers and fed them. I'm out of bread."] = "给，{name}。奶奶总为旅人祝福，还管饭。我面包吃完了。"
L["The spirits asked me to mind you, {name}. I said yes before they'd finished."] = "众灵让我照看你，{name}。话没说完我就答应了。"
L["Here, {name}. Better a gift than a war stomp. Both leave an impression."] = "给，{name}。送礼总比战争践踏强。两样都能留下深深的印记。"
L["Here, {name}. Tauren leave the world a little better, and a little trampled."] = "给，{name}。牛头人走过，世界会好一点，也会被踩平一点。"
L["You look weary, {name}. The Earth Mother would offer a nap. I offer this."] = "你看着累了，{name}。大地母亲会让你睡个午觉。我给你这个。"
L["Sunwalkers call it a blessing, hunters luck, {name}. Tauren call it manners."] = "日行者叫它祝福，猎人叫它运气，{name}。牛头人叫它礼数。"
L["Take this, {name}. If a harpy screeches at you, screech back. They hate that."] = "拿着，{name}。鹰身人冲你尖叫，你就叫回去。它们最烦这个。"
L["Here, {name}. A tauren blessing: sturdy, slow to fade, smells faintly of sage."] = "给，{name}。牛头人的祝福：结实、耐久，还带点鼠尾草香。"
L["The Earth Mother watches over us both, {name}."] = "大地母亲守护着我们俩，{name}。"
L["Somebody warn the doorframes, {name}. There are two of us now."] = "快通知门框，{name}。现在有两个我们了。"
L["Plains or peaks, {name}, a shu'halo heart is a big one."] = "莫高雷或至高岭，{name}，牛头人的心都很大。"
L["Horns and helmets, {name}. Only another tauren knows the pain."] = "犄角配头盔，{name}。这份痛只有牛头人懂。"
L["Rain on fur takes a week to dry, {name}. Only another tauren ever believes me."] = "毛淋了雨，得一个礼拜才干，{name}。只有牛头人同胞信我。"
L["Between tauren, {name}: Thunder Bluff's lifts were built by somebody smaller."] = "牛头人之间说句实话，{name}：雷霆崖的升降梯，是个子小的人造的。"
L["Our ancestors watch us both, {name}. Let's give them something nice to see."] = "先祖们看着咱俩呢，{name}。让他们看点好的。"
L["From Mulgore to Highmountain, {name}, the herd always finds itself."] = "从莫高雷到至高岭，{name}，族群总能找到彼此。"
L["Get behind me, {name}. There's room back there for the whole party."] = "躲我后面，{name}。那儿够整支小队待的。"
L["The herd moves together, {name}. Mind my hooves; the herd has learned to."] = "族群同进同退，{name}。当心我的蹄子，族群都学会了。"
L["Low ceilings ahead, {name}? I'll be the first to find out. Take this."] = "前面天花板低，{name}？我会第一个知道。拿着。"
L["I'm slow to anger, {name}, but I hold a grudge for the whole party."] = "我不轻易发火，{name}，但我替全队记仇。"
L["Need a wall to hide behind, {name}? I'm most of one. Come on."] = "需要一堵墙躲着，{name}？我差不多就是。来吧。"
L["When I war stomp, {name}, everybody sit down. It saves you falling over."] = "我战争践踏时，{name}，大家都坐下。省得摔倒。"
L["Everyone fed? Everyone blessed? Good, {name}. Tauren never lead a hungry herd."] = "都吃饱了？都祝福过了？好，{name}。牛头人从不带饿肚子的族群。"
L["Tauren don't swim, {name}, we wade. If it's deep, you're riding on me."] = "牛头人不游泳，{name}，我们蹚水。水深的话，你骑我身上。"
L["Stay close, {name}. My ancestors walk with us. They're quieter than you lot."] = "跟紧，{name}。祖先与我们同行。他们比你们安静多了。"
L["If I fall, {name}, don't try to carry me. Drag me. Fondly."] = "我要是倒了，{name}，别扛我。拖着走。深情地拖。"
L["We move like a stampede, {name}: all together, and sorry about the flowers."] = "我们像兽群奔腾，{name}：齐心协力，花花草草对不住了。"
L["Nobody walks alone at the rear, {name}. That's where I'll be, looming kindly."] = "谁也不会独自殿后，{name}。我就在后面，慈祥地杵着。"
L["Tell me when to charge, {name}. Tauren are slow to start, and slower to stop."] = "该冲锋时告诉我，{name}。牛头人起步慢，刹车更慢。"
L["Nobody wander, {name}. The last party that did in the Barrens is still walking."] = "谁都别乱走，{name}。上一支在贫瘠之地乱走的队伍，现在还在走。"
L["An'she rises, {name}, and so do we. Slower, in my case."] = "安舍升起，{name}，我们也起身。我慢一点。"
L["The sun is An'she's eye, {name}. He's watching, so let's look busy."] = "太阳是安舍的眼睛，{name}。他在看，咱们装得忙一点。"
L["Morning, {name}. The kodo are up, the grass is wet, and this is yours."] = "早，{name}。科多兽醒了，草上有露水，这个是你的。"
L["Morning, {name}. I've greeted the sun, the wind and two plainstriders. Now you."] = "早，{name}。太阳、风、两只陆行鸟我都打过招呼了。轮到你。"
L["Morning, {name}. Dew on the grass, dew on my fur. I'll be damp till noon."] = "早，{name}。草上有露水，我毛上也有。要湿到中午了。"
L["Early, {name}. That mist over Mulgore at dawn? Mostly kodo breath."] = "真早，{name}。莫高雷清晨那层雾？大半是科多兽呼的气。"
L["Mu'sha keeps the night watch, {name}. I'll tell her to keep an eye on you."] = "穆莎守着夜，{name}。我会让她多照看你。"
L["The moon's out, {name}. Mu'sha sees you, and she approves. I asked."] = "月亮出来了，{name}。穆莎看着你，她很满意。我问过了。"
L["Late, {name}. The kodo are asleep, and they snore like thunder. Take this."] = "夜深了，{name}。科多兽睡着了，打呼噜像打雷。拿着。"
L["Stars out, {name}. Each one's an ancestor, they say. That one's winking at you."] = "星星出来了，{name}。都说每颗都是一位先祖。那颗在冲你眨眼。"
L["Late, {name}. Mulgore is so quiet at night you can hear the grass argue."] = "夜深了，{name}。莫高雷的夜静得能听见草在吵架。"
L["Quiet now, {name}. At this hour, even my hooves try to tiptoe."] = "小声点，{name}。这时候连我的蹄子都想踮着脚走。"
L["Ya be too kind, {name}! Dis one be from me."] = "你太客气咯，{name}！这个嘛，算我的。"
L["Thanks, mon! Da spirits smile on ya, {name}."] = "谢啦，伙计！众灵在冲你笑咧，{name}。"
L["Ya gave me good mojo, {name}. Now ya get some back, extra spicy."] = "你给了我好巫毒，{name}。现在还你一份，加辣的咧。"
L["Bwonsamdi gonna be real disappointed, {name}. Thanks, mon."] = "邦桑迪要大失所望咯，{name}。谢啦，伙计。"
L["Dat be some fine work, {name}. Almost as fine as me. Almost."] = "活儿干得漂亮，{name}。差不多跟我一样漂亮。差不多。"
L["A troll can grow back a hand, {name}. Can't grow back honour. Here."] = "巨魔的手能再长，{name}。荣誉可长不回来。给。"
L["Ya just made a troll smile, {name}, and we got a lot of teeth."] = "你让巨魔笑咧，{name}，我们牙可多着咧。"
L["Da loa keep a tally, {name}, and now ya on da good side of it."] = "洛阿都记着账咧，{name}，现在你在好的那一栏。"
L["Ya beat me to it, {name}! Darkspear hate bein' second. Now we even."] = "被你抢先咧，{name}！暗矛最恨当第二。这下扯平咧。"
L["I owe ya now, {name}, and trolls only like owin' da loa. Settled."] = "这下我欠你咧，{name}，巨魔只乐意欠洛阿的。还清！"
L["I be tellin' da whole Echo Isles 'bout ya, {name}. All dey talk 'bout is crabs."] = "我要跟全回音群岛讲你的事，{name}。他们成天就聊螃蟹咧。"
L["My hair just stood up taller, {name}. Didn't know it could. Thanks, mon."] = "我头发又竖高了一截，{name}。原来还能更高咧。谢啦，伙计。"
L["Da spirits say 'give it back', {name}. Da spirits nag, but dey right."] = "众灵说“还回去”，{name}。众灵是唠叨，可说得对咧。"
L["Mojo for mojo, {name}: oldest trade in da jungle. Second oldest be bananas."] = "巫毒换巫毒，{name}：丛林里最古老的买卖。第二古老的是香蕉。"
L["Vol'jin said repay kindness quick, {name}. He said a lot. Dat one stuck."] = "沃金说受了好处要快还，{name}。他话很多，这句我记住咧。"
L["Dat deserve a dance, {name}. Lucky ya, ya get {buff} instead."] = "这值得跳支舞，{name}。你走运，改给你{buff}咧。"
L["Jungle rule, {name}: what ya give come back, usually wit' teeth. Dis one don't."] = "丛林规矩，{name}：送出去的总会回来，通常还带着牙。这个不带。"
L["A gift for a troll? Careful, {name}. We follow nice folk home."] = "给巨魔送礼？当心咧，{name}。我们会跟着好人回家的。"
L["Sure ting, {name}. Hold still; da mojo don't like a movin' target."] = "小事一桩，{name}。莫乱动，巫毒不喜欢移动靶咧。"
L["No worries, {name}. Da loa got ya covered."] = "莫担心，{name}。洛阿罩着你咧。"
L["Stay away from da voodoo, {name}. ...Except dis voodoo. Dis one fine."] = "离巫毒远点，{name}。……除了这个巫毒。这个没事。"
L["Close ya eyes, {name}. Da mojo be shy when people watch."] = "闭上眼，{name}。有人看着，巫毒会害羞咧。"
L["Ya don't gotta ask twice, {name}. Ya barely gotta ask once."] = "不用问两遍，{name}。一遍都差点不用问咧。"
L["Sure, {name}. Bein' a troll be mostly swagger. Da rest be dis."] = "行嘞，{name}。当巨魔嘛，大半靠派头。剩下的就靠这个。"
L["Ya asked real polite, {name}. Polite get da good stuff."] = "你问得真客气，{name}。客气的人拿好货咧。"
L["Ya came to da right troll, {name}. Da wrong troll be over dere, fishin'."] = "你找对巨魔咧，{name}。找错的那个在那边钓鱼。"
L["Yes, {name}. Da loa owe me a favour, and I be spendin' it on you."] = "行，{name}。洛阿欠我个人情，我就花在你身上咧。"
L["No problem, {name}. Got a pouch fulla mojo. Don't touch da other pouch."] = "没问题，{name}。我有一袋子巫毒。另一个袋子莫碰。"
L["Anyting for ya, {name}. Well, not my hair. Da hair be sacred."] = "为你啥都行，{name}。头发除外。头发是神圣的咧。"
L["Troll magic, {name}, served hot. Blow on it first."] = "巨魔魔法，{name}，热乎的。先吹吹再用。"
L["Right away, {name}. In Zandalar dis need a priest, a pyramid and a week."] = "马上，{name}。在赞达拉，这得要一个祭司、一座金字塔和一星期。"
L["Easy one, {name}. Hard one be gettin' a raptor to sit still."] = "小意思，{name}。难的是让迅猛龙老实坐好。"
L["Troll rule, {name}: never make a friend beg or a raptor wait. Here."] = "巨魔规矩，{name}：朋友莫让求，迅猛龙莫让等。给。"
L["Hold still, {name}. Last one who wiggled got da spell and a new haircut."] = "莫乱动，{name}。上一个乱扭的，法术到手，还白送个新发型咧。"
L["Da loa be watchin' over ya, {name}. Dey real nosy like dat."] = "洛阿在守着你咧，{name}。他们就是这么爱管闲事。"
L["Stay sharp out dere, {name}. Take dis wit' ya."] = "在外头机灵点，{name}。这个带上。"
L["Ya look like somebody who appreciate quality, {name}. Here: quality."] = "你看着像识货的人，{name}。喏：好货。"
L["Take dis, {name}. Walk like ya own da jungle. I do."] = "拿着，{name}。走路要像丛林归你管。我就是。"
L["Everybody need mojo, {name}. I make so much I gotta give it away."] = "人人都需要巫毒，{name}。我做得太多，只好送人咧。"
L["A little somethin' for ya, {name}. Don't ask where da loa got it."] = "一点小意思，{name}。莫问洛阿打哪儿弄来的。"
L["Go on, {name}. Anyting try to eat ya now gonna get indigestion."] = "去吧，{name}。现在谁想吃你，准得消化不良咧。"
L["Ya lookin' dangerous now, {name}. Almost troll-level dangerous."] = "你现在看着挺危险咧，{name}。快赶上巨魔级别了。"
L["Somethin' for ya, {name}. No, ya don't owe da loa nothin'. Probably."] = "一点小意思，{name}。放心，你不欠洛阿啥。大概咧。"
L["Raptors out dere got bigger teeth den me, {name}. Now dey got a problem."] = "外头迅猛龙的牙比我还大，{name}。现在该它们头疼咯。"
L["Troll hospitality, {name}: ya get mojo, ya get a smile, ya don't get my fish."] = "巨魔待客之道，{name}：巫毒给你，笑脸给你，鱼不给。"
L["Walk wit' mojo, {name}. Everybody else just be walkin'."] = "带着巫毒，{name}，走路都带风。别人只是走路咧。"
L["Free mojo, {name}! Quick, before da witch doctor find out I give it away."] = "免费巫毒，{name}！快拿，莫让巫医知道我白送咧。"
L["Da loa said give dis to da next good soul, {name}. Ya da next good soul."] = "洛阿说把这个给下一个好心人，{name}。就是你咧。"
L["Here, {name}. Hakkar never shared, and look what happen to him."] = "给，{name}。哈卡从来不分享，瞧瞧他啥下场。"
L["Jungle got two kinds of folk, {name}: da ready and da lunch. Now ya ready."] = "丛林只分两种人，{name}：有备而来的，和被端上桌的。你是前一种咧。"
L["Easy, {name}. Dis mojo tickle goin' in. Don't laugh; it get offended."] = "放轻松，{name}。这巫毒进去有点痒。莫笑，它会生气咧。"
L["'Nobody badduh dan me,' Zul'jin said, {name}. Dis let ya argue da point."] = "“没人比我更狠！”祖尔金说的，{name}。有了这个，你能跟他掰扯掰扯咧。"
L["Hey, {name}! Always good to see family, mon."] = "嘿，{name}！见到自家人总是开心，老兄。"
L["Da rest of Azeroth stand up straight, {name}. We got more style."] = "艾泽拉斯别的种族都站得笔直，{name}。咱们更有范儿。"
L["Hey, {name}, ya tusks be lookin' sharp. Mine too, obviously."] = "嘿，{name}，獠牙真尖真帅咧。我的也是，当然。"
L["Every troll be family, {name}. Even da ones who still owe me gold."] = "巨魔都是一家人，{name}。连那些还欠我金币的也是。"
L["Island or pyramid, {name}, a troll be a troll. Zandalari just wear more gold."] = "海岛还是金字塔，{name}，巨魔都是巨魔。赞达拉人只是多戴点金子。"
L["Two trolls, {name}. Da room just got taller and a lot more relaxed."] = "两个巨魔，{name}。这屋子一下变高了，也松快多咯。"
L["Da loa can't tell us apart, {name}. Dat be why dey bless us both. Cheaper."] = "洛阿分不清我俩，{name}，所以一起保佑。买一送一咧。"
L["Troll to troll, {name}: nobody else know how hard it be to buy boots."] = "巨魔对巨魔，{name}：只有咱们懂买靴子有多难。"
L["Our ancestors had empires, {name}. We got each other. Fair trade, I say."] = "祖先有帝国，{name}，咱们有彼此。要我说，这买卖不亏。"
L["Stay close, {name}. Trolls regenerate; da rest of ya gotta be careful."] = "跟紧点，{name}。巨魔能再生，你们其他人可得小心咧。"
L["Dis crew got style, {name}. Now it got mojo too."] = "这帮人有范儿，{name}。现在还有巫毒了。"
L["We go in together, {name}, we come out together. Dat be da whole plan, mon."] = "一起进去，{name}，一起出来。整个计划就这样，伙计。"
L["Nobody fallin' today, {name}. Bwonsamdi can wait for da next group."] = "今天谁都不许倒，{name}。邦桑迪等下一队吧。"
L["Keep ya head down, {name}. I keep mine up. Somebody gotta look good."] = "你把头低下，{name}。我的头抬着。总得有人负责耍帅。"
L["Raptor formation, {name}: fast, loud, and nobody look back."] = "迅猛龙阵型，{name}：跑得快，嗓门大，谁也不回头。"
L["Big snake show up, {name}, don't run. Ya run, it chase. Stand behind me."] = "大蛇来了，{name}，莫跑。你一跑它就追。躲我后头。"
L["Anybody need more mojo, {name}, just shout. Not too loud; da loa nappin'."] = "谁还要巫毒，{name}，喊一声。小点声，洛阿在打盹咧。"
L["We gonna be a story at Sen'jin, {name}. Let's make it one wit' a happy endin'."] = "咱们要成森金村的故事了，{name}。给它个好结局咧。"
L["Stick close, {name}. My tusks be sharp, but dey can't be everywhere."] = "跟紧点，{name}。我獠牙是尖，可没法哪儿都顾着咧。"
L["Nobody panic, {name}. Panic be bad mojo. Swagger be good mojo."] = "都莫慌，{name}。慌张是坏巫毒，派头是好巫毒。"
L["See a big idol wit' glowin' eyes, {name}? Don't touch it. Trust me on dis."] = "看见眼睛发光的大神像了，{name}？莫碰。这回信我。"
L["Night be da best time for mojo, {name}. Nobody see where it come from."] = "夜里最适合耍巫毒，{name}。没人看得见打哪儿来的。"
L["Da jungle wake up at night, {name}. So do I. Here, dis one fresh."] = "丛林夜里才醒，{name}。我也是。给，这个新鲜的。"
L["Moon be high, {name}, spirits be restless. Dis keep dem off ya."] = "月亮高咧，{name}，灵魂乱窜。这个替你挡着。"
L["Hir'eek, da bat loa, keep late hours too, {name}. Dis from da both of us."] = "蝙蝠洛阿希里克也是夜猫子，{name}。这份算我俩一起送的。"
L["Dis late, {name}, only trolls and trouble be awake. I be da nice one."] = "这么晚了，{name}，醒着的只有巨魔和麻烦。我是好的那个咧。"
L["Stars be out, {name}. Every one a loa, my granny say. Dat a lotta watchers."] = "星星出来咯，{name}。奶奶说每颗都是一位洛阿。好多双眼睛盯着咧。"
L["Such courtesy does you credit, {name}. Nearly as much as it does me."] = "如此礼数，为你增光，{name}。差不多跟为我增的光一样多。"
L["How gracious, {name}. Allow me to return the favour."] = "真是得体，{name}。容我回敬一份。"
L["Thank you, {name}. I haven't felt this radiant since... well, this morning."] = "谢谢你，{name}。我好久没这么光彩照人了……呃，从今早起。"
L["Kind of you, {name}. We sin'dorei never turn down free magic. Ask anyone."] = "你真好，{name}。我们辛多雷从不拒绝免费的魔法。不信你问问。"
L["Exquisite, {name}. I would know; I only accept the exquisite."] = "精致，{name}。这我说了算，我只收精致的东西。"
L["Lovely, {name}. I'll be insufferable about this all day. More than usual."] = "真美，{name}。我会为这事得意一整天。比平时还得意。"
L["Thank you, {name}. It even goes with my gold trim. You have an eye."] = "谢谢你，{name}。连我的金边都配得上。你眼光真好。"
L["Returned in kind, {name}. A prettier kind, admittedly. I can't help it."] = "以礼相还，{name}。当然，还得更漂亮些。我也没办法。"
L["Thank you, {name}. Visit Silvermoon; I'll show you all of it but Murder Row."] = "谢谢你，{name}。来银月城吧，除了谋杀小径，哪儿都带你逛。"
L["Returned, {name}. Unlike Kael'thas, I give things back."] = "奉还，{name}。我可不像凯尔萨斯，拿了东西会还。"
L["Thank you, {name}. I felt that to the tips of my ears, and that's a long way."] = "谢谢你，{name}。一直暖到我耳朵尖——那可是好长一段路。"
L["Thank you, {name}. That was so kind my eyes nearly changed colour again."] = "谢谢你，{name}。太贴心了，我的眼睛差点又变色。"
L["A gift, unasked? Farstriders would call that an ambush. A lovely one, {name}."] = "不请自来的礼物？远行者会称之为伏击。很美的伏击，{name}。"
L["Better than a mana crystal, {name}, and I've given those up. Mostly. Thank you."] = "比法力水晶还好，{name}，虽然那个我戒了。基本戒了。谢谢你。"
L["Quick of you, {name}. Elves live for centuries, and you still beat me to it."] = "好快，{name}。精灵能活几百年，照样被你抢了先。"
L["Charming, {name}. I don't say it lightly. I say it constantly, but not lightly."] = "迷人，{name}。这话我不轻易说。我常说，但从不轻易说。"
L["Thank you, {name}. I'll mention you at court. Well, at a very exclusive picnic."] = "谢谢你，{name}。我会在朝堂上提起你。呃，是在一场极其高端的野餐上。"
L["Thank you, {name}. You've been added to my list of people who deserve me."] = "谢谢你，{name}。你已列入“配得上我的人”名单。"
L["Unasked kindness, {name}! Somebody tell Rommath; he'll want to study it."] = "不求自来的善意，{name}！快告诉罗曼斯，他肯定想拿去研究。"
L["Naturally, {name}. Only the finest for you."] = "那是自然，{name}。给你的只能是最好的。"
L["For you, {name}? Of course. The sun gives freely."] = "给你吗，{name}？当然。太阳向来慷慨。"
L["Patience, {name}. Radiance can't be rushed, only admired."] = "耐心，{name}。光彩不能催，只能欣赏。"
L["Of course, {name}. {buff}, delivered with impeccable posture."] = "当然，{name}。{buff}，以无可挑剔的姿态奉上。"
L["You asked nicely, {name}. In Silvermoon that counts for everything."] = "你问得很得体，{name}。在银月城，这就是一切。"
L["One moment, {name}. I never cast anything without checking my hair."] = "稍等，{name}。不先整理头发，我从不施法。"
L["At once, {name}. Keeping someone waiting is so terribly unfashionable."] = "马上，{name}。让人久等实在太不时髦了。"
L["Certainly, {name}. Stand back a step; my sleeves are enchanted and very wide."] = "当然，{name}。退后一步，我的袖子附了魔，还特别宽。"
L["Magisters would bill you, {name}. Blood Knights would lecture. I merely glow."] = "魔导师会给你开账单，{name}，血骑士会训话。我只负责发光。"
L["At once, {name}. If it goes well, tell everyone. If not, blame the robe."] = "马上，{name}。效果好就告诉大家。不好就怪这件法袍。"
L["At once, {name}. The dragonhawk can wait; it's used to waiting while I dress."] = "马上，{name}。龙鹰能等，我梳妆时它早等惯了。"
L["Gladly, {name}. We once took the Light from a naaru. Asking is so much nicer."] = "乐意，{name}。我们曾从纳鲁那儿硬抢圣光。开口要，体面多了。"
L["Three centuries of casting, {name}, and you're the first to say please."] = "施法三百年，{name}，你是第一个说“请”的。"
L["Gladly, {name}. Silvermoon's brooms sweep themselves, so my hands are free."] = "乐意，{name}。银月城的扫帚会自己扫地，我正好手闲。"
L["Of course, {name}. Arcane Torrent is for the rude. You asked nicely."] = "当然，{name}。奥术洪流是留给没礼貌的人的。你问得很客气。"
L["Anar'alah belore, {name}. May the sun guide you, and light your good side."] = "Anar'alah belore，{name}。愿太阳指引你，也照亮你上镜的那半边脸。"
L["Shorel'aran, {name}. Fight with elegance."] = "Shorel'aran，{name}。战斗也要优雅。"
L["Take this, {name}. Whatever happens out there is merely a setback."] = "拿着，{name}。外面发生什么，都不过是个小挫折。"
L["Everyone deserves to shine, {name}. Only a little less than me, of course."] = "人人都该闪耀，{name}。当然，得比我暗一点。"
L["The sun is with you, {name}. I simply held the door for it."] = "太阳与你同在，{name}。我只是替它开了门。"
L["Go on, {name}, take it. The Sunwell's back; we can afford to be generous."] = "拿去吧，{name}。太阳之井回来了，我们大方得起。"
L["For you, {name}: {buff}, lightly scented with Silvermoon."] = "给你，{name}：{buff}，带着一丝银月城的香气。"
L["Here, {name}. Hand-cast in Silvermoon, so do try not to scuff it."] = "给，{name}。银月城纯手工施放，千万别刮花了。"
L["A little Sunwell for you, {name}. It's been through a lot; treat it kindly."] = "送你一点太阳之井，{name}。它经历了太多，好好待它。"
L["Be prepared, {name}. We weren't, once, and now we have a scar for a road."] = "做好准备，{name}。我们曾经没准备，结果多了条叫死亡之痕的路。"
L["Here, {name}. I only give to the worthy. How convenient that you walked by."] = "给，{name}。我只送给配得上的人。真巧，你正好路过。"
L["Take this, {name}. It's been in my family for moments."] = "拿着，{name}。这是我家祖传的。传了好几秒。"
L["We sin'dorei have lost much, {name}. Never our generosity. Or our cheekbones."] = "我们辛多雷失去了很多，{name}。但慷慨还在。颧骨也在。"
L["Take this, {name}. Should a mana wyrm follow you, it's only jealous."] = "拿着，{name}。要是有法力浮龙跟着你，它只是嫉妒。"
L["Seven thousand years to perfect generosity, {name}. We started last week."] = "慷慨要练七千年才完美，{name}。我们上周才开始。"
L["Take this, {name}. It came through the Undercity orb, so it's slightly dizzy."] = "拿着，{name}。它坐幽暗城的传送宝珠过来的，有点晕。"
L["For you, {name}. It matches everything. I checked, obviously."] = "给你，{name}。百搭。我当然检查过了。"
L["If a ghoul stops you, {name}, say Silvermoon's still standing. They hate that."] = "要是有食尸鬼拦你，{name}，就说银月城还屹立着。它们最恨这个。"
L["The Sunwell shines for us both, {name}."] = "太阳之井为我们闪耀，{name}。"
L["Two sin'dorei in one place, {name}. The day just got twice as elegant."] = "两个辛多雷同在一处，{name}。今天的优雅翻倍了。"
L["You too, {name}? Two sin'dorei, one mirror. We'll have to take turns."] = "你也是，{name}？两个辛多雷，一面镜子。得轮流照了。"
L["Like the phoenix, {name}: we keep rising, and we look good doing it."] = "就像凤凰，{name}：我们一次次重生，而且每次都很好看。"
L["Between sin'dorei, {name}: yes, the Horde is loud. Yes, we're used to it now."] = "辛多雷之间说句实话，{name}：是，部落很吵。是，我们已经习惯了。"
L["Sin'dorei to sin'dorei, {name}: shall we pretend neither of us had a fel phase?"] = "辛多雷对辛多雷，{name}：咱们就当谁都没经历过邪能非主流期？"
L["Sunstrider or Farstrider, {name}, we all stride beautifully."] = "逐日也好，远行也罢，{name}，我们走起来都美。"
L["We both remember Quel'Thalas before the Scourge, {name}. Let's earn the after."] = "我们都记得天灾之前的奎尔萨拉斯，{name}。之后的，靠我们去挣。"
L["Do keep pace, {name}. We have a reputation for arriving beautifully."] = "跟上步调，{name}。我们向来以登场优美著称。"
L["Stand where the light is good, {name}. If we must fight, we'll look splendid."] = "站到光线好的地方，{name}。既然要打，就打得漂亮。"
L["A party at last, {name}. I did dress for one."] = "终于组队了，{name}。我可是按派对打扮的。"
L["The sun shines on all of us, {name}. Mostly on me, but it shares."] = "太阳照耀着我们所有人，{name}。主要照我，但它也分享。"
L["One for you, {name}, and one for the party's image, which I've taken on myself."] = "一份给你，{name}，一份给小队形象，这事我一手包了。"
L["If I fall, {name}, arrange me attractively. The rest I leave to the healer."] = "要是我倒下了，{name}，把我摆得好看点。其余的交给治疗。"
L["Nobody touch the enchanted relics, {name}. Well, I may. I've had training."] = "谁都别碰附魔圣物，{name}。好吧，我可以。我受过训练。"
L["Every expedition needs a ranger, {name}. I'm not one, but I have the boots."] = "每支远征队都需要游侠，{name}。我不是，但我有靴子。"
L["We fight together, {name}, then tell it beautifully. I'll handle the telling."] = "一起战斗，{name}，然后讲得漂漂亮亮。讲的部分归我。"
L["The healer is to be thanked and the tank adored, {name}. Me, admired. Carry on."] = "治疗要感谢，坦克要爱戴，{name}。我嘛，要仰慕。继续吧。"
L["If this goes badly, {name}, we blame the Scourge. It's traditional."] = "要是搞砸了，{name}，就怪天灾军团。传统如此。"
L["Mana potions are for emergencies, {name}. I've had eleven emergencies today."] = "法力药水是应急用的，{name}。我今天已经应急十一次了。"
L["We walked out of the ashes once, {name}. We'll walk out of whatever's ahead."] = "我们从灰烬里走出来过一次，{name}。前面是什么，都走得出来。"
L["The sun has risen, {name}, and so have I. We coordinate."] = "太阳升起了，{name}，我也起了。我们步调一致。"
L["Dawn over Quel'Thalas is lovelier, {name}, but this will do. Just."] = "奎尔萨拉斯的黎明更美，{name}，不过这个也凑合。勉强。"
L["Morning light, {name}. The most flattering hour. For both of us, naturally."] = "晨光，{name}。最显气色的时辰。对我们俩都是，那是自然。"
L["Breakfast in Eversong is fruit, tea and arcane, {name}. Skip to the arcane."] = "永歌森林的早餐是水果、茶和奥术，{name}。直接上奥术吧。"
L["Dawn, {name}. Red and gold across the sky. Somebody's been copying us."] = "黎明，{name}。满天红与金。有人在抄袭我们。"
L["Morning, {name}. Only Silvermoon's arcane guardians are up this early. And me."] = "早，{name}。这么早，银月城只有奥术守卫醒着。还有我。"
L["Your generosity is noted, {name}. In triplicate. Suramar remembers its friends."] = "你的慷慨已记录在案，{name}。一式三份。苏拉玛不忘朋友。"
L["Most gracious, {name}. Allow me to repay you in kind."] = "承蒙厚意，{name}。容我以礼相还。"
L["Thank you, {name}. Ten thousand years under a dome; I'm still practising that."] = "谢谢你，{name}。在屏障里待了一万年，这句我还在练。"
L["A gift with no favour owed? The court would faint. Thank you, {name}."] = "不求回报的馈赠？宫廷里的人会晕过去的。谢谢你，{name}。"
L["Returned, {name}. We keep careful accounts of kindness. And of slights."] = "已奉还，{name}。善意我们一笔笔记着。怠慢也是。"
L["I'll mention you to First Arcanist Thalyssra, {name}. Favourably, even."] = "我会向首席奥术师萨莉瑟拉提起你，{name}。甚至是说好话。"
L["Most kind, {name}. In Suramar we'd hold a banquet. Consider it held."] = "太客气了，{name}。在苏拉玛，这得办场宴会。就当办过了。"
L["I'd send a formal letter of thanks, {name}, but this seemed quicker."] = "本该正式写封感谢信，{name}，不过这样更快。"
L["In Elisande's court a gift hid a knife, {name}. Yours hides none. Thank you."] = "艾利桑德的宫廷讲究礼里藏刀，{name}。你这份只有礼。谢谢你。"
L["Thank you, {name}. My manasaber approves of you, and she approves of no one."] = "谢谢你，{name}。我的魔刃豹认可你，她可谁都不认可。"
L["Exquisite, {name}. Once I'd have said 'adequate'. The world has humbled me."] = "精妙，{name}。换作从前，我只会说“尚可”。世界让我谦虚了。"
L["You fed a mind that once went hungry, {name}. We never forget those who do."] = "你喂饱了一颗曾经饥饿的心智，{name}。这样的人，我们永不忘记。"
L["Centuries of court etiquette, {name}, and 'thank you' still outperforms it all."] = "宫廷礼仪学了几百年，{name}，还是一句“谢谢”最管用。"
L["Thank you, {name}. You're invited to the next masquerade. Masks mandatory."] = "谢谢你，{name}。下次假面舞会请你来。面具必须戴。"
L["Thank you, {name}. Oculeth would open a portal to say so. I'll simply cast."] = "谢谢你，{name}。欧库勒斯会开个传送门来道谢。我就直接施法了。"
L["Of course, {name}. A little arcane polish, just for you."] = "当然，{name}。为你添点奥术光泽。"
L["A reasonable request, {name}. Granted."] = "合理的请求，{name}。准了。"
L["Certainly, {name}. The short version; the long one takes a lunar cycle."] = "当然，{name}。这是简版，完整版要一整个月相周期。"
L["A request, how refreshing. The court only ever made demands. Here, {name}."] = "是请求，真新鲜。宫廷里只有命令。给，{name}。"
L["Done, {name}, and free. Elisande would have charged you a favour for it."] = "好了，{name}，免费。换成艾利桑德，得收你一个人情。"
L["There, {name}. No need to bow. A small nod would be lovely, though."] = "好了，{name}。不必鞠躬。不过点个头会很得体。"
L["Of course, {name}. I've perfected this since before most cities had walls."] = "当然，{name}。大多数城市还没城墙时，我就已练到完美了。"
L["Granted, {name}. I'd ask a favour back, but I'm trying to be less Suramar."] = "准了，{name}。本想讨个人情，可我正努力少点苏拉玛味儿。"
L["Certainly, {name}. Forgive the flourish. We can't cast plainly; we've tried."] = "当然，{name}。见谅这番花哨。我们朴素不来，试过了。"
L["At once, {name}. Elisande once stopped time. I only need a second."] = "马上，{name}。艾利桑德曾让时间停止。我只要一秒。"
L["Of course, {name}. The ley lines here are shallow, but I'll make do."] = "当然，{name}。这里的魔网很浅，不过我将就一下。"
L["Very well, {name}. Stand in the moonlight. Or by that lamp. Lamps will do."] = "好吧，{name}。站到月光下。或者那盏灯旁边。灯也行。"
L["Naturally, {name}. Suramar had a spell for everything. I remember several."] = "自然，{name}。苏拉玛凡事都有法术。我记得几个。"
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "拿着，{name}。奥术的馈赠可不给闲人。"
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "送你一星苏拉玛奥术，{name}。善加利用。"
L["I've gone without magic once, {name}. I don't recommend it. Take this."] = "我断过一次魔法，{name}。不推荐。拿着。"
L["The world outside the dome is so large, {name}. And so under-enchanted. Here."] = "屏障外的世界好大，{name}。附魔也太少了。给。"
L["Arcwine is traditional, {name}, but {buff} travels better."] = "按传统该送奥术酒，{name}，不过{buff}更方便带。"
L["Do take this, {name}. It's rude to refuse Suramar's hospitality. Very rude."] = "请收下，{name}。拒绝苏拉玛的款待很失礼。非常失礼。"
L["Here, {name}. I'm told this is how outsiders say hello. Charming custom."] = "给，{name}。听说外人就是这么打招呼的。迷人的习俗。"
L["Take this, {name}. Magic hoarded is magic spoiled, as Suramar learned."] = "拿着，{name}。魔法囤着会坏，苏拉玛吃过这个亏。"
L["Once, I'd have made you bow for this, {name}. We've all grown."] = "从前，这得让你鞠躬才给，{name}。我们都长进了。"
L["The Kirin Tor do this too, {name}, bless them. Quite nicely, for newcomers."] = "肯瑞托也会这个，{name}，难为他们了。以新手来说，还挺像样。"
L["A gift from under the dome, {name}. Kept fresh for a very, very long time."] = "来自屏障之下的礼物，{name}。保鲜了非常非常久。"
L["Enjoy this, {name}. I used to cast it on nobility. You're an improvement."] = "请享用，{name}。我以前只给贵族施放。你比他们强。"
L["I packed for the outside world like a gala, {name}. Four capes. Take this."] = "我出门收拾行李像赴晚宴，{name}。带了四件披风。这个给你。"
L["Here, {name}. Suramar work: overdesigned, overdecorated, and flawless."] = "给，{name}。苏拉玛出品：设计过度，装饰过度，完美无瑕。"
L["Here, {name}. In Suramar this came with a string quartet. Do hum something."] = "给，{name}。在苏拉玛，这个要配弦乐四重奏。你哼两句吧。"
L["Suramar's children shine together again, {name}."] = "苏拉玛的子民再次一同闪耀，{name}。"
L["Shal'dorei, {name}! You packed arcwine? Outsider wine is just... grapes."] = "夏多雷，{name}！你带奥术酒了吗？外面的酒就只是……葡萄。"
L["Suramar's own, {name}. Try not to be too impressed by the rest of the world."] = "苏拉玛自己人，{name}。外面的世界，别太当回事。"
L["We survived the Legion and the withering, {name}. The rest is small talk."] = "军团和枯法之苦我们都熬过来了，{name}。其他都是闲话。"
L["Our tailors made it out of Suramar too, {name}. Thank the stars."] = "我们的裁缝也逃出了苏拉玛，{name}。感谢群星。"
L["We both remember going hungry, {name}. Never again, for either of us."] = "我们都记得挨饿的滋味，{name}。你我都不会再挨饿了。"
L["Out from under the dome, {name}. Is the sky still this big for you too?"] = "走出屏障了，{name}。你也还觉得天空这么大吗？"
L["Two shal'dorei in one place, {name}. The locals will assume it's a gala."] = "两个夏多雷同在一处，{name}。本地人会以为在办晚宴。"
L["An expedition, {name}! In Suramar this needed six permits and a masquerade."] = "远征，{name}！在苏拉玛，这得批六张许可证，再办一场假面舞会。"
L["The dome kept us safe, {name}. Now we must make do with one another. Gladly."] = "屏障曾保我们平安，{name}。现在只能靠彼此了。乐意之至。"
L["Arcane for everyone, {name}. The court would call it waste. I call it company."] = "人人有奥术，{name}。宫廷会说是浪费，我说这叫作伴。"
L["Do follow my lead, {name}. I've had ten thousand years of walking in step."] = "请跟着我，{name}。一万年里我一直在练齐步走。"
L["In a party one shares one's magic, {name}. How novel. I rather like it."] = "组队时要分享魔法，{name}。真新奇。我挺喜欢。"
L["An outing is like a masquerade, {name}: smile, keep moving, watch for knives."] = "出门就像假面舞会，{name}：微笑，别停步，提防刀子。"
L["Stay in the light of my spells, {name}. It's the most flattering in the party."] = "待在我的法术光里，{name}。全队就这光最显气色。"
L["After Elisande's court, {name}, a party of five is a holiday. Nobody plots."] = "见识过艾利桑德的宫廷，{name}，五人小队简直是度假。没人搞阴谋。"
L["Lost? Follow the one who glows, {name}. That's me. It's always me."] = "迷路了？跟着发光的走，{name}。就是我。永远是我。"
L["If I start lecturing on ley lines, {name}, do interrupt. Politely."] = "要是我开始讲魔网，{name}，请打断我。礼貌地。"
L["I watched my people wither, {name}. I won't watch friends fade. Nobody falls."] = "我眼看族人枯萎，{name}。不会再看着朋友凋零。谁都不许倒下。"
L["Tell me if I'm being grand, {name}. I lose track. It's the millennia."] = "我要是端架子了就提醒我，{name}。我记不清。活了几千年，难免。"
L["Night at last, {name}. Add a few thousand lanterns and it's nearly Suramar."] = "终于入夜了，{name}。再挂几千盏灯，就差不多是苏拉玛了。"
L["Under the dome it was always night, {name}. I feel quite at home."] = "屏障下永远是黑夜，{name}。我觉得很自在。"
L["The stars are out, {name}. We had better ones in Suramar. These will do."] = "星星出来了，{name}。苏拉玛的星星更好。这些凑合吧。"
L["Nightborne, {name}, and here's the night. At last I'm dressed for the hour."] = "夜之子，{name}，夜来了。我这身打扮终于应景了。"
L["At this hour, {name}, Suramar was only just getting dressed for dinner."] = "这个时辰，{name}，苏拉玛才刚开始更衣赴晚宴。"
L["Daylight, {name}. Ten thousand years under a dome, and it still startles me."] = "天亮了，{name}。在屏障下待了一万年，我还是会被吓一跳。"
L["An early hour, {name}. The court never rose before noon. I'm reforming."] = "这么早，{name}。宫廷里没人在中午前起床。我在改过自新。"
L["Morning, {name}. The sun here is so very... unenchanted. Take this instead."] = "早，{name}。这里的太阳真是……毫无附魔。拿这个凑合吧。"
L["Morning, {name}. We warded Suramar against every threat but the sun."] = "早，{name}。我们给苏拉玛设了各种结界，唯独没防太阳。"
L["Dawn, {name}: when the court's gossip went to bed. Here's mine: you look well."] = "黎明，{name}：宫廷八卦该睡了。我的八卦是：你气色真好。"
L["A favour for a favour, {name}! Pleasure doing business."] = "人情换人情，{name}！合作愉快！"
L["Thanks, {name}! Consider your account settled in full."] = "谢啦，{name}！你的账已全部结清。"
L["Aw, {name}. I'd invoice you, but I'm feeling sentimental. It'll pass."] = "哎，{name}。本该给你开发票的，可我一时心软。会好的。"
L["Thanks, {name}! I checked it for fine print. There wasn't any. Weird!"] = "谢啦，{name}！我查了附加条款，居然没有。怪了！"
L["Returned with interest, {name}. Minus the interest. Don't get used to it."] = "连本带利还你，{name}。利息免了。别习惯了。"
L["Much obliged, {name}! You've just been upgraded to preferred customer."] = "多谢，{name}！你刚升级成VIP客户了。"
L["I'd name a rocket after you, {name}, but my rockets never last long. Thanks!"] = "本想用你的名字命名火箭，{name}，可我的火箭都活不长。谢啦！"
L["I'd have charged fifty gold for that, {name}. Let's call us even."] = "这个我本该收五十金币的，{name}。就当扯平了。"
L["Gave first, {name}? Bold business model. I'll match it. Don't tell Undermine."] = "你先送？{name}，大胆的商业模式。我跟了。别告诉安德麦。"
L["A deal where both sides profit, {name}! I'd heard of those. Never seen one."] = "双赢的买卖，{name}！听说过，从没见过。"
L["First free gift since Kezan blew up, {name}. Returning it before I price it."] = "科赞爆炸以来头一份免费礼物，{name}。趁我还没标价，赶紧还你。"
L["Thanks, {name}! I appraised it at priceless. Here's one appraised the same."] = "谢啦，{name}！我估了价：无价。回你一份，同样无价。"
L["Kindness in, kindness out, {name}. Best returns since the kaja'mite boom."] = "善意进，善意出，{name}。卡亚矿热潮以来最好的回报。"
L["Even trade, {name}? My accountant just fainted. He does that around fair deals."] = "公平交易，{name}？我的会计刚晕过去了。他一见公平买卖就晕。"
L["Thanks, {name}! I'd shake on it, but I count my fingers after. Habit, not you."] = "谢啦，{name}！本想握手，可握完我得数手指。习惯，不是针对你。"
L["No haggling at all? Thanks, {name}. I feel cheated. In a nice way."] = "一点都不砍价？谢啦，{name}。我感觉被骗了。被骗得很舒服。"
L["You got it, {name}! Time is money, friend!"] = "没问题，{name}！时间就是金钱，朋友！"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "成交，{name}！记你账上。开玩笑的！"
L["Right away, {name}! Satisfaction guaranteed or your {buff} back."] = "马上，{name}！不满意包退{buff}。"
L["{buff}, {name}! Tips optional. Encouraged. Optional."] = "{buff}，{name}！小费随意。鼓励给。随意。"
L["Fast, cheap or good, {name}? Today you get all three. Don't spread it around."] = "快、便宜、好，{name}，平常三选二。今天全给你。别声张。"
L["Sure thing, {name}! No explosions this time, I promise. Mostly promise."] = "没问题，{name}！这次不会爆炸，我保证。基本保证。"
L["For you, {name}? No charge. Put that in writing and I'll deny it."] = "给你？免费，{name}。敢写成白纸黑字，我就不认账。"
L["Sure, {name}! Quote's zero gold. Lowest I've ever quoted. It stings a little."] = "好嘞，{name}！报价零金币。我报过最低的价。心有点疼。"
L["Coming up, {name}! Full warranty included. Valid until it wears off."] = "马上来，{name}！全程保修。有效期到它消失为止。"
L["Sure, {name}! Sign here, initial there... joking. Mostly. Hold still."] = "好嘞，{name}！这里签字，那里按手印……开玩笑的。基本是。别动。"
L["Free of charge, {name}. If anybody from Bilgewater asks, you paid double."] = "免费，{name}。锈水财阀的人要是问起，就说你付了双倍。"
L["Gadgetzan's got the water trade, {name}. I've got this. Better margins."] = "加基森做水生意，{name}。我做这个。利润更高。"
L["Kezan standard, {name}: fast, loud, and done before you read the terms."] = "科赞标准，{name}：快，响，你还没看完条款就搞定了。"
L["Order received, {name}! Delivery instant, wrapping optional, refunds imaginary."] = "订单已收到，{name}！即时送达，包装可选，退款纯属想象。"
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "这次免费，{name}。可别告诉贸易亲王。"
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "顶级货色，零手续费，{name}。仅限今天！"
L["Free sample, {name}! If you like it, you know where to find me."] = "免费试用，{name}！喜欢的话，你知道上哪儿找我。"
L["Here, {name}. If anything explodes near you today, that was unrelated."] = "给，{name}。今天你附近要是有东西爆炸，跟这个无关。"
L["Goodwill's an asset, {name}. Here's some {buff} for my books."] = "商誉也是资产，{name}。这份{buff}记在我账上。"
L["Take this, {name}. Safety first! Or third. It's on the list somewhere."] = "拿着，{name}。安全第一！或者第三。反正在清单上。"
L["Cast in record time, {name}! The record's mine. I set it just now."] = "破纪录的施法速度，{name}！纪录是我的，刚刚创下的。"
L["Kaja'Cola gives you ideas, {name}. This does the rest. Take it!"] = "卡亚可乐给你灵感，{name}。剩下的交给这个。拿着！"
L["Limited-time offer, {name}! Limited mostly by how long it lasts."] = "限时特惠，{name}！时限就是它的持续时间。"
L["Free trial, {name}! No obligation. Well, a small emotional one."] = "免费试用，{name}！没有任何义务。呃，只欠一点点人情。"
L["Here, {name}. Patent pending. Try it out and tell your rich friends."] = "给，{name}。专利申请中。试试看，再告诉你那些有钱的朋友。"
L["Consider this an investment, {name}. In you. I expect heroic returns."] = "就当是投资，{name}。投你。我期待英雄级的回报。"
L["Take it, {name}! My last shipment sank off Kezan, so everything's clearance."] = "拿着，{name}！上批货沉在科赞外海了，全场清仓。"
L["The Venture Company charges for this, {name}. I'm the competition. Here."] = "风险投资公司这个要收钱，{name}。我是他们的竞争对手。给。"
L["Every goblin has a soft spot, {name}. Mine's small and guarded. You found it."] = "每个地精都有软肋，{name}。我的又小又有人看守。你找到了。"
L["Take this, {name}. It's the only thing I own with no lien on it."] = "拿着，{name}。这是我唯一没被抵押的东西。"
L["You'll be rich someday, {name}. I can tell. Remember who gave you this."] = "你迟早会发财，{name}。我看得出来。苟富贵，勿相忘。"
L["Anything for a fellow entrepreneur, {name}!"] = "都是生意人，好说好说，{name}！"
L["Kezan's finest, together again, {name}. Keep a hand on your coin purse."] = "科赞精英又聚首了，{name}。看好你的钱袋。"
L["Fellow goblin, {name}? Then you know this is a very, very rare discount."] = "同是地精，{name}？那你该知道，这折扣非常非常罕见。"
L["Goblins look after goblins, {name}. It's cheaper than hiring guards."] = "地精照顾地精，{name}。比雇保镖便宜。"
L["Kezan's gone, {name}, but the hustle made it out. Look at us."] = "科赞没了，{name}，可生意经逃出来了。瞧瞧咱们。"
L["Between goblins, {name}, this never happened. I have a reputation."] = "地精之间，{name}，这事从没发生过。我还要名声的。"
L["Bilgewater or Steamwheedle, {name}, we always float to the top. Like oil."] = "锈水也好，热砂也罢，{name}，我们总能浮到最上面。像油一样。"
L["Remember the volcano, {name}? We sold tickets to it. Proud times."] = "还记得那座火山吗，{name}？我们还卖过门票。光荣岁月。"
L["Group rate, {name}! Everybody here gets it half off. Of free."] = "团购价，{name}！全队五折。免费的五折。"
L["Nobody dies on my contract, {name}. The paperwork's a nightmare."] = "我的合同期内谁都不许死，{name}。文书工作是场噩梦。"
L["We split the loot even, {name}. I'll do the maths. Trust me."] = "战利品平分，{name}。账我来算。信我。"
L["Team-building, {name}! You make everybody stronger, and they all owe you."] = "团建时间，{name}！你让大家更强，大家都欠你人情。"
L["Stick together, {name}. Mercenaries cost gold; friends only cost this."] = "抱团走，{name}。雇佣兵要花金币，朋友只花这个。"
L["Everybody's covered, {name}. Not insured, mind. Covered. Different price."] = "大家都罩着了，{name}。注意，不是保险。是罩着。价钱不同。"
L["I read the risk report on this outing, {name}. Short read. It just says 'no'."] = "这趟的风险报告我看了，{name}。很短。就一个字：“别”。"
L["Nobody touches the big red lever, {name}. There's always a big red lever."] = "谁都别碰那根红色大拉杆，{name}。总会有一根红色大拉杆。"
L["If this goes south, {name}, I've got a rocket. Seats one. I'm working on it."] = "要是情况不妙，{name}，我有火箭。只坐得下一个。我在想办法。"
L["We're a company now, {name}. I'm treasurer. The vote was unanimous. Mine."] = "我们现在是公司了，{name}。我是财务。全票通过。就我那一票。"
L["Stay alive, {name}. Nobody's found a way to sell resurrections yet. I'm trying."] = "活着，{name}。还没人找到卖复活的门路。我在研究。"
L["Stay close, {name}. I've already sold the story of this trip. Make it good."] = "跟紧点，{name}。这趟的故事我已经卖出去了。演精彩点。"
L["Early bird gets the gold, {name}! Here's a freebie. Don't tell the other birds."] = "早起的鸟儿有金币，{name}！送你个赠品。别告诉别的鸟。"
L["Morning, {name}! Markets open in an hour. Until then, I'm feeling generous."] = "早，{name}！还有一小时开市。开市前，我心情大方。"
L["Up early, {name}? Smart. Time is money, and it's cheapest in the morning."] = "起得早，{name}？聪明。时间就是金钱，早上最便宜。"
L["Up early, {name}? Me too. Rich goblins sleep in. I'm working on it."] = "起这么早，{name}？我也是。有钱的地精都睡懒觉。我在努力。"
L["Fresh day, fresh ledger, {name}. You're the first entry. The good column."] = "新的一天，新的账本，{name}。你是第一笔。记在好的那栏。"
L["Thank you, {name}! The caravan always repays a kindness. Usually in string."] = "谢谢你，{name}！商队向来知恩图报。通常用绳子报。"
L["How kind, {name}! You're on the caravan's good list now."] = "真好心，{name}！你上了商队的好人名单啦。"
L["Oh, I'll keep this, {name}! I keep everything. Here's one for you."] = "哦，这个我收下了，{name}！我什么都收。这个给你。"
L["Thanks, {name}! Here's yours back. Well, a new one. Hardly used."] = "谢啦，{name}！还你一个。呃，是个新的。几乎没用过。"
L["My ears just went straight up, {name}. That means I'm very pleased."] = "我的耳朵刚刚竖起来了，{name}。意思是我特别开心。"
L["By tonight's campfire, {name}, this story will have a sandworm in it. Thanks!"] = "到了今晚篝火边，{name}，这故事里准会多出一条沙虫。谢啦！"
L["I'd gift-wrap yours, {name}, but all my wrapping is somebody's old map."] = "本想给你包装一下，{name}，可我的包装纸全是别人的旧地图。"
L["The alpacas saw that, {name}. They'll tell everyone how nice you are. Thanks!"] = "羊驼都看见了，{name}。它们会告诉大家你人多好。谢啦！"
L["Thank you, {name}! I'd give you my best button, but this is better. Slightly."] = "谢谢你，{name}！本想送你我最好的纽扣，不过这个更好。稍微好一点。"
L["Ooh, a present! Swapsies, {name}. Here's mine. No takebacks."] = "哇，礼物！交换，{name}。这是我的。不许反悔。"
L["Thanks, {name}! That goes in the good pouch. Not the rock pouch. The good one."] = "谢啦，{name}！这个放进好袋子。不是石头袋。是好袋子。"
L["In Vol'dun that would've cost a whole waterskin, {name}. Thank you!"] = "在沃顿，这得花一整袋水，{name}。谢谢你！"
L["Thanks, {name}! Your name goes on the wagon. Between the alpaca and the dent."] = "谢啦，{name}！你的名字要刻上马车。就在羊驼和那个凹坑中间。"
L["Kindness is the one thing the desert never buried, {name}. Thank you."] = "善意是沙漠唯一埋不住的东西，{name}。谢谢你。"
L["Rakera says repay quick, {name}, before you forget which pocket it's in. Here!"] = "莱克拉说要快点回报，{name}，趁你还没忘了塞哪个兜里。给！"
L["Nobody's given me anything I didn't dig up first, {name}. Thank you!"] = "以前我的东西全是自己挖出来的，没人送过，{name}。谢谢你！"
L["Of course, {name}! Shake the sand out and hold still."] = "当然，{name}！抖掉沙子，站好别动。"
L["Coming right up, {name}! Caravan service, no waiting."] = "马上就来，{name}！商队服务，无需等待。"
L["Sure, {name}! Let me dig it out... rope, rocks, a nice rock... here it is!"] = "好呀，{name}！我翻翻……绳子、石头、好看的石头……有了！"
L["Hold on, {name}! Tail's in the way, one moment... there!"] = "等一下，{name}！尾巴挡着，稍等……好了！"
L["One {buff}, {name}! Only slightly sandy."] = "一份{buff}，{name}！只沾了一点点沙子。"
L["Ask a vulpera and you'll get something, {name}. Usually odd. Not today!"] = "找狐人帮忙总能拿到点东西，{name}。通常很怪。今天不怪！"
L["Yours, {name}! Vulpera love giving things. Almost as much as finding them."] = "给你的，{name}！狐人爱送东西。几乎跟爱捡东西一样。"
L["Here, {name}! Patched it up myself. Holds better than it looks."] = "给，{name}！我自己缝补的。比看着结实。"
L["Sure, {name}! Stand upwind. Sandstorm last week; I'm still shedding it."] = "好呀，{name}！站上风口。上周的沙暴，我现在还在掉沙。"
L["YES! Sorry, {name}, too loud? The desert's very big. You have to shout in it."] = "好！抱歉，{name}，太大声了？沙漠太大了，得用喊的。"
L["Of course, {name}. Caravan rule: nobody asks twice for water or for help."] = "当然，{name}。商队规矩：讨水和求助，都不用开口第二次。"
L["On it, {name}! Small spell, big fox, bigger ears. Wait. Other way round."] = "来了，{name}！小法术，大狐狸，更大的耳朵。等等，说反了。"
L["For you, {name}? Easy! Easier than getting sand out of an alpaca."] = "给你？简单，{name}！比从羊驼毛里抖出沙子简单多了。"
L["Every traveller needs something for the road, {name}. I checked: not a rock."] = "旅人上路总得带点东西，{name}。我检查过了：不是石头。"
L["Keep this, {name}. The desert is long and the water is short."] = "收好，{name}。沙漠漫长，水可不多。"
L["Found this lying around, {name}. Kidding! It's fresh. Take it!"] = "路边捡的，{name}。开玩笑的！新鲜的。拿着！"
L["Here, {name}. Best thing in my pack, and I've got a lot of pack."] = "给，{name}。我包里最好的东西。我的包可大了。"
L["In the dunes you share your shade and your spells, {name}. Here."] = "在沙丘里，阴凉和法术都要分享，{name}。给。"
L["Some {buff} for you, {name}. I'd haggle, but you look busy."] = "给你点{buff}，{name}。本想讨价还价，看你挺忙的。"
L["A gift from the whole caravan, {name}! They'll never know."] = "整个商队送你的礼物，{name}！他们永远不会知道。"
L["For the road, {name}. Roads are the best part. Roads, and snacks."] = "路上用，{name}。路是最棒的部分。路，还有零食。"
L["Here, {name}! I swapped a hat for a thing, and the thing for this. Good trade!"] = "给，{name}！我拿帽子换了个东西，又拿那东西换了这个。划算！"
L["Nobody walks past anybody in the dunes, {name}. Bad luck, and rude. Here."] = "在沙丘里，谁也不会对谁视而不见，{name}。晦气，也没礼貌。给。"
L["My nose says trouble's ahead of you, {name}. Take this. My nose is never wrong."] = "我鼻子说你前面有麻烦，{name}。拿着。我的鼻子从不出错。"
L["Too many spells in my pack, {name}. They jingle. Take one, please."] = "我包里法术太多了，{name}。叮当乱响。拿一个吧，求你了。"
L["If you find anything shiny later, {name}, you know where my ears are. Here!"] = "以后找到亮晶晶的东西，{name}，你知道我的耳朵在哪儿。给！"
L["Wait, {name}! You nearly left without this. Deserts eat people who do that."] = "等等，{name}！你差点没拿这个就走了。沙漠会吃掉这种人的。"
L["Stew's not ready yet, {name}, so this is the starter."] = "炖菜还没好，{name}，先上这个开胃菜。"
L["A fellow wanderer! The caravan is never far, {name}."] = "同为流浪者！商队从不走远，{name}。"
L["Ears up, {name}! Always nice to share a spell with a fellow fox."] = "耳朵竖起来，{name}！跟同类狐狸分享法术，总是开心的。"
L["One vulpera to another, {name}: I've three spare spoons if you need one."] = "狐人对狐人，{name}：我有三把备用勺子，要一把吗？"
L["Vol'dun raised us both, {name}. Sand in the fur, luck in the pack."] = "沃顿养大了我们俩，{name}。毛里有沙，包里有运。"
L["Ears to ears, {name}: between us we've heard everything said in this place."] = "耳朵对耳朵，{name}：这地方说过的话，咱俩全听见了。"
L["Remember the caravan fires, {name}? Everybody sang badly. It was perfect."] = "还记得商队的篝火吗，{name}？大家都唱得好难听。完美极了。"
L["Vol'dun's far behind us, {name}. Half of it followed us here in our fur."] = "沃顿已经很远了，{name}。可它有一半藏在我们毛里跟来了。"
L["Caravan rules, {name}: stay together, share the water, nobody sells the alpaca."] = "商队规矩，{name}：不掉队，水同喝，谁也不许卖羊驼。"
L["Anything shiny in there, {name}, I saw it first. Caravan law."] = "里面有亮晶晶的，{name}，都是我先看到的。商队法规。"
L["One for the party, {name}! A caravan's only as fast as its slowest alpaca."] = "给小队的，{name}！商队的速度取决于最慢的那只羊驼。"
L["Keep your pack shut, {name}. I don't mean to take things. They follow me."] = "把包扣好，{name}。我不是故意拿东西，是它们自己跟着我走。"
L["Lost in a city, {name}, never in a cave. Caves are just houses with no rent."] = "城里会迷路，{name}，山洞里从不。山洞就是免租的房子。"
L["I'm small, {name}, so I'll check the tiny tunnels. You lot take the big ones."] = "我个子小，{name}，小地道我来查。大的归你们。"
L["Shout if you need anything, {name}. I've probably got it. It's probably dented."] = "需要什么就喊，{name}。我多半有。多半还是瘪的。"
L["I'll walk at the back and pick up whatever we drop, {name}. Finders keepers."] = "我走最后，捡大家掉的东西，{name}。谁捡到归谁。"
L["A caravan with no wagon, {name}! Very fast. Very light. Nowhere to nap."] = "没车的商队，{name}！跑得快，走得轻，就是没地儿打盹。"
L["Scouted ahead, {name}. By nose. Smells of danger and very old cheese."] = "探过路了，{name}，用鼻子探的。一股危险味，还有陈年奶酪味。"
L["Everybody fed? Everybody watered? Good. Now this, {name}. Caravan order."] = "都吃饱了？都喝足了？好。接下来是这个，{name}。商队规矩。"
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids."] = "我们狐人夜里赶路，{name}。沙子凉，蝎子困。"
L["Desert nights get cold, {name}. Here, something warm-ish."] = "沙漠的夜很冷，{name}。给，有点暖的东西。"
L["Stars out, {name}. Every one's a signpost if you know how to read it. I don't."] = "星星出来了，{name}。会看的话，每颗都是路标。我不会。"
L["Good hour for foxes, {name}. The ears work best when everything's quiet."] = "正是狐狸的好时辰，{name}。四下越静，耳朵越灵。"
L["Past dark and I'm just waking up, {name}. In the dunes, noon's for napping."] = "天黑了我才刚醒，{name}。在沙丘上，正午是睡午觉的。"
L["I'll curl up in my tail later, {name}. Best blanket I own. First, this."] = "待会儿我裹着尾巴睡，{name}，那是我最好的毯子。先给你这个。"
L["A kindness returned is a kindness doubled, {name}."] = "一份善意回赠，就是两份善意，{name}。"
L["Thank you, {name}. You have restored my balance."] = "谢谢你，{name}。你让我重获平衡。"
L["Somewhere, a Sha just went hungry. Thank you, {name}."] = "某处有只煞刚刚饿肚子了。谢谢你，{name}。"
L["Thank you, {name}. Aysa would bow, Ji would cheer. I will do both, badly."] = "谢谢，{name}。阿伊莎会鞠躬，吉会欢呼。我都来，都不像样。"
L["Thank you, {name}. I will think of you at my next meal, and the one after."] = "谢谢你，{name}。下顿饭我会想起你，下下顿也会。"
L["Chen always said: never refuse a gift. Or a drink. Thank you, {name}."] = "陈常说：礼物不可拒。酒也不可拒。谢谢你，{name}。"
L["I was about to nap, {name}, but this is better. Slightly. Thank you."] = "我正要打个盹，{name}，不过这个更好。稍微好点。谢谢你。"
L["A hozen would have thrown something, {name}. I was raised better. Thank you."] = "换作猢狲，早就扔东西过来了，{name}。我家教好。谢谢你。"
L["That was very pandaren of you, {name}. All that's missing is a dumpling."] = "你这很有熊猫人风范，{name}。就差一个饺子了。"
L["At Halfhill that earns a prize turnip, {name}. I left mine at home. Thank you."] = "这在半山能换个获奖萝卜，{name}。我的落家里了。谢谢你。"
L["Grandmother kept a jar of kindnesses, {name}. Yours goes in; this comes out."] = "奶奶有个装善意的罐子，{name}。你的放进去，这个拿出来。"
L["Thank you, {name}. In the Jade Forest my door is open, and my pantry more so."] = "谢谢你，{name}。在翡翠林，我家门常开，粮仓开得更大。"
L["You move like the Shado-Pan, {name}. I never saw that coming. Thank you."] = "你身手堪比影踪派，{name}。我压根没看见你出手。谢谢你。"
L["Like rain on a rice paddy, {name}. The paddy never says thank you. I do."] = "真是场及时雨，{name}。稻田从不道谢，我会。"
L["Thank you, {name}. Li Li would put this in her travel journal. With drawings."] = "谢谢你，{name}。李李准会把这写进旅行日记，还配插图。"
L["Thank you, {name}. The August Celestials are busy, so I thank you for all four."] = "谢谢你，{name}。至尊天神们都忙，我替四位一起谢了。"
L["Stormstout ale knocks a pandaren flat, {name}. So did that. Thank you."] = "风暴烈酒能把熊猫人放倒，{name}。你这一下也是。谢谢你。"
L["Now we are square, {name}. The first time anyone has called a pandaren square."] = "这下圆满了，{name}。论圆，熊猫人最在行。谢谢你。"
L["Of course, {name}. Patience, and it is done. Patience is the slow part."] = "当然，{name}。耐心些，这就好。慢就慢在耐心上。"
L["With pleasure, {name}. A kind deed is never wasted."] = "乐意效劳，{name}。善举从不白费。"
L["At once, {name}. Quick for a pandaren, which is not saying much."] = "马上，{name}。以熊猫人的标准算快的。这标准不高。"
L["Master Shang Xi said: help whoever asks, {name}. He also said: duck."] = "尚喜大师说过：有求必应，{name}。他还说过：低头。"
L["A Tushui master would make you meditate first, {name}. I will skip that part."] = "换作阿伊莎，得先让你冥想，{name}。这步我跳过。"
L["Anything for you, {name}. Except the last dumpling. Let us not be silly."] = "什么都行，{name}。最后一个饺子除外。别开玩笑了。"
L["One {buff}, {name}, brewed strong. The recipe stays a secret."] = "一份{buff}，{name}，浓酿的。配方保密。"
L["Stand like a crane, {name}: one leg, calm face. Two legs is also fine."] = "学仙鹤站好，{name}：单腿立，神情淡定。两条腿也行。"
L["We never refuse a request, {name}. Only second helpings. No, not those either."] = "我们从不拒绝请求，{name}，只拒绝添饭。不，添饭也不拒绝。"
L["The last to ask me for help, {name}, was an island-sized turtle. You're easier."] = "上个求我帮忙的，{name}，是只岛那么大的龟。你好办多了。"
L["Pandaren help like we cook, {name}: slowly, generously, and far too much of it."] = "熊猫人帮忙跟做饭一样，{name}：慢，大方，而且量太多。"
L["Certainly, {name}. Let me put down my bowl. ...There. That was the hard part."] = "当然，{name}。容我先放下碗……好了。最难的一步完成了。"
L["Yes, {name}. Grandfather said never make guests ask twice. He said it twice."] = "好，{name}。爷爷说过，别让客人开口两次。他说了两次。"
L["Hold still, {name}. I am calm, you are calm, the spell is calm. Nobody panic."] = "别动，{name}。我淡定，你淡定，法术也淡定。谁都别慌。"
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "拿着，{name}。回头一起喝杯茶？"
L["Balance in all things, {name}. Now go with a light heart."] = "凡事求平衡，{name}。放宽心上路吧。"
L["Take this, {name}. A grummle would sell it to you for a luckydo."] = "拿着，{name}。换作咕噜，会拿它跟你换个幸运符。"
L["The jinyu say the waters foretold this, {name}. They say that a lot."] = "锦鱼人说这是水预言过的，{name}。他们常这么说。"
L["The Huojin say act first. The Tushui say think first. I say: here, {name}."] = "吉说先做再想，阿伊莎说先想再做。我说：给，{name}。"
L["A pandaren stood up to give you this, {name}. Treasure it."] = "一个熊猫人为了给你这个站起来了，{name}。好好珍惜。"
L["Fight like a monk, {name}: calm, quick, and then a long lunch."] = "打得像武僧，{name}：又稳又快，然后慢慢吃午饭。"
L["Go gently, {name}. The turtle got where it was going and never hurried once."] = "慢慢来，{name}。那只大海龟从没赶过路，照样到了地方。"
L["You looked like you needed a hug, {name}. This is next best, and less furry."] = "你看着像需要个拥抱，{name}。这个是次选，毛少一点。"
L["If a fight finds you, {name}, roll away. Rolling is very underrated."] = "要是有架找上门，{name}，就用滚地翻。这招太被小看了。"
L["For you, {name}. It is warm, round and full of good intentions. Like me."] = "给你，{name}。热乎、圆滚、满是好意。跟我一样。"
L["Take this, {name}. My kite is stuck in a tree, so I have time for good deeds."] = "拿着，{name}。我的风筝挂树上了，正好有空做好事。"
L["I carried this from Pandaria, {name}. Also a keg. The keg is mine."] = "从潘达利亚带来的，{name}。还有一桶酒。酒归我。"
L["The virmen stole my carrots, {name}, but this they will never get. Here."] = "兔妖偷了我的胡萝卜，{name}，这个它们休想拿走。给。"
L["On the Wandering Isle, {name}, strangers get soup. This travels better."] = "在迷踪岛，{name}，陌生人能喝上一碗汤。这个更好带。"
L["Pandaren look soft, {name}. So does a sack of rice, until it lands on you."] = "熊猫人看着软乎，{name}。一袋米看着也软，直到砸在身上。"
L["Chi-Ji says there is always hope, {name}. I say there is always a spare. Here."] = "赤精说希望总会有的，{name}。我说备用的总会有的。给。"
L["We must share a brew when the road allows, {name}!"] = "得空了一定要一起喝一壶，{name}！"
L["Shen-zin Su would be proud of us both, {name}. Or asleep. Hard to tell."] = "迷踪岛会为我们俩骄傲的，{name}。要么就是在睡觉。说不准。"
L["Two pandaren together, {name}. Somewhere, an innkeeper just felt a chill."] = "两个熊猫人凑一块儿了，{name}。某处有个旅店老板刚打了个寒战。"
L["Liu Lang would approve, {name}: two of us, both a long way from home."] = "刘浪会赞同的，{name}：咱们俩都离家很远。"
L["Tushui or Huojin, {name}, we both left the turtle, and we both miss the food."] = "跟阿伊莎也好，跟吉也罢，{name}，都还惦记龟背上的饭菜。"
L["One pandaren to another, {name}: the brews out here are thin. Share mine later."] = "熊猫人对熊猫人，{name}：外面的酒太淡。回头喝我的。"
L["We both smell of rice wine and road dust, {name}. The smell of home."] = "咱俩都一身米酒味加尘土味，{name}。这就是家的味道。"
L["Pandaren look after pandaren, {name}. Mostly by feeding them. This comes first."] = "熊猫人照顾熊猫人，{name}，主要靠喂。先上这道。"
L["A fight, then a meal, {name}. That is the correct order. Never the reverse."] = "先打架，再吃饭，{name}。顺序是这样的。绝不能反过来。"
L["Stay together, {name}, like dumplings in a steamer. Warm, and ready."] = "抱团，{name}，像蒸笼里的包子。热乎，随时出笼。"
L["We move as one, {name}. Slowly, perhaps, but as one."] = "我们同进同退，{name}。也许慢了点，但同进同退。"
L["Balance, {name}: one fights, one heals, and one carries the snacks. Me."] = "平衡之道，{name}：一个打，一个治，一个带零食。我。"
L["If we fall, {name}, we fall together, and then we nap. Let us not."] = "要倒下，{name}，就一起倒下，然后一起打盹。还是别了吧。"
L["Stay behind me, {name}. I am soft, but I am very wide."] = "站我后面，{name}。我是软，但我够宽。"
L["If we win, {name}, I will cook. If we lose, I will also cook, but sadly."] = "赢了我下厨，{name}。输了我也下厨，只是含着泪。"
L["Everyone breathe, {name}. In, and out. Now hit things, calmly."] = "大家深呼吸，{name}。吸气，呼气。现在，心平气和地开打。"
L["Keep up, {name}. I am in a hurry. It happens to pandaren about once a decade."] = "跟上，{name}。我赶时间呢。熊猫人十年才急这么一回。"
L["A party is like a brew, {name}: odd ingredients, wonderful together. Mostly."] = "小队就像酿酒，{name}：料都古怪，混起来却绝妙。大多时候。"
L["If I fall, {name}, roll me somewhere safe. Carrying me is not an option."] = "我要是倒了，{name}，把我滚到安全的地方。扛是扛不动的。"
L["Pandaren fight like water, {name}: calm, patient, and then suddenly everywhere."] = "熊猫人打架像水，{name}：平静，耐心，然后突然无处不在。"
L["Up before the tea, {name}? Brave. Here, instead of the tea."] = "茶还没泡你就起了，{name}？勇敢。给，这个先替茶。"
L["Morning, {name}. First this, then breakfast, then the second breakfast."] = "早，{name}。先这个，再早饭，然后第二顿早饭。"
L["A new day, {name}, and nobody has spilled anything yet. Let us begin gently."] = "新的一天，{name}，还没人洒过东西。我们轻轻开始吧。"
L["Halfhill's farmers have been up for hours, {name}. I have been up for minutes."] = "半山的农夫早起了好几个钟头，{name}。我才起了几分钟。"
L["Morning mist, {name}. It looked just like home. Then a kobold walked by."] = "晨雾，{name}。看着真像老家。然后走过去一个狗头人。"
L["Good morning, {name}. My stomach woke first and has been giving orders since."] = "早，{name}。我的肚子先醒了，一直在发号施令。"
L["Past my first nap, {name}, and before my second. Quickly, while I'm awake."] = "第一个盹睡完了，第二个还没开始，{name}。趁我醒着，快。"
L["Late, {name}. The brewmasters are asleep. The brews, I suspect, are not."] = "夜深了，{name}。酒仙们睡了。酒嘛，我猜还醒着。"
L["Midnight snack time, {name}. This is the appetiser."] = "夜宵时间到，{name}。这是开胃菜。"
L["Dark already, {name}? Back home, Grandfather's stories would just be starting."] = "天黑了，{name}？在老家，爷爷的故事这会儿才刚开讲。"
L["The moon is round and full tonight, {name}. We have a great deal in common."] = "今晚月亮又圆又满，{name}。我俩共同点可多了。"
L["Your kindness is noted, {name}. Dragons do not forget."] = "你的好意我记下了，{name}。巨龙从不遗忘。"
L["Thank you, {name}. Returned on swift wings."] = "谢谢你，{name}。展开疾翼，即刻回赠。"
L["Wings, fire and scales, {name}, and still you thought I needed help. Touching."] = "有翅膀、有火、有鳞，{name}，你还觉得我需要帮忙。真感人。"
L["I would bow, {name}, but last time my wings cleared a table. Thank you."] = "我本想鞠躬，{name}，可上次翅膀扫翻了一桌子。谢谢你。"
L["That goes straight into my hoard, {name}. Kind deeds are the only gold I keep."] = "这个直接收进我的宝库，{name}。善行是我唯一收藏的黄金。"
L["I was made to be a weapon, {name}. I much prefer this part. Thank you."] = "我生来是被造成武器的，{name}。我更喜欢这部分。谢谢你。"
L["Thank you, {name}. Wrathion would have made a speech of it. I will not."] = "谢谢你，{name}。换作拉希奥，得为这事演讲一番。我就不了。"
L["Returned with a little fire in it, {name}. Only a little. I am practising."] = "回赠你，带了一点火，{name}。就一点。我在练习。"
L["A mortal gift, {name}: small, brief and kind. I am learning to like all three."] = "凡人的礼物，{name}：小、短、暖。这三样我正学着喜欢。"
L["Thank you, {name}. Mortal customs are new to me. Do I pay you? No? Then this."] = "谢谢，{name}。凡人规矩我不熟。要付钱吗？不用？那给你这个。"
L["Thank you, {name}. I have scales where most have feelings. That got through."] = "谢谢你，{name}。我浑身是鳞，刀枪不入，这回却被你打动了。"
L["You're on my list of favourite mortals, {name}. It was empty until today."] = "你上了我的最爱凡人名单，{name}。今天之前它还是空的。"
L["The red in me is grateful, {name}. The black in me is suspicious. The red wins."] = "我体内的红龙在感激，{name}，黑龙在起疑。红龙赢了。"
L["Thank you, {name}. My wings would clap, but wings don't do that. I checked."] = "谢谢你，{name}。我想用翅膀鼓掌，可翅膀不会。我试过了。"
L["A dragon's thanks comes with a roar, {name}. I will spare the neighbours."] = "龙道谢得配一声咆哮，{name}。为了邻居，就免了吧。"
L["Very well, {name}. Stand still, I would hate to singe you."] = "那好，{name}。站着别动，燎到你就不好了。"
L["Granted, {name}. A dragon keeps its word."] = "应允了，{name}。巨龙言出必行。"
L["Certainly, {name}. Stand clear of the tail."] = "当然，{name}。离尾巴远点。"
L["Of course, {name}. Is this still how it is done? I was asleep for a while."] = "当然，{name}。现在还兴这么做吗？我刚打了个盹。"
L["Gladly, {name}. All five dragonflights are in me, and all five say yes."] = "乐意之至，{name}。五大龙军团都在我体内，全票通过。"
L["Right away, {name}. Dragon-sized help, in a conveniently smaller form."] = "马上就来，{name}。巨龙的分量，便携的包装。"
L["Of course, {name}. Neltharion only gave orders. A request is much nicer."] = "当然，{name}。耐萨里奥只会下令，你这声“请”好听多了。"
L["Right away, {name}. Stand back a little; I am still learning how big I am."] = "马上，{name}。退后一点，我还没摸清自己有多大。"
L["Certainly, {name}. Hold still. I have excellent aim and very little practice."] = "当然，{name}。别动。我准头极好，就是没怎么练过。"
L["Of course, {name}. Dragons usually demand tribute. I'm waiving it, this once."] = "当然，{name}。龙一般要收贡品。这次给你免了。"
L["Of course, {name}. Please don't scream. Mortals often do. It's the horns."] = "当然，{name}。请别尖叫，凡人常这样。都怪这对角。"
L["My breath is fire, {name}, so we will do this the other way."] = "我一张嘴就是火，{name}，所以咱们换个方式。"
L["Gladly, {name}. In my day... no. I promised to stop saying 'in my day'. Here."] = "乐意之至，{name}。想当年……不，说好不提“想当年”了。给。"
L["A small magic, {name}, but I cast it with enormous dignity."] = "小小法术，{name}，但我施放得无比庄重。"
L["Take this, {name}. Even a dragon needs allies. Especially one this size."] = "拿着，{name}。龙也需要盟友，尤其是个头这么小的龙。"
L["A gift from the Dragon Isles, {name}. Fly well."] = "来自巨龙群岛的礼物，{name}。祝你飞得顺畅。"
L["Alexstrasza says every life is precious, {name}. I am starting with yours."] = "阿莱克丝塔萨说每条生命都珍贵，{name}。我就从你开始。"
L["I slept through ten thousand years of good deeds, {name}. Catching up now."] = "一万年的好事我都睡过去了，{name}。现在来补课。"
L["Tell them a dragon did this, {name}. It sounds far grander than it was."] = "就说是龙干的，{name}。听着可比实际气派多了。"
L["Scalecommander's orders, {name}. I am not a Scalecommander, but still."] = "鳞长有令，{name}。我不是鳞长，你就当是吧。"
L["Take this, {name}. Ancient dragon magic, only slightly out of date."] = "拿着，{name}。远古巨龙魔法，就是稍微过了保质期。"
L["A dragon giving, {name}, not taking. I am trying something new."] = "龙向来只进不出，{name}。我今天试试新花样。"
L["In visage form I look harmless, {name}. So did Lady Prestor. I really am."] = "人形的我看着人畜无害，{name}。普瑞斯托女士也是。我是真的。"
L["A gift from above, {name}. I landed specially. It took two tries."] = "天降之礼，{name}。我专程降落，试了两次才落稳。"
L["Here, {name}. Every dragon should guard something. I have chosen you, for now."] = "给，{name}。每条龙都得守护点什么。我暂时选了你。"
L["Take this, {name}. It's from five dragonflights, so it clashes with everything."] = "拿着，{name}。五大龙军团出品，五色俱全，跟啥都撞色。"
L["I'd fly you there myself, {name}, but I'm told that is 'kidnapping'. Take this."] = "本想亲自驮你飞过去，{name}，可听说那叫“绑架”。拿这个吧。"
L["Dragons gifted the world at its dawn, {name}. Mine is smaller, and later."] = "巨龙在世界初生时就赠过礼，{name}。我这份小一点，晚一点。"
L["A little essence for you, {name}. It is what I'm made of, so handle it gently."] = "给你一点精华，{name}。我就是这东西做的，轻拿轻放。"
L["Take this, {name}. It will feel warm. Most things do, after I touch them."] = "拿着，{name}。会有点热。被我碰过的东西大多如此。"
L["The Forbidden Reach feels far behind us now, {name}."] = "禁忌离岛如今已远在身后了，{name}。"
L["Two dracthyr in one place, {name}. Mind the wings; there is not room for four."] = "两个龙希尔凑一块，{name}。当心翅膀，这儿可放不下四只。"
L["Remember when the whole world was new to us, {name}? It still is, mostly."] = "还记得那时满世界都新鲜吗，{name}？现在基本也是。"
L["In visage form nobody can tell, {name}. Between us: we look better in scales."] = "化成人形谁也看不出来，{name}。私下说，还是带鳞片好看。"
L["Made for war, {name}, and look at us: sharing. Somebody's plans went wrong."] = "生来为战，{name}，如今却在分享。某位的算盘落空了。"
L["Visage or scales, {name}, I would know one of us anywhere. It is the posture."] = "人形也好，鳞片也罢，{name}，自己人我一眼认得出。看站姿。"
L["Mortals always ask us the same thing, {name}: will we fly them. Still no."] = "凡人总问我们同一件事，{name}：能不能驮他们飞。还是不能。"
L["Between two dracthyr, {name}: the horns never get any easier with hats."] = "龙希尔之间说句私话，{name}：头上长角，帽子永远戴不顺。"
L["Tell me when to breathe fire, {name}. And, please, when not to."] = "该喷火时叫我，{name}。不该喷时，更要叫我。"
L["I woke in a cave full of strangers, {name}. This is far better company."] = "我在一洞陌生人中醒来，{name}。这群伙伴可强多了。"
L["Neltharion made us to fight alone, {name}. We have improved on him."] = "耐萨里奥造我们来单打独斗，{name}。咱们青出于蓝。"
L["Stay clear of my tail, {name}. It hasn't yet learned whose side it's on."] = "离我尾巴远点，{name}。它还没搞清楚自己是哪边的。"
L["A flight of our own, {name}. So this is what the dragons meant."] = "有了自己的龙军团，{name}。巨龙原来是这意思。"
L["If I say 'take cover', {name}, I mean behind my wings. They are good for that."] = "我喊“找掩护”，{name}，是说躲我翅膀后面。翅膀最擅长这个。"
L["Stand beside me, {name}, never in front. I cannot aim my breath politely."] = "站我旁边，{name}，千万别站前面。我的吐息没法礼貌地瞄准。"
L["Leave the big ones to me, {name}. Well, the ones smaller than me. That is most."] = "大个儿的交给我，{name}。呃，比我小的那些。反正大多都是。"
L["Stay close, {name}. I can glide us all down from anywhere. Up is your problem."] = "跟紧，{name}。多高我都能带大家滑翔下去。上去靠你们。"
L["Keep moving, {name}. A dragon in a hurry is grand. One waiting is just big."] = "别停，{name}。赶路的龙威风凛凛，等人的龙就只是块头大。"
L["Tell me the plan slowly, {name}. I was made for battles, not for plans."] = "计划慢慢说，{name}。我是为打仗造的，不是为计划造的。"
L["Mortals live so briefly, {name}. Let us not make today any shorter."] = "凡人寿命太短，{name}。今天就别再让它更短了。"
L["It is good to see one of our own, {name}."] = "能见到自己人真好，{name}。"
L["Our people are few, {name}. That makes each of us count."] = "我们族人不多，{name}，所以个个都算数。"
L["Thank you, {name}. The Alliance looks after its own, and today that's me."] = "谢谢你，{name}。联盟会照顾自己人，今天被照顾的是我。"
L["Kindness answered, {name}. For the Alliance!"] = "好意已回报，{name}。为了联盟！"
L["Stormwind has a statue for every hero, {name}. I'm putting in a word for yours."] = "暴风城英雄人人有雕像，{name}。你那座我去申请。"
L["The Alliance way, {name}: you help me, I help you, a dwarf buys the drinks."] = "联盟之道，{name}：你帮我，我帮你，矮人请喝酒。"
L["Genn would growl, Muradin would hug, {name}. I'll just return it."] = "吉恩会咆哮，穆拉丁会熊抱，{name}。我回个礼。"
L["If the Alliance gave medals for manners, {name}, you'd need a second tabard."] = "联盟要是给礼貌发勋章，{name}，你得再添件战袍来挂。"
L["Returned in full, {name}. An ally who gives first is worth a whole garrison."] = "如数奉还，{name}。先出手的盟友，抵得上一整座要塞。"
L["Thank you, {name}. I'll mention you in my letter home. Mother reads them aloud."] = "谢谢你，{name}。我会在家书里提你。我娘会大声念出来。"
L["The Lion's Pride will hear of this, {name}. At length. Thank you."] = "狮王之傲旅店会听说这事的，{name}。能讲上好久。谢谢你。"
L["The Alliance at its finest, {name}: nobody asked, somebody helped. Thanks."] = "这才是联盟最好的样子，{name}：没人开口，有人帮忙。谢了。"
L["I'll tell everyone on the Deeprun Tram, {name}. It's a long tram. Thank you."] = "我要讲给矿道地铁上每个人听，{name}。地铁可长了。谢谢你。"
L["Most gallant, {name}. If I had a lion on my tabard, it would be purring."] = "真有风度，{name}。我战袍上要是有狮子，这会儿准在打呼噜。"
L["Our kings bicker, {name}, but their people get on splendidly. Thank you."] = "国王们吵来吵去，{name}，百姓倒处得挺好。谢谢你。"
L["The Alliance was forged by folk keeping their word, {name}. Here's mine."] = "联盟靠说话算话的人铸就，{name}。这是我的那份。"
L["Of course, {name}. Allies help each other. It's practically in the name."] = "当然，{name}。盟友互助，“盟”字都写在名字里了。"
L["At once, {name}. The Alliance does not leave a friend wanting."] = "马上，{name}。联盟绝不让朋友空手而归。"
L["Of course, {name}. It's in the Alliance charter. Somewhere near the back."] = "当然，{name}。联盟章程里写着呢，大概在最后几页。"
L["By order of the Alliance, {name}: one {buff}, effective at once."] = "奉联盟之命，{name}：赐{buff}一份，即刻生效。"
L["Anything for an ally, {name}. Within reason. This is well within reason."] = "为了盟友什么都行，{name}。在合理范围内。这个非常合理。"
L["Right away, {name}. SI:7 knew you would ask. I only just found out."] = "马上，{name}。军情七处早料到了，我才刚知道。"
L["Straight away, {name}. The Alliance marches on requests like yours. And bread."] = "马上，{name}。联盟靠你这样的请求行军。还有面包。"
L["Yes, {name}. From Stormwind to Ironforge, 'please' opens every gate."] = "好，{name}。从暴风城到铁炉堡，一个“请”字能开所有城门。"
L["Right away, {name}. I've worn the blue all day hoping somebody would ask."] = "马上，{name}。我穿了一整天蓝衣，就盼着有人开口。"
L["Hold still, {name}. I learned this faster than the Alliance anthem."] = "别动，{name}。这招我学得比联盟军歌还快。"
L["Of course, {name}. Armies win wars; small favours win allies. Here's one."] = "当然，{name}。大军赢得战争，小忙赢得盟友。帮你一个。"
L["For the Alliance, {name}! Stay strong out there. Stronger, now."] = "为了联盟，{name}！在外面挺住。现在更挺得住了。"
L["Onward, {name}. The Alliance is with you."] = "前进吧，{name}。联盟与你同在。"
L["Take this, {name}. Had a gnome made it, it would come with twelve levers."] = "拿着，{name}。要是侏儒做的，准得配十二根拉杆。"
L["Compliments of the Alliance, {name}. We've done these since the Second War."] = "联盟赠品，{name}。老字号，第二次战争那会儿就有了。"
L["Chin up, {name}. Somewhere in Stormwind, a bard is writing about this."] = "振作点，{name}。暴风城有个吟游诗人正写你呢。"
L["Every ally counts, {name}. I counted, actually. You're my favourite so far."] = "每个盟友都算数，{name}。我真数过了，目前最喜欢你。"
L["Anduin would want me to share, {name}, and I'd hate to disappoint him."] = "安度因会希望我分享，{name}，我可不想让他失望。"
L["Take this, {name}. Stormwind's walls can't follow you, so this will have to."] = "拿着，{name}。暴风城的城墙跟不了你，就让这个跟着吧。"
L["Here, {name}. The gryphons get you there; this gets you back."] = "给，{name}。狮鹫送你去，这个保你回。"
L["Alliance rule, {name}: keep your word, your walls, your friends. Here, friend."] = "联盟守则，{name}：守信、守城、守朋友。给，朋友。"
L["Every ally deserves a lion at their back, {name}. I'm the nearest lion."] = "每个盟友背后都该有头雄狮，{name}。离你最近的狮子就是我。"
L["A gift from the Alliance, {name}. Signed, sealed and hand-delivered."] = "联盟的礼物，{name}。签字、盖章、专人送达。"
L["The Alliance never forgets the brave, {name}. Give it something to remember."] = "联盟从不忘记勇者，{name}。去给它留点值得记的事。"
L["Together we stand, {name}. For the Alliance!"] = "团结一心，{name}。为了联盟！"
L["Right, {name}: shields up, heads down, and nobody charges before the plan does."] = "听好，{name}：举盾，低头，计划没冲之前谁都不许冲。"
L["The finest company the Alliance ever fielded, {name}. Or at least the nearest."] = "联盟史上最精锐的队伍，{name}。至少是离得最近的一支。"
L["Together, {name}, we're practically a regiment. A small, well-dressed regiment."] = "凑一起，{name}，我们简直是一个团。小是小，但穿得体面。"
L["Watch each other's backs, {name}. The Alliance was built by people who did."] = "互相照看后背，{name}。联盟就是这样的人建起来的。"
L["Shields together, {name}. The Alliance never won anything in single file."] = "盾牌并拢，{name}。联盟可从没排着单列打赢过。"
L["If this goes in the history books, {name}, let's be a chapter, not a footnote."] = "要是这事写进史书，{name}，咱们要当一章，别当脚注。"
L["Whoever carries the banner, {name}, gets painted looking noble. Volunteers?"] = "谁扛旗，{name}，谁就能被画得英姿飒爽。有人自愿吗？"
L["Dwarven nerve, elven patience, human stubbornness, {name}: the Alliance recipe."] = "矮人的胆量，精灵的耐心，人类的倔强，{name}：联盟配方。"
L["Keep the lion roaring, {name}. Softly, mind. We're sneaking."] = "让雄狮继续咆哮，{name}。小声点，咱们在潜行。"
L["Strength and honour, {name}. And kindness, it turns out. Repaid in full."] = "力量与荣誉，{name}。原来还有善意。如数奉还。"
L["The Horde takes care of its own, {name}."] = "部落从不亏待自己人，{name}。"
L["Strength given, strength returned, {name}. That's all of Horde diplomacy."] = "借我力量，还你力量，{name}。部落的外交全在这儿了。"
L["I'd carve your name on Orgrimmar's gates, {name}, but they're full. Thanks."] = "你的名字该刻上奥格瑞玛大门，{name}，可惜满了。谢啦。"
L["Gallywix would've sent you an invoice, {name}. I'm sending this instead."] = "换作加里维克斯，早给你寄账单了，{name}。我寄这个。"
L["You did not have to do that, {name}. That is why the Horde remembers it."] = "你本不必这么做，{name}。正因如此，部落记住了。"
L["In the Horde we do not say thank you twice, {name}. So: once, and meant."] = "部落的谢谢不说第二遍，{name}。所以就一遍：真心的。"
L["In the Horde a debt is carried like an axe, {name}: openly, and not for long."] = "部落的债像斧子一样扛着，{name}：明着扛，扛不久。"
L["The gate grunts will hear of you, {name}. They'll grunt. It means respect."] = "守门步兵会听说你的事，{name}。他们会哼一声。那是敬意。"
L["The Horde keeps two lists, {name}: grudges and favours. Yours is the short one."] = "部落记两本账，{name}：记仇的和记恩的。你在薄的那本上。"
L["Honour says repay you, {name}. Manners say smile. I'm working on the smile."] = "荣誉让我回报你，{name}。礼貌让我微笑。微笑我还在练。"
L["That landed softer than any zeppelin I've ridden, {name}. Thank you."] = "这一下比我坐过的哪艘飞艇落地都轻，{name}。谢谢你。"
L["Thanks, {name}, in Orcish, Zandali, Thalassian and Gutterspeak. Pick one."] = "谢了，{name}。兽人语、赞达拉语、萨拉斯语、亡灵语版，任选。"
L["Thrall taught the Horde honour, {name}. Nobody had to teach you. Thank you."] = "萨尔教会了部落荣誉，{name}。你却无师自通。谢谢你。"
L["You gave first, {name}. In the Horde that earns first cut of the roast. Here."] = "你先出手的，{name}。在部落，这能分到烤肉第一刀。给。"
L["The Warchief can't thank everyone himself, {name}. He's delegated it to me."] = "大酋长没法亲自谢每个人，{name}。这活儿交给我了。"
L["Consider it done, {name}. For the Horde, and for anyone who asks nicely."] = "包在我身上，{name}。为了部落，也为了每个客气开口的人。"
L["You only had to ask, {name}. The Horde answers."] = "你只管开口，{name}。部落必有回应。"
L["The Horde usually helps with axes, {name}. Today, {buff}."] = "部落平时用斧头帮忙，{name}。今天用{buff}。"
L["Done, {name}. No speeches. The Horde has plenty of those already."] = "好了，{name}。不讲话了，部落的演讲已经够多了。"
L["You asked, {name}. In Orgrimmar, that counts as a formal treaty."] = "你开口了，{name}。在奥格瑞玛，这就算正式条约了。"
L["Asking is no weakness, {name}. Refusing an ally would be."] = "开口求助不是软弱，{name}。拒绝盟友才是。"
L["No need to bang a war drum, {name}. You asked; it's done."] = "用不着敲战鼓，{name}。你开口，就办了。"
L["Of course, {name}. In the Horde, 'please' outranks everyone but the Warchief."] = "当然，{name}。在部落，“请”字的官阶仅次于大酋长。"
L["In Orgrimmar we'd have argued about it first, {name}. Tradition. Here."] = "在奥格瑞玛，咱们得先吵一架，{name}。传统。给。"
L["Consider it requisitioned, {name}. The quartermaster needn't hear about it."] = "就当是征用的，{name}。军需官那边不必知道。"
L["Done, {name}. If anyone asks, I scowled the whole time. I've a reputation."] = "好了，{name}。有人问，就说我全程黑着脸。名声要紧。"
L["Of course, {name}. Horde hospitality: rough edges, full helpings."] = "当然，{name}。部落待客之道：粗是粗了点，管饱。"
L["The Horde came together because somebody always said yes, {name}. Yes."] = "部落能聚起来，是因为总有人说“好”，{name}。好。"
L["For the Horde, {name}! Go with strength. I've just handed you some."] = "为了部落，{name}！愿力量与你同行。我刚给了你一些。"
L["Go with honour, {name}. Victory awaits."] = "带着荣誉前行，{name}。胜利在等着你。"
L["Go and do something worth a song, {name}. Loud songs. The Horde likes loud."] = "去干点值得传唱的事吧，{name}。要大声唱的，部落就爱热闹。"
L["Walk tall, {name}. The Horde always made room for those the world turned away."] = "昂首前行，{name}。被世界拒之门外的人，部落总会留个位置。"
L["Take this, {name}, and a word of Horde wisdom: hit first, apologise never."] = "拿着，{name}，再送你一句部落箴言：先动手，永不道歉。"
L["Victory or death, {name}. I'd prefer victory, so take this."] = "胜利或死亡，{name}。我更想要胜利，所以拿着。"
L["Like a mak'gora, {name}, except everybody wins. Here."] = "像荣誉决斗，{name}，但人人都赢。给。"
L["For the Horde, {name}, and for you. The Horde's big; you're closer."] = "为了部落，{name}，也为了你。部落太大，你离得近。"
L["Here, {name}. Stronger together, they say, and I've just done my half."] = "给，{name}。都说团结更强，我这一半已经尽了。"
L["Carry this, {name}. It weighs less than a Horde banner and flies just as proud."] = "带上这个，{name}。比部落战旗轻，飘得一样威风。"
L["Here, {name}. The Horde feeds its own, arms its own, and now enchants them."] = "给，{name}。部落给自己人管饭、发武器，现在还包施法。"
L["Take this, {name}. Whatever's out there is about to meet the Horde."] = "拿着，{name}。外面那些东西，马上就要见识部落了。"
L["Here, {name}. Wherever you're headed, arrive looking like the Horde sent you."] = "给，{name}。不管去哪，到了都得像是部落派来的。"
L["The Crossroads never turned a traveller away, {name}. It overcharged a few."] = "十字路口从不拒绝旅人，{name}。只是宰过几个。"
L["The Horde raises you tough, {name}. This is for the days tough isn't enough."] = "部落把你养得够硬，{name}。这个留给硬也不够用的日子。"
L["Take this, {name}. A Horde gift: no ribbon, no speech, no refunds."] = "拿着，{name}。部落礼物：不系丝带，不讲话，不退不换。"
L["Stand tall, {name}. Taller than that. The Horde has tauren to keep up with."] = "挺直腰板，{name}。再高点。部落里还有牛头人要追呢。"
L["Our strength is each other, {name}. For the Horde!"] = "我们的力量来自彼此，{name}。为了部落！"
L["Forward, {name}. The Horde advances together. Retreats... never, officially."] = "前进，{name}。部落共同进军。撤退嘛……官方说法是从不。"
L["Together we're a war band, {name}. Apart, we're just loud."] = "聚在一起是战团，{name}。分开了，就只是吵。"
L["Shoulder to shoulder, {name}. Whoever charges first buys the grog."] = "肩并肩，{name}。谁先冲锋谁请喝酒。"
L["Nobody gets left behind, {name}. I've counted us twice."] = "一个都不能少，{name}。我点了两遍。"
L["Rule of the warband, {name}: nobody eats until everybody's back."] = "战团规矩，{name}：人没回齐，谁也不许开饭。"
L["Drums up, {name}. If we can't be quiet, we'll be terrifying."] = "战鼓敲起来，{name}。安静不了，就吓死他们。"
L["The Horde never won a thing alone, {name}. Let's not start now."] = "部落从没单打独斗赢过，{name}。现在也别开这个头。"
L["We fight like the Horde, {name}: all at once, and nobody waits for the signal."] = "按部落的打法来，{name}：一拥而上，谁也不等信号。"
L["Right, {name}. Loot shared, blame shared, glory to whoever shouts first."] = "好，{name}。战利品平分，黑锅平分，荣耀归喊得最快的。"
L["Look at us, {name}. The Warchief would be proud. Mildly. From a distance."] = "瞧瞧咱们，{name}。大酋长会骄傲的。一点点。隔着老远。"
L["Tusks, horns, long ears and bare bone, {name}. Finest warband going."] = "獠牙、犄角、长耳朵、白骨头，{name}。天下第一战团。"
L["The war stories get bigger after, {name}. Let's give them a head start."] = "打完仗，故事只会越吹越大，{name}。咱们先给它开个好头。"
L["Thank you, {name}. Good hearts turn up on every side, and apparently here."] = "谢谢你，{name}。哪一方都有好心人，看来这儿也有。"
L["Thank you, {name}. No side, no title, just kindness. Legends start like this."] = "谢谢，{name}。无门无派，只有善意。传奇都这么开头。"
L["Thank you, {name}. Kindness has no faction, which is handy, since I have none."] = "谢谢你，{name}。善意不分阵营，正好，我也没有阵营。"
L["Thank you, {name}. Whichever side gets you is getting a bargain."] = "谢谢你，{name}。不管哪边得到你，都是捡了大便宜。"
L["Whoever claims me in the end, {name}, I'll remember you first. Thank you."] = "不管最后我归了哪边，{name}，我都先记着你。谢谢。"
L["Strictly neutral, {name}, but gratitude doesn't count. Thank you."] = "我严守中立，{name}，但道谢不算站队。谢谢你。"
L["Thank you, {name}. I carry no banner, so both hands are free to return this."] = "谢谢你，{name}。我不扛旗，两只手都空着，正好回礼。"
L["The Steamwheedle stay neutral for gold, {name}. I do it for moments like this."] = "热砂财团为金币保持中立，{name}。我为这样的时刻。"
L["Neither side has taught me their thanks yet, {name}, so here's the plain kind."] = "两边都还没教我怎么道谢，{name}，先来个原味的。"
L["Thank you, {name}. I stand between two great banners, and still you noticed me."] = "谢谢你，{name}。我夹在两面大旗之间，你还是看见了我。"
L["Two sides at war, {name}, and us being lovely right in the middle. Thank you."] = "两边在打仗，{name}，咱们在正中间岁月静好。谢谢你。"
L["Gladly, {name}, whatever banner you fly. I don't even own a banner."] = "乐意，{name}，不管你打哪面旗。我连旗都没有。"
L["Certainly, {name}. I help everyone. It's the one thing I've decided."] = "当然，{name}。我谁都帮。这是我唯一拿定的主意。"
L["Everyone asks me which side I'm on, {name}. Much nicer to be asked for help."] = "人人都问我站哪边，{name}。被请帮忙可舒服多了。"
L["Of course, {name}. No war council to ask; just me, and I say yes."] = "当然，{name}。不用请示战争议会，我说行就行。"
L["Here you are, {name}. No oath, no colours, no fee."] = "给你，{name}。不宣誓，不站队，不收费。"
L["I can't pick a side yet, {name}, but I can pick a good cause. This is one."] = "阵营我还选不了，{name}，好事我还是会选的。这就是一件。"
L["At once, {name}. I have no side to be on, so for now I am entirely on yours."] = "马上，{name}。我没有阵营可站，所以眼下完全站你这边。"
L["Of course, {name}. Nobody pays me to take sides, so I take requests instead."] = "当然，{name}。没人雇我站队，那我就改接单。"
L["Neutral does not mean unwilling, {name}. It means I help first and argue never."] = "中立不等于不情愿，{name}。意思是先帮忙，永不争论。"
L["Friends can come from any side, {name}. Or, like me, from none in particular."] = "朋友可以来自任何一方，{name}。也可以像我这样，哪边都不是。"
L["Soon they'll hand us tabards, {name}. Until then, we look after each other."] = "迟早会发给我们战袍，{name}。在那之前，我们互相照应。"
L["I haven't chosen a side yet, {name}, so I'm being kind to both. Take this."] = "我还没选边，{name}，所以两头都示好。拿着。"
L["A gift with no strings, {name}. I don't even have a faction to tie them to."] = "不附带任何条件，{name}。我连阵营都没有，条件往哪儿挂？"
L["Go on, {name}. Two whole factions are waiting to argue over us."] = "去吧，{name}。两大阵营正等着抢我们呢。"
L["No quartermaster yet, {name}, so nobody's counting. Have plenty."] = "还没有军需官管账，{name}，没人数。尽管多拿。"
L["Take this, {name}. Neutral ground travels with me; you're standing on some."] = "拿着，{name}。中立地带跟着我走，你脚下就是。"
L["The Argent Dawn helps whoever needs it, {name}. I'm learning from the best."] = "银色黎明谁需要就帮谁，{name}。我在跟最好的老师学。"
L["Booty Bay's rule: no fighting on the docks, {name}. Mine: no refusing a gift."] = "藏宝海湾：码头禁止斗殴，{name}。我这儿：礼物禁止拒收。"
L["The one thing both factions agree on, {name}. They just don't know it yet."] = "两大阵营唯一的共识，{name}。只是他们自己还不知道。"
L["This goes with any tabard, {name}. I made sure by giving it no colours at all."] = "配哪件战袍都行，{name}。我特意没给它上任何颜色。"
L["For you, {name}. Neither Orgrimmar nor Stormwind sent it. It works anyway."] = "给你，{name}。奥格瑞玛没送，暴风城也没送，照样管用。"
L["Here, {name}. I belong to no nation yet, so I practise belonging to everyone."] = "给，{name}。我还不属于任何国度，就先练习属于所有人。"
L["Side by side, {name}, whatever comes."] = "并肩同行，{name}，无论前路如何。"
L["No flag over this party, {name}, just us. That's plenty."] = "这队不打旗号，{name}，只有我们。够了。"
L["One day we'll pick sides, {name}. Today we pick fights, together."] = "总有一天要站队，{name}。今天先组队，一起打架。"
L["Whatever side the rest of the world is on, {name}, I'm on this party's."] = "不管世人站哪边，{name}，我站这支队伍这边。"
L["Neutral in the war, {name}, but very partial to this group."] = "战争中我中立，{name}，对这队却很偏心。"
L["They call us a neutral party, {name}. Nobody said it had to be a quiet one."] = "都叫我们中立小队，{name}。可没说非得是安静的小队。"
L["Whatever we fight today, {name}, it's nothing personal. Just very thorough."] = "今天不管打谁，{name}，都不针对个人。只是打得很彻底。"
L["One side in this party, {name}: ours. Smallest faction on Azeroth. The best."] = "本队只站一边，{name}：咱们。艾泽拉斯最小也最好的阵营。"
L["No orders from any capital, {name}. We choose our road. Let's choose quickly."] = "没有哪座主城给我们下令，{name}。路我们自己选。选快点。"
L["No war to win today, {name}, just this one fight. Much more manageable."] = "今天没有战争要赢，{name}，只有这一仗。好办多了。"
L["One good turn deserves another, {name}."] = "投桃报李，{name}。"
L["Have some {buff} in return, {name}."] = "回赠你一份{buff}，{name}。"
L["Kindness should go both ways, {name}. Thank you."] = "好意该有来有往，{name}。谢谢你。"
L["You went first, {name}, so I'll go second and we'll call it friendship."] = "你先出手，{name}，我接着来，这就叫友谊。"
L["I'd write you a song, {name}, but {buff} is less off-key."] = "本想给你写首歌，{name}，但{buff}没那么跑调。"
L["A gift for a gift, {name}. At this rate we'll be unstoppable by supper."] = "礼尚往来，{name}。照这速度，晚饭前我们就天下无敌了。"
L["All square, {name}. Unless you'd like to make it best of three."] = "扯平了，{name}。除非你想三局两胜。"
L["You started it, {name}. I'm only finishing it."] = "你先动的手，{name}。我来收尾。"
L["That was kind, {name}. The day just got noticeably better. Here's my half."] = "真贴心，{name}。今天明显变好了。这是我那一半。"
L["I was about to do that for you, {name}. Honestly. Here's proof."] = "我正准备这么做呢，{name}。真的。证据在此。"
L["Thank you, {name}. I'll sleep better tonight, and I sleep in a ditch."] = "谢谢你，{name}。今晚能睡得更香了，虽然我睡在沟里。"
L["Two good things today, {name}: your kindness, and the chance to return it."] = "今天有两件好事，{name}：你的好意，还有回报它的机会。"
L["You had me in your debt for all of three seconds, {name}. There."] = "我欠了你足足三秒钟，{name}。还上了。"
L["Gratitude is best served quickly, {name}. Here it is, still warm."] = "谢意要趁热，{name}。给，还热乎着。"
L["Well, {name}, now I have to be a better person all day. Thanks for that."] = "好吧，{name}，这下我一整天都得做个更好的人了。多谢你啊。"
L["Returned with a bow, {name}. A figurative one. My back isn't what it was."] = "鞠躬回礼，{name}。比喻意义上的。我的腰不比从前了。"
L["Thank you, {name}. I'd hoped somebody would start. I'm hopeless at starting."] = "谢谢你，{name}。我一直盼着有人先开头。我最不会开头了。"
L["Thank you, {name}. You've rescued a day I'd written off at breakfast."] = "谢谢你，{name}。这一天我早饭时就放弃了，被你救了回来。"
L["You asked, {name}, and here it is."] = "你要的来了，{name}。"
L["{buff}, coming right up, {name}."] = "{buff}马上就来，{name}。"
L["Gladly, {name}. One moment."] = "很乐意，{name}。稍等一下。"
L["Asked and answered, {name}. Next question?"] = "有问必答，{name}。下一个问题？"
L["Say the word and it's yours, {name}. You said several. Here."] = "一句话的事，{name}。你说了好几句。给。"
L["For you, {name}? Gladly. I was hoping someone would ask."] = "给你？乐意，{name}。正盼着有人开口呢。"
L["Of course, {name}. Easiest yes I'll say all day."] = "当然，{name}。今天最爽快的一次点头。"
L["Right away, {name}. Finally, a question I know the answer to."] = "马上，{name}。总算来了道我会的题。"
L["Of course, {name}. Nobody asks me for anything these days. This is lovely."] = "当然，{name}。最近都没人找我帮忙。这感觉真好。"
L["Hold still, {name}. It works best on people who aren't fidgeting. So, nobody."] = "别动，{name}。这法术对不乱动的人最灵。可惜没人不乱动。"
L["Here you are, {name}. I'd make you wait for effect, but that seems rude."] = "给，{name}。本想吊吊你胃口，可那样太不厚道。"
L["Yes, {name}. I'd have said it sooner if you'd asked sooner."] = "行啊，{name}。你早点问，我早点答应。"
L["Say no more, {name}. Well, say thank you. Then no more."] = "不必多说，{name}。哦，除了“谢谢”。"
L["There, {name}. Next time, don't ask; just stand near me looking hopeful."] = "好了，{name}。下次别开口，站我旁边眼巴巴看着就行。"
L["Coming up, {name}. This is the one part of my day that goes to plan."] = "马上来，{name}。今天总算有件事按计划走了。"
L["Asking nicely works, {name}. Tell everyone. The world could use the news."] = "客气真管用，{name}。去告诉大家，世道缺这种好消息。"
L["At once, {name}. Stay put, or this lands on your shadow instead."] = "这就来，{name}。别动，不然就落你影子上了。"
L["Safe travels, {name}. {buff} packs lighter than a sword."] = "一路平安，{name}。{buff}可比剑轻便多了。"
L["A small blessing for the road, {name}."] = "送你一点路上的祝福，{name}。"
L["Go well, {name}, and come back in one piece."] = "保重，{name}，可要完完整整地回来。"
L["No reason, {name}. It just felt like a {buff} sort of day."] = "没理由，{name}。就觉得今天适合来点{buff}。"
L["Don't mind me, {name}. Just passing, with a spare {buff}."] = "别在意，{name}。路过而已，顺手多了份{buff}。"
L["Consider it a gift, {name}. I'd wrap it, but it glows through the paper."] = "就当是礼物吧，{name}。本想包一下，可它隔着纸都在发光。"
L["Here, {name}. Pass it on when you meet someone who needs it."] = "给，{name}。遇到需要的人，就把它传下去。"
L["Whatever brings you here, {name}, may it go better than planned."] = "不管你为何而来，{name}，愿一切比计划的还顺利。"
L["Just being neighbourly, {name}. Very, very temporary neighbours."] = "邻里之间嘛，{name}。非常、非常临时的邻居。"
L["You looked about to do something brave, {name}. Here, for that."] = "看你像要去干件勇敢的事，{name}。给，壮壮胆。"
L["No need to stop, {name}. It works while you walk."] = "不用停下，{name}。走着也能生效。"
L["Nothing asked, nothing owed, {name}. Nothing to do but go and be splendid."] = "不求什么，也不欠什么，{name}。你只管去大放异彩。"
L["Call it a wager, {name}, that you'll do something worthwhile with it."] = "就当我押了一注，{name}，赌你能拿它干点正事。"
L["A gift from a passing stranger, {name}. The best kind, the old stories say."] = "陌路人送的礼，{name}。老故事里，这种最灵验。"
L["It's rude to pass someone without a greeting, {name}. This is mine."] = "路过不打招呼太失礼了，{name}。这就是我的招呼。"
L["I'm not following you, {name}. We're just going the same way. Here."] = "我可没跟踪你，{name}。只是顺路。给。"
L["If today goes well, {name}, remember me. If it goes badly, I was never here."] = "今天顺利的话，{name}，记得我。不顺的话，我从没来过。"
L["Hold still a moment, {name}. There. Best-prepared person in sight."] = "别动，{name}。好了。放眼望去，就你准备最周全。"
L["Everyone ready? You are now, {name}."] = "都准备好了？这下你也齐活了，{name}。"
L["A little something for the party, {name}."] = "给队伍的一点小心意，{name}。"
L["Stay close, {name}. We go further together."] = "跟紧点，{name}。一起才能走得更远。"
L["House rules, {name}: nobody dies, nobody sulks, everybody eats after."] = "规矩如下，{name}：不许死，不许闹脾气，打完一起吃饭。"
L["There, {name}. Now if this goes badly, it won't be my fault."] = "好了，{name}。这下要是搞砸了，可不怪我。"
L["All set, {name}. I'd give a speech, but we'd be here all day."] = "齐活了，{name}。本想讲两句，可一讲就是一整天。"
L["Look after that, {name}. It's the only one I brought for you."] = "收好了，{name}。给你的就带了这一份。"
L["Now we look the part, {name}. Let's go and be it."] = "像模像样了，{name}。走，去名副其实。"
L["Fresh {buff} all round, {name}. The rest is luck and elbows."] = "{buff}人人有份，{name}。剩下靠运气和胳膊肘。"
L["Right, {name}. If anyone has a plan, now's the time. No? Wonderful. Onward."] = "好，{name}。谁有计划，现在说。没有？太好了，出发。"
L["One each, {name}. Don't swap; they're fitted."] = "一人一份，{name}。别换，量身定做。"
L["Whoever starts the fight, {name}, has to tell the story afterwards."] = "谁先开怪，{name}，回头就由谁来讲这段故事。"
L["Good friends, sharp steel, {buff}. What else is there, {name}?"] = "好友、利刃、{buff}。还缺什么呢，{name}？"
L["Stay where I can see you, {name}. I can't help what I can't find."] = "别离开我视线，{name}。找不着的人我可帮不上。"
L["If this ends up a legend, {name}, I want a line in it. Just the one."] = "要是成了传说，{name}，给我留句台词。一句就够。"
L["Brace yourselves, {name}. And each other, if it comes to that."] = "都站稳了，{name}。实在不行，就互相扶着。"
L["Chin up, {name}. Whatever's ahead has never met this lot before."] = "抬起头，{name}。前方的东西还没见识过咱们。"
L["Do try to stay in one piece, {name}. I'm only equipped for small repairs."] = "尽量保持完整，{name}。我只会小修小补。"
L["Well, {name}, we look ready. Let's go before we find out otherwise."] = "好了，{name}，看着挺像样。趁还没露馅，出发。"
L["If we get lost, {name}, we're exploring. Nobody ever scolded an explorer."] = "要是迷路了，{name}，就说是在探索。没人骂过探险家。"
L["Thank you, {name}. I'd conjure a gift in return, but it would only be water."] = "谢谢你，{name}。想造份礼物回你，可造出来准是水。"
L["Much obliged, {name}. I'll write it up properly later. Several pages."] = "承情，{name}。回头我好好写份报告。好几页那种。"
L["Thank you, {name}. They never taught gratitude at Dalaran. I'm self-taught."] = "谢谢你，{name}。达拉然从不教怎么感恩，我是自学的。"
L["Kind of you, {name}. I'd say it went to my head, but that's my job."] = "有心了，{name}。要说上头……脑子本来就归我管。"
L["Thank you, {name}. I nearly Counterspelled that on reflex. So glad I didn't."] = "谢谢你，{name}。差点本能地法术反制你，还好忍住了。"
L["Even a frost mage would thaw at that, {name}. Thank you."] = "冰霜法师也得被你捂化了，{name}。谢谢。"
L["Thank you, {name}. Noted in my spellbook, between Frost Nova and lunch."] = "谢谢，{name}。记在法术书里，冰霜新星和午饭之间。"
L["Repaid at once, {name}, before I pass a bookshop. I've lost weeks that way."] = "趁没路过书店赶紧还你，{name}。我在书店丢过好几周。"
L["Twenty years in the library, {name}, and no book mentioned people like you."] = "在图书馆泡了二十年，{name}，没一本书写过你这样的人。"
L["Arcane theory says nothing comes free, {name}. Theory was wrong. Thank you."] = "奥术理论说凡事皆有代价，{name}。理论错了。谢谢你。"
L["Of course, {name}. And yes, I suppose you'll want water as well."] = "当然，{name}。行了，我知道，你还要水。"
L["As requested, {name}. Side effects may include footnotes."] = "如你所愿，{name}。副作用可能包括脚注。"
L["At once, {name}. Carefully, too; I've blinked into two walls today."] = "马上，{name}。我会小心，今天已经闪现撞墙两次了。"
L["Gladly, {name}. Knowledge should be shared. The Kirin Tor say so, reluctantly."] = "乐意，{name}。知识该共享——肯瑞托也这么说，不情不愿地。"
L["Certainly, {name}. I'll cast it slowly. The hand movements are the best part."] = "没问题，{name}。我慢慢施，手势才是精华。"
L["Of course, {name}. Think of it as homework, and I've done it for you."] = "当然，{name}。就当是作业，我替你写完了。"
L["Of course, {name}. Antonidas taught me this. He also taught me to duck."] = "当然，{name}。安东尼达斯教的。他还教我抱头蹲下。"
L["At once, {name}. Arcane, not fire. I did check. I always check. Nearly always."] = "马上，{name}。奥术的，不是火。我每次都查。几乎每次。"
L["Certainly, {name}. It's this or a lecture on ley lines, and you've been kind."] = "当然，{name}。本该先讲一课魔网，看你人好，免了。"
L["You asked a mage, {name}. The spell is instant; the explanation is not."] = "你问的是法师，{name}。法术是瞬发的，解释可不是。"
L["I've cast this a thousand times, {name}. Nine hundred and ninety went well."] = "这法术我放过一千次，{name}。其中九百九十次很顺利。"
L["Certainly, {name}. Stand still. Fidgeters have been known to end up woolly."] = "当然，{name}。站好。乱动的人，据说都长出了羊毛。"
L["Here, {name}. I had a spare thought and nowhere to put it."] = "给，{name}。我多了个念头，正好没地方放。"
L["Take this, {name}. I'd add bread, but conjured bread tastes of nothing."] = "拿着，{name}。本想加个面包，可造出来的面包没味儿。"
L["{buff} for you, {name}. No charge, unlike the portals."] = "{buff}免费送，{name}。传送门可不免费。"
L["Here, {name}. Most folk I point at turn into sheep. Today's your lucky day."] = "给，{name}。被我指着的人大多会变成羊。今天你走运。"
L["Nothing on fire, nothing frozen, {name}. I'm branching out."] = "不点火，不冰冻，{name}。我在拓展业务。"
L["For you, {name}. I was practising, and you happened to be the nearest head."] = "给你，{name}。我在练习，你刚好是离我最近的那颗脑袋。"
L["Here, {name}. I'd have portalled it over, but you were standing right there."] = "给，{name}。本想开个传送门送过去，可你就站在这儿。"
L["Kings once hired Dalaran for this, {name}. You get it for nothing."] = "国王们曾花重金请达拉然做这个，{name}。你白拿。"
L["Take this, {name}. It wears off, unlike my last experiment."] = "拿着，{name}。会消退的，不像我上个实验。"
L["For you, {name}: everything I learned in Dalaran, minus the essays."] = "给你，{name}：我在达拉然学到的一切，论文除外。"
L["Here, {name}. Arcane magic is best shared, before it gets ideas of its own."] = "给，{name}。奥术要趁早分享，免得它自己有了主意。"
L["Evocation takes an age, {name}, so I spend my mana where it counts. Here."] = "唤醒要好半天，{name}，所以法力值得花在刀刃上。给。"
L["Here, {name}. A mage who walks past without helping is just a very tall hat."] = "给，{name}。见人不帮的法师，不过是一顶很高的帽子。"
L["Now that you're clever, {name}, stand between me and the angry things."] = "既然你变聪明了，{name}，就站到我和那些暴躁家伙中间。"
L["For the record, {name}, I only blink away when it's tactically sound."] = "郑重声明，{name}，我只在战术需要时才闪现跑路。"
L["Water's on me after, {name}. Please don't ask for it mid-fight."] = "打完我请喝水，{name}。战斗中别找我要。"
L["Minds sharpened, {name}. I'll handle the fire, the frost and the panicking."] = "脑子都磨快了，{name}。火、冰和惊慌失措，都交给我。"
L["Right, {name}: if I say 'Frost Nova', run. If I say 'run', also run."] = "{name}，我喊“冰霜新星”就跑，喊“跑”也跑。"
L["Pyroblast takes a while, {name}. Whatever interrupts it, I take personally."] = "炎爆术读条很长，{name}。谁打断它，我记仇。"
L["If I ice-block, {name}, I'm not frozen with fear. I'm frozen on purpose."] = "我开寒冰屏障，{name}，不是吓僵，是冷静。字面意思。"
L["Portals home are on me after, {name}. Getting there alive is on all of us."] = "回城的传送门我包了，{name}。活着回去，得靠大家。"
L["Anything you'd rather not fight, {name}, point at it. It'll be wool by teatime."] = "不想打的，{name}，指给我。下午茶前就变成羊毛。"
L["I'll drop a Blizzard on them, {name}. You're welcome to watch, from outside it."] = "我给他们下场暴风雪，{name}。欢迎围观——站圈外。"
L["If I start counting under my breath, {name}, that's mana, not nerves."] = "我要是念念有词，{name}，那是算法力值，不是紧张。"
L["If I go quiet, {name}, it's Evocation, not sulking. Usually."] = "{name}，我沉默是在唤醒，不是赌气。通常。"
L["If this goes badly, {name}, I've a teleport home. I'd never use it. Probably."] = "要是打崩了，{name}，我有传送回家。我绝不会用。大概。"
L["How thoughtful, {name}. The Light keeps accounts; I settle mine early."] = "真体贴，{name}。圣光会记账，我提前结清。"
L["Thank you, {name}. I'll put in a good word with the Light. It owes me several."] = "谢谢你，{name}。我会在圣光面前替你美言。它欠我好几个人情。"
L["Thank you, {name}. A small miracle, and I didn't even have to pray for it."] = "谢谢你，{name}。一个小奇迹，我都没祈祷就来了。"
L["Thank you, {name}. My faith in people is restored. It was only resting."] = "谢谢你，{name}。我对人性的信心恢复了。它只是在打盹。"
L["Thank you, {name}. You're in tonight's prayers. Near the top."] = "谢谢你，{name}。今晚祷告有你，排得很靠前。"
L["Healers are rarely on this end of it, {name}. I'd forgotten how nice it is."] = "治疗很少被人照顾，{name}。我都忘了这滋味多好。"
L["Thank you, {name}. You've saved me a prayer, and I'm always one short."] = "谢谢你，{name}。帮我省了次祷告，我老是差一次。"
L["Thank you, {name}. I'd give a sermon on generosity, but you've just given it."] = "谢谢你，{name}。本想讲讲慷慨，你这是身教胜于言传。"
L["Thank you, {name}. I'll light a candle for you. Two. I'm feeling reckless."] = "谢谢你，{name}。为你点根蜡烛。两根。豁出去了。"
L["Even my shadowy side is smiling, {name}. It has no face, so take my word."] = "连我的暗影面都在笑，{name}。它没脸，你信我就好。"
L["Of course, {name}. The Light keeps no hours, and neither, sadly, do I."] = "当然，{name}。圣光全天候营业，可惜我也是。"
L["Straight away, {name}. Most prayers take longer; you've found a shortcut."] = "马上，{name}。一般的祈祷要久得多，你找到捷径了。"
L["Certainly, {name}. The Light shines on those who ask. I just aim it."] = "当然，{name}。圣光照耀祈求者，我只负责瞄准。"
L["With pleasure, {name}. Faith moves mountains; I'm starting smaller."] = "乐意效劳，{name}。信仰能移山，我先挪个小的。"
L["Of course, {name}. Confessions are extra, and I'd rather not hear them."] = "当然，{name}。告解另算，而且我不太想听。"
L["Of course, {name}. Consider this sermon abridged. Very abridged. There, done."] = "当然，{name}。布道精简版。极简版。好了，讲完了。"
L["Certainly, {name}. A warm glow means the Light. A cold one, tell me at once."] = "当然，{name}。暖光是圣光。要是冷光，立刻告诉我。"
L["Of course, {name}. I'll pray it lasts. I'm told I have an in."] = "当然，{name}。祈祷它持久。听说我上头有人。"
L["Certainly, {name}. I heal, I smite, I do funerals. This is the cheerful bit."] = "当然，{name}。治疗、惩击、葬礼我都干，这是最开心的。"
L["Bless you, {name}. No, you didn't sneeze; I'm simply thorough."] = "祝福送到，{name}。打喷嚏的话，是我在念叨你。"
L["Here, {name}. Think of it as a prayer that arrived early."] = "给，{name}。就当是提前应验的祷告吧。"
L["The Light asked me to pass this along, {name}. I'm paraphrasing."] = "圣光托我转交这个，{name}。以上为大意。"
L["Take this, {name}. It saves us both an awkward resurrection later."] = "拿着，{name}。免得待会儿还得尴尬地复活你。"
L["Freely given, {name}. Faith costs nothing. The robes, sadly, did."] = "白送的，{name}。信仰不要钱，可惜这身长袍要。"
L["Here, {name}. Think of me as a small, walking temple. No steps to climb."] = "给，{name}。把我当座会走的小神殿，不用爬台阶。"
L["A blessing for a stranger, {name}. The Light insists there's no such thing."] = "给陌生人的祝福，{name}。圣光坚持说，没有陌生人。"
L["Take this, {name}. No collection plate follows. Look: empty hands."] = "拿着，{name}。后面没有募捐盘。看：两手空空。"
L["Here, {name}. I'd preach, but you look like somebody with somewhere to be."] = "给，{name}。本想布道，可你看着像赶时间的人。"
L["I do weddings, funerals and resurrections, {name}. Mostly the last. Here."] = "婚礼、葬礼、复活我都办，{name}。多半是复活。给。"
L["Here, {name}. I'd float over properly, but levitating in public draws a crowd."] = "给，{name}。本想飘过来，可当众漂浮太招人围观。"
L["Your turn, {name}. Now, I beg you all: make my job boring."] = "轮到你了，{name}。拜托各位：让我闲得无聊吧。"
L["Everyone stay near me, {name}. The Light has a limited range."] = "大家都靠近我，{name}。圣光也有射程限制。"
L["There, {name}. If anyone falls, I'll be very disappointed, then fix it."] = "好了，{name}。谁倒了我会很失望，再把他拉起来。"
L["Done, {name}. I'll be at the back, praying loudly."] = "好了，{name}。我在后排，大声祈祷。"
L["If I scream, {name}, it's a spell, and everything runs. Please don't join in."] = "我一尖叫，{name}，那是法术，怪全会跑。你们别跟着跑。"
L["If I Fade, {name}, I haven't gone. I've just become deeply uninteresting."] = "我要是渐隐了，{name}，人还在，只是毫无存在感。"
L["One shield each, {name}. After that, souls need a lie-down. Pace yourselves."] = "一人一个盾，{name}。之后灵魂得躺会儿。悠着点。"
L["Let's all come back from this the usual way, {name}: walking."] = "都按老规矩回来，{name}：走回来，别飘回来。"
L["I'll keep you alive, {name}. You keep me from having to say 'I told you so'."] = "我保你活着，{name}。你保我不必说“我早说过”。"
L["I prayed over this group, {name}. The Light said 'good luck'. I'll take it."] = "我为这队人祈祷过，{name}。圣光说“祝好运”。行吧。"
L["Thank you, {name}. I'd purr, but I'm not in the right shape for it."] = "谢谢你，{name}。想呼噜两声，可惜形态不对。"
L["Thanks, {name}. My bear form sends a grateful grunt."] = "谢啦，{name}。熊形态的我哼一声致谢。"
L["Much obliged, {name}. My cat form wants to bring you a rabbit. I've said no."] = "多谢，{name}。我的猎豹形态想叼只兔子送你，被我拦下了。"
L["Thank you, {name}. I'll plant a tree in your honour. Give it a century."] = "谢谢你，{name}。我为你种棵树，一百年后来看。"
L["Thank you, {name}. I'd send an owl with a note, but I'd have to be the owl."] = "谢谢你，{name}。想派猫头鹰送信，可那只猫头鹰得是我。"
L["Kindly done, {name}. I felt that in my roots, and I haven't any at the moment."] = "有心了，{name}。暖到我根里了，虽然我现在没长根。"
L["Nature returns everything eventually, {name}. I'm quicker. Thank you."] = "自然终将归还一切，{name}。我比较快。谢谢。"
L["Barkskin keeps most things out, {name}. Kindness got straight through. Thanks."] = "树皮术挡得住大多数东西，{name}。善意直接穿透了。谢谢。"
L["Thank you, {name}. As a bear this would be a hug. Be glad I'm in this shape."] = "谢谢你，{name}。熊形态的话，这就是个熊抱。还好不是。"
L["Certainly, {name}. Give me a moment to remember which shape has hands."] = "当然，{name}。等我想想哪个形态有手。"
L["Of course, {name}. Hold still, like an oak. Oaks are wonderful at it."] = "当然，{name}。站着别动，像棵橡树。橡树最擅长这个了。"
L["Gladly, {name}. The wild shares everything. Well, not the bears."] = "乐意之至，{name}。自然万物共享。呃，熊除外。"
L["Right away, {name}. Pardon the feathers; I've just come from being an owl."] = "马上，{name}。别介意这些羽毛，我刚当完猫头鹰。"
L["Of course, {name}. Nature doesn't take requests, but I do."] = "当然，{name}。大自然不接单，我接。"
L["Gladly, {name}. Ask a tree and you'll wait a year. Ask a druid and it's now."] = "乐意，{name}。求棵树得等一年，找德鲁伊马上就有。"
L["Of course, {name}. The balance tips a little your way. Don't tell the balance."] = "当然，{name}。平衡稍微往你这边偏一点。别告诉平衡。"
L["I'd have run over, {name}, but as a cheetah, and you'd have screamed. Here."] = "本想跑过来，{name}，可得用猎豹形态，你会尖叫的。给。"
L["Of course, {name}. The wild is kind to all who ask. Midges excepted."] = "当然，{name}。荒野善待所有求助者。蚊子除外。"
L["Fresh from the Emerald Dream, {name}. Sorry if I yawn."] = "刚从翡翠梦境出来，{name}。打哈欠请见谅。"
L["Take this, {name}. Nature provides, and I'm its errand runner today."] = "拿着，{name}。大自然供货，今天我负责跑腿。"
L["The wild calls you friend now, {name}. Handy, since most of it has teeth."] = "荒野现在当你是朋友了，{name}。挺好，它们大多长着牙。"
L["I brought you flowers as well, {name}, but I was a stag at the time. Sorry."] = "我还给你带了花，{name}，可当时我是头鹿……抱歉。"
L["Here, {name}. Cenarius would want you to have it. I'm nearly sure."] = "给，{name}。塞纳留斯会希望你拿着。我基本确定。"
L["Nature wants you to have this, {name}. I'm its hands. Today I have hands."] = "大自然想送你这个，{name}。我是它的手。今天我有手。"
L["Take this, {name}. The wild has been watching you, and it's decided you'll do."] = "拿着，{name}。荒野观察你好久了，决定认你了。"
L["If a cat follows you today, {name}, it's only me checking this took."] = "今天要是有只猫跟着你，{name}，那是我在看效果。"
L["For you, {name}. The Moonglade sends its regards. It sends very few."] = "给你，{name}。月光林地向你问好。它很少问候谁。"
L["Nature is cruel, lovely and damp, {name}. This helps with two of those."] = "自然残酷、美丽又潮湿，{name}。这能帮你应付两样。"
L["I tie strangers up in roots most days, {name}. This is the nicer part."] = "平时我用根须缠陌生人，{name}。这算温柔的一面。"
L["Ready, {name}? Now, whatever happens, nobody startle the bear."] = "准备好了，{name}？不管出什么事，别惊着熊。"
L["There, {name}. I'll be the cat, the bear or, if we must swim, the seal."] = "好了，{name}。我能当猫、当熊，要游泳就当海豹。"
L["I've one rebirth in me, {name}. Please, nobody make me choose."] = "我只有一次复生，{name}。拜托，别逼我选人。"
L["Close ranks, {name}. The forest is watching, and it's rooting for us."] = "靠拢点，{name}。森林在看着，对我们的支持根深蒂固。"
L["If I turn into a tree, {name}, things are going badly and I'm fixing them."] = "我要是变成树，{name}，说明情况不妙，我在救场。"
L["I've one Innervate, {name}. Whoever looks most desperate gets it. No acting."] = "我只有一个激活，{name}。谁最绝望给谁。不许演。"
L["If I start glowing and hooting, {name}, that's moonkin. It's a serious form."] = "我要是发光还咕咕叫，{name}，那是枭兽形态。很严肃的。"
L["If it gets crowded, {name}, I'll call a Hurricane. Hold on to your hats."] = "要是太挤，{name}，我就召唤飓风。抓紧帽子。"
L["We move like a herd, {name}. A mixed herd. One of us is sometimes a bear."] = "我们结群行动，{name}。混编兽群，偶尔有只是熊。"
L["Kindness, {name}? My favourite virtue. Just ahead of polishing."] = "善意吗，{name}？我最爱的美德，擦盔甲排第二。"
L["For that, {name}, my best blessing. Not the second best. The best."] = "冲这个，{name}，送你最好的祝福。不是次好，最好。"
L["Virtue rewarded on the spot, {name}! I do love it when that happens."] = "善有善报，当场兑现，{name}！我就爱看这个。"
L["Thank you, {name}. My oath says to repay kindness. I'd do it anyway."] = "谢谢你，{name}。誓言要我知恩图报，不过没它我也会。"
L["I'll judge you favourably, {name}. I judge most things harshly. Thank you."] = "对你，我从轻审判，{name}。别的我一般都从重。谢谢。"
L["Thank you, {name}. My aura just brightened. It does that when I'm touched."] = "谢谢你，{name}。我的光环刚刚亮了。我一感动它就亮。"
L["A kindness, {name}! I'll have it engraved on my shield, beside the dents."] = "一份善意，{name}！我要刻在盾牌上，就在凹痕旁边。"
L["Much obliged, {name}. My warhorse sends thanks as well. He's more reserved."] = "承情，{name}。我的战马也向你致谢。它比较内敛。"
L["I swore to protect the good, {name}. You've just gone to the top of the list."] = "我发誓守护善良之人，{name}。你刚刚排到了名单第一。"
L["By the Light, {name}, of course! I've been hoping somebody would ask."] = "以圣光之名，{name}，当然！我一直盼着有人开口呢。"
L["You have my blessing, {name}. Literally, this time."] = "我祝福你，{name}。这回是字面意思。"
L["Certainly, {name}. Kneel if you like. I won't insist. I'll be delighted."] = "当然，{name}。想跪就跪吧。我不强求。但我会很高兴。"
L["Gladly, {name}. I never run short of blessings. Mana, now and then."] = "乐意之至，{name}。祝福我从来不缺，法力值偶尔缺。"
L["Certainly, {name}. Hold still. My aim is righteous; my gauntlets are clumsy."] = "当然，{name}。别动。我心正，只是手甲笨。"
L["Gladly, {name}. Helping is the oath. Shining while I do it is a bonus."] = "乐意，{name}。帮人是誓言，边帮边发光是附赠。"
L["Of course, {name}. Stand fast, chin up, and look deserving. There. You do."] = "当然，{name}。站稳，抬头，显得受之无愧。嗯，你是。"
L["Of course, {name}. You'd be amazed how rarely anyone asks the tin can for help."] = "当然，{name}。你想不到，很少有人找铁罐头帮忙。"
L["Of course, {name}. A moment while I pick the blessing. I do have favourites."] = "当然，{name}。稍等，我挑个祝福。我也有偏爱的。"
L["The Light asks nothing in return, {name}. I, however, accept thanks."] = "圣光不求回报，{name}。不过我收谢谢。"
L["Go with the Light, {name}. I'll be right behind you, clanking."] = "与圣光同行，{name}。我就跟在你后面，叮叮当当。"
L["The blessing's free, {name}. You've been spared the sermon. This time."] = "祝福免费，{name}。布道就免了。这次先免了。"
L["There, {name}. It won't last forever, so be heroic while it does."] = "好了，{name}。它不会永远有效，趁着还在，英勇点。"
L["Stand tall, {name}. The Light walks with you, and it has excellent posture."] = "挺直腰板，{name}。圣光与你同行，它的站姿可标准了。"
L["Take this, {name}. I'd give you my hammer too, but it's very attached to me."] = "拿着，{name}。本想连锤子也给你，可它离不开我。"
L["Blessings are for handing out, {name}. Hoarding them is frowned upon. By me."] = "祝福就是用来送的，{name}。囤着会被人瞪。被我瞪。"
L["Justice for the wicked, blessings for the rest, {name}. You're the rest."] = "恶人得审判，其余人得祝福，{name}。你是其余人。"
L["Take this, {name}. My libram says to share. It says a lot; this bit I like."] = "拿着，{name}。圣契说要分享。它说的多了，这句我爱听。"
L["Chivalry isn't dead, {name}. It's in heavy armour, and it brought you this."] = "骑士精神没死，{name}。它穿着重甲，给你带来了这个。"
L["Wear it with pride, {name}. Pride's a sin, but only in large amounts."] = "骄傲地戴着吧，{name}。骄傲是罪，但少量无妨。"
L["You're blessed, {name}. If I bubble later, it's strictly tactical."] = "祝福好了，{name}。待会儿我开无敌，纯属战术。"
L["Stand fast, {name}. We have the Light, and I have a very large hammer."] = "坚守阵地，{name}。我们有圣光，我还有一把超大的锤子。"
L["One blessing each, {name}. The Light is generous, but it insists on turns."] = "每人一个祝福，{name}。圣光很慷慨，但要排队。"
L["Splendid, {name}. Now, nobody look directly at me. I'm rather bright today."] = "好极了，{name}。谁都别直视我，我今天有点亮。"
L["Stay inside my aura, {name}. It's warmer than it looks."] = "待在我的光环里，{name}。比看起来暖和。"
L["If I stun something, {name}, hit it while it's thinking things over."] = "我要是晕住了什么，{name}，趁它在反省时揍它。"
L["The glowing ground is mine, {name}. Stand in it freely; it only bites them."] = "地上发光的是我的奉献，{name}。放心站，只烫敌人。"
L["I'll judge them, {name}, and you sentence them. A very efficient court."] = "我来审判，{name}，你来判刑。效率极高的法庭。"
L["If I shout 'for the Light', {name}, it means charge. Or pray. Usually both."] = "{name}，我喊“为了圣光”就是冲锋。或祈祷。通常都有。"
L["Armour polished, hammer blessed, {name}, and my horse is sulking. We're ready."] = "盔甲擦亮，锤子祝圣，{name}，战马在生闷气。准备完毕。"
L["Righteous Fury's up, {name}. Everything wants to hit me now. That's the idea."] = "正义之怒开了，{name}。现在谁都想揍我。要的就是这个。"
L["How kind, {name}. My imp says thank you too. He's lying, but I'm not."] = "真好心，{name}。我的小鬼也说谢谢。它撒谎，我没有。"
L["Thank you, {name}. It's been ages since anyone gave me something uncursed."] = "谢谢你，{name}。好久没人送我不带诅咒的东西了。"
L["Thank you, {name}. I'll repay you with something I didn't find in a crypt."] = "谢谢你，{name}。我会回赠一件不是从墓穴里翻出来的东西。"
L["Most gracious, {name}. I've asked the voidwalker to stop looming at you."] = "承蒙厚意，{name}。我已经叫虚空行者别再杵在你身后了。"
L["Thank you, {name}. I'll tell my demons about you. They'll be baffled."] = "谢谢，{name}。我会跟恶魔们提起你，它们会懵的。"
L["No blood, no bargain, no binding, {name}? What a strange way to trade. Thanks."] = "不要血、不讲价、不立约，{name}？好怪的交易。谢了。"
L["Thank you, {name}. I'll be nicer to my felhunter tonight, in your honour."] = "谢谢你，{name}。为了你，今晚我对地狱猎犬好一点。"
L["How thoughtful, {name}. Everything I'm given, I return. Except souls. Here."] = "真体贴，{name}。别人给我的，我都会还。灵魂除外。给。"
L["Of course, {name}. No soul required. This time."] = "当然，{name}。不用灵魂。这次不用。"
L["You asked a warlock for help, {name}. Bold. I like you already."] = "找术士帮忙，{name}？胆子不小，我已经喜欢你了。"
L["Of course, {name}. The imp offered to help, and I said no, for all our sakes."] = "当然，{name}。小鬼说要帮忙，为了大家好，我拒绝了。"
L["Certainly, {name}. Of all my spells, this is the one I can do at parties."] = "当然，{name}。我所有法术里，就这个能在聚会上表演。"
L["Gladly, {name}. A good deed on my record; the Shadow Council would be appalled."] = "乐意，{name}。档案上添一件好事，暗影议会要吓坏了。"
L["Of course, {name}. Please don't read the book I'm holding. For your own sake."] = "当然，{name}。别看我手里这本书。为你好。"
L["Certainly, {name}. Feel watched? That's only the Eye of Kilrogg. Hold still."] = "当然，{name}。觉得有人盯着？只是基尔罗格之眼。别动。"
L["Of course, {name}. I only curse people who don't ask nicely. You're quite safe."] = "当然，{name}。我只诅咒说话不客气的人。你很安全。"
L["Yes, {name}, it's the one without screaming. Hold still."] = "放心，{name}，是不带尖叫的那个。别动。"
L["Of course, {name}. Going somewhere wet? I won't ask. Warlocks never ask."] = "当然，{name}。要去有水的地方？我不问。术士从不问。"
L["Here, {name}. Don't ask where it came from. Really, don't."] = "给，{name}。别问是从哪儿来的。真的，别问。"
L["Fall in a lake someday, {name}, and you'll think of me fondly."] = "哪天掉进湖里，{name}，你会怀念我的。"
L["Breathe easy, {name}. I'd hate to lose you to anything as dull as water."] = "尽管呼吸，{name}。败给水这么无聊的东西，太可惜了。"
L["Here, {name}. You'll want a soulstone too, but that's a bigger conversation."] = "给，{name}。你还会想要灵魂石，不过那得另外谈。"
L["Take this, {name}. It's the only spell of mine the priests approve of."] = "拿着，{name}。这是我唯一获得牧师认可的法术。"
L["Take this, {name}. My mother still thinks I'm a mage. Let's keep it that way."] = "拿着，{name}。我妈还以为我是法师。别告诉她。"
L["Here, {name}. It isn't green, it doesn't whisper, and it won't follow you home."] = "给，{name}。不是绿的，不会低语，也不会跟你回家。"
L["Here, {name}. Dark magic, used for good. Do tell my old tutor; he'll hate it."] = "给，{name}。黑魔法，用来行善。告诉我导师，他会气死。"
L["Random acts of kindness, {name}. I'm trying them. The imp has complained."] = "随手行善，{name}。我在尝试。小鬼已经投诉了。"
L["Here, {name}. I'm not all curses and fear. Mostly, but not all."] = "给，{name}。我不全是诅咒和恐惧。只是大半。"
L["My grimoire has a chapter on kindness, {name}. It's short, but I've read it."] = "我的魔典有一章讲善良，{name}。很短，但我读过。"
L["Everyone ready, {name}? Souls intact? Good. Let's keep it that way."] = "都准备好了吗，{name}？灵魂都还在？很好，保持住。"
L["Stay close, {name}. The voidwalker takes the hits; I take the credit."] = "跟紧点，{name}。虚空行者挨打，功劳归我。"
L["Swim all you like, {name}. If anyone drifts off, I'll summon them back."] = "尽管游，{name}。谁漂远了，我就把他召唤回来。"
L["Do pet the felhunter, {name}. Just take your spells off first."] = "尽管摸地狱猎犬，{name}。先把法术摘了就行。"
L["If I fear something, {name}, don't chase it. It comes back. Angrier."] = "被我恐惧的怪，{name}，别追。它会回来，更火大。"
L["If my health drops for no reason, {name}, it's Life Tap. Sorry, healer."] = "我无故掉血，{name}，是生命分流。对不住，治疗。"
L["Healthstones after, {name}. For a crisis, mind, not as a snack."] = "治疗石稍后发，{name}。救急用的，不是零食。"
L["Keep clear when I cast Hellfire, {name}. I burn too. That's the tragic part."] = "我放地狱烈焰时离远点，{name}。我也烧。这才叫悲剧。"
L["My imp is on fire, {name}, and he's on our side. Please stop dousing him."] = "我的小鬼着火了，{name}，但它是自己人。别再泼水了。"
L["If something green falls from the sky, {name}, that's mine. Cheer."] = "天上掉下绿东西，{name}，那是我的。欢呼吧。"
L["Thank you, {name}! Sorry, was that loud? I only have the one volume."] = "谢谢你，{name}！抱歉，太大声了？我只有这一个音量。"
L["Much obliged, {name}. No spells to give back, but I do a very sincere shout."] = "多谢，{name}。我没法术可还，但我能吼得非常真诚。"
L["Thanks, {name}. Now I'm twice as angry. In the good way."] = "谢啦，{name}。现在我怒气翻倍了。好的那种。"
L["Thanks, {name}. You've earned a place right behind me. Safest spot there is."] = "谢啦，{name}。你赢得了我身后的位置，全场最安全。"
L["Thank you, {name}. Kindness makes me soft. Luckily I've plenty of armour."] = "谢谢你，{name}。善意让我心软。还好我盔甲够厚。"
L["Thank you, {name}. My armourer thanks you too. I paid for his house."] = "谢谢，{name}。铁匠也谢你。他家房子是我出钱盖的。"
L["Thanks, {name}. I'd bandage something for you, but you look annoyingly fine."] = "谢啦，{name}。想给你包扎点什么，可你完好得气人。"
L["Thank you, {name}. I switched to my grateful stance for that. It's rarely used."] = "谢谢你，{name}。为此我切到了感恩姿态。很少用的。"
L["You've given me magic, {name}. No idea where to keep it. I'll wear it. Thanks."] = "你给了我魔法，{name}。不知放哪儿，就穿身上吧。谢谢。"
L["Owing folk makes me restless, {name}, and restless makes me charge things."] = "欠人情让我坐不住，{name}，坐不住我就想冲锋。"
L["You want a shout, {name}? I was going to shout anyway."] = "要我吼一嗓子，{name}？反正我本来就要吼。"
L["Of course, {name}. Cover your ears; this is the only way I know how."] = "当然，{name}。捂好耳朵，我只会这一种办法。"
L["Right away, {name}. Stay in earshot. For me that's a generous distance."] = "马上，{name}。待在听得见的地方——对我来说挺远的。"
L["Happily, {name}! Words aren't my strength. Volume is."] = "好嘞，{name}！我嘴笨，但嗓门大。"
L["Right, {name}. Deep breath. Not you. Me."] = "好，{name}。我深呼吸，你不用。"
L["Happy to, {name}. First request today that didn't involve lifting something."] = "乐意，{name}。今天头一个不用我扛东西的请求。"
L["Coming up, {name}. It's all in the diaphragm. And the anger. Mostly the anger."] = "马上，{name}。全靠丹田。还有怒气。主要是怒气。"
L["Of course, {name}. Most folk only ask me to stop. This is a nice change."] = "当然，{name}。平时大家只求我住嘴。今天换换口味。"
L["Of course, {name}. Took me years to learn. Years of yelling at trees, mostly."] = "当然，{name}。我学了好多年。主要是对着树吼了好多年。"
L["Consider yourself shouted at, {name}. Affectionately."] = "你已经被我吼过了，{name}。深情地吼。"
L["No incense, no prayers, {name}. Just me, shouting encouragingly."] = "不烧香，不祈祷，{name}。就我在这儿，鼓励地吼。"
L["Chin up, {name}! If anything bothers you, I'll charge it."] = "打起精神，{name}！谁惹你，我就冲锋过去。"
L["There, {name}! Anything that doesn't feel braver now wasn't listening."] = "好了，{name}！谁现在还不觉得更勇敢，那是没在听。"
L["Here, {name}, some courage. Warriors make it by yelling. Don't ask how."] = "给，{name}，一点勇气。战士吼出来的，别问怎么吼的。"
L["Here, {name}. Something sharper than a whetstone: morale."] = "给，{name}。比磨刀石还利的东西：士气。"
L["Take this, {name}. Warriors don't carry spells, so we carry each other."] = "拿着，{name}。战士不带法术，所以我们互相扛着。"
L["Here, {name}. You look about to walk into something big. Walk in harder."] = "给，{name}。看你要去闯大事。那就闯得更猛点。"
L["Here, {name}. No magic in it. Just a warrior believing in you, very firmly."] = "给，{name}。没有魔法，只是一个战士坚定地相信你。"
L["Take this, {name}. Trainers charge for it. I charge at things. Different job."] = "拿着，{name}。训练师收钱，我收人头。分工不同。"
L["Here, {name}. Tell whatever you fight that a warrior vouched for you."] = "给，{name}。跟你的对手说，有个战士给你作保。"
L["That one was for you, {name}. The next one's for whatever's in your way."] = "这一吼是给你的，{name}。下一吼给挡你路的东西。"
L["Listen up, {name}! That's it. That was the whole speech."] = "都听好了，{name}！完了。演讲就这些。"
L["Where's the danger, {name}? Never mind, I'll find it. Face first."] = "危险在哪儿，{name}？算了，我自己找。用脸找。"
L["Right, {name}! I go first, I shout loudest, and nobody touches the healer."] = "听着，{name}！我先上，我吼最大声，谁都不许碰治疗。"
L["Everybody angrier? Good. Onward, {name}, and mind my backswing."] = "都更火大了？很好。前进，{name}，小心我回抡。"
L["I need to be hit before I'm any use, {name}. Nobody panic when it happens."] = "我得先挨打才管用，{name}。到时候谁也别慌。"
L["Bandages are in my pack, {name}. I tied the knots, so they're very secure."] = "绷带在我包里，{name}。结是我打的，牢得解不开。"
L["Right, {name}: I take the hits, you take the credit, and we split the repairs."] = "听好，{name}：我挨打，你领功，修理费平摊。"
L["If I go red and quiet, {name}, that's Berserker Rage. Red and loud, all's well."] = "我脸红不吭声，{name}，是狂暴之怒。脸红还大吼，就没事。"
L["My shield's seen worse than this, {name}. So has my face. Onward."] = "我的盾见过比这更糟的，{name}。我的脸也见过。前进！"
L["A sharper mind for you, {name}. Mine cost me an eyebrow in Dalaran."] = "送你个灵光脑子，{name}。我那个在达拉然赔了条眉毛。"
L["A clearer head for you, {name}. What you fill it with is your own affair."] = "给你个清爽的脑子，{name}。往里装什么，你自己定。"
L["Thoughts humming, {name}? Normal. If they hum back, come and find me."] = "脑子里嗡嗡响，{name}？正常。要是它回你话，来找我。"
L["A little arcane for your thoughts, {name}. Keep the change."] = "给你的思绪添点奥术，{name}。不用找了。"
L["Brilliance, bottled, {name}. The Kirin Tor would charge you for the bottle."] = "瓶装的聪明才智，{name}。换肯瑞托，连瓶子都得收钱。"
L["Sharper wits, {name}. Spend them on spells, locks or riddles; I won't judge."] = "脑子更灵了，{name}。用在法术、开锁还是猜谜上，我都不管。"
L["On loan from the Violet Citadel, {name}. Late returns are fined in sheep."] = "紫罗兰城堡借你的，{name}。逾期不还，罚你变羊。"
L["Clever enough to spot the trap now, {name}. Avoiding it is a separate spell."] = "聪明到能识破陷阱了，{name}。躲开它是另一个法术。"
L["There, {name}. Wiser already: look, you're standing further from me."] = "好了，{name}。已经变聪明了：瞧，你离我站远了。"
L["The one spell of mine that's never set anything alight, {name}. Enjoy."] = "我唯一没点着过东西的法术，{name}。请享用。"
L["A gnome's instructions make sense now, {name}. Still don't follow them."] = "侏儒的说明书你现在能看懂了，{name}。但千万别照做。"
L["Fortitude, {name}: a priest's polite way of saying 'stand in front'."] = "真言术：韧，{name}——“你站前面”的委婉说法。"
L["Every bit of stamina is one less panicked prayer from me, {name}."] = "你每多一点耐力，我就少一次慌张的祷告，{name}。"
L["Tougher already, {name}. Please don't take that as a dare."] = "已经更抗揍了，{name}。拜托别把这当成挑战。"
L["There are other Power Words, {name}. 'Shield', and in emergencies, 'Run'."] = "真言术不止这一个，{name}：还有“盾”，急了还有“跑”。"
L["Sturdier now, {name}. Falls, bears and bad decisions all hurt a bit less."] = "更结实了，{name}。摔跤、熊和馊主意，都没那么疼了。"
L["{buff}, {name}. Three words where 'be tougher' would do."] = "{buff}，{name}。说人话就是：抗揍点。"
L["A little more of you to go round, {name}. Spend it slowly."] = "血条又长了一截，{name}。省着点花。"
L["Sturdier, {name}. Not invincible. I expect I'll be saying that again later."] = "结实了，{name}，但不是无敌。这话待会儿我估计还得再说。"
L["Stubbornness, really, {name}. Dwarves are born with it; the rest of us pray."] = "说白了就是倔，{name}。矮人天生就有，我们只能靠祈祷。"
L["The only armour that never needs repairing, {name}. The smiths hate it."] = "唯一不用修理的护甲，{name}。铁匠恨死它了。"
L["Consider your spirits lifted, {name}. Divinely, as it happens."] = "精神为之一振，{name}。还是神圣牌的。"
L["Like a good night's sleep, {name}, without all the lying down."] = "就像睡了个好觉，{name}，只是不用躺下。"
L["A second helping of spirit, {name}. The Light always insists on seconds."] = "再添一份精神，{name}。圣光跟长辈一样，总劝你再来一碗。"
L["Keep your spirit where it is, {name}. The Spirit Healers are busy enough."] = "灵魂好好待在身上，{name}。灵魂医者已经够忙了。"
L["Cheer up, {name}. That's not advice this time; it's a spell."] = "打起精神来，{name}。这回不是劝你，是法术。"
L["Recover faster, {name}: from fights, from long casts and from my jokes."] = "恢复更快了，{name}：打完架、施完长咒、听完我的冷笑话。"
L["A deep breath's worth of calm, {name}, without having to take one."] = "相当于深呼吸一次，{name}，但不用你亲自吸。"
L["The Light's own second wind, {name}. Don't waste it on arguments."] = "圣光给你续了口气，{name}。别拿去跟人吵架。"
L["Proof against shadow, {name}. I know its tricks; I've borrowed a few."] = "防暗影了，{name}。它那些把戏我懂，我借用过几招。"
L["Should the Void call, {name}, you can now pretend you're out."] = "虚空要是打来，{name}，你现在可以装作不在家。"
L["For when the dark gets personal, {name}. It usually does."] = "以防黑暗针对你，{name}。它向来爱针对人。"
L["The shadows will have to knock first now, {name}."] = "现在暗影得先敲门了，{name}。"
L["The dark still bites, {name}, but now it has to chew."] = "黑暗照样会咬，{name}，只是现在得嚼上好一阵了。"
L["A lining against the dark, {name}. Like a cloak, only on the inside."] = "防黑暗的内衬，{name}。像斗篷，只不过穿在里面。"
L["Curses slide right off you now, {name}. The cultists will take it personally."] = "诅咒沾不上你了，{name}。邪教徒会觉得被针对了。"
L["Priests study the Shadow to guard against it, {name}. Mostly."] = "牧师钻研暗影，是为了防范它，{name}。大多数是。"
L["For crypts, cults and Scholomance, {name}. The dark gets chatty in all three."] = "去墓穴、邪教窝和通灵学院用的，{name}。那三处的黑暗都是话痨。"
L["It won't keep off gloom, {name}. For that you want company. Here I am."] = "它挡不住郁闷，{name}。那得靠人陪。我这不就来了。"
L["Marked by the wild, {name}. The deer will tip their antlers as you pass."] = "印上野性了，{name}。你经过时，鹿都会向你点角致意。"
L["You may smell faintly of moss, {name}. That's how you know it's working."] = "你身上可能有淡淡的苔藓味，{name}。说明生效了。"
L["Mark of the Wild, {name}. The wolves will still bite, but they'll feel bad."] = "野性印记，{name}。狼还是会咬，但会心怀愧疚。"
L["The wild's own seal of approval, {name}. The squirrels were consulted."] = "荒野官方认证，{name}。松鼠们也投过票了。"
L["A little of the wild in you now, {name}. Resist the urge to howl."] = "你身上有点野性了，{name}。忍住别嚎。"
L["Hide, claw and a thick coat, {name}. The wild packs light but thorough."] = "皮糙、爪利、毛厚，{name}。荒野出行，轻装但齐全。"
L["Cenarius signs every one of these, {name}. Well, a tree does, on his behalf."] = "每一份都有塞纳留斯的签名，{name}。好吧，是棵树代签的。"
L["The forest's own armour, {name}. It doesn't clank, and it smells of rain."] = "森林亲制的护甲，{name}。不叮当响，还带着雨的味道。"
L["A tougher hide in seconds, {name}. The oaks took centuries and are furious."] = "几秒就长出厚皮，{name}。橡树熬了几百年，气坏了。"
L["It's a loan from the wild, {name}. Try not to bring it back chewed."] = "荒野借你的，{name}。还的时候别带着牙印。"
L["Anything that bites you now gets a mouthful, {name}."] = "现在谁咬你，{name}，谁就满嘴刺。"
L["Let the boar charge, {name}. It'll leave with regrets and splinters."] = "让野猪冲吧，{name}。它会带着悔恨和一身木刺离开。"
L["Like a rose, {name}: lovely to look at, a mistake to grab."] = "你成带刺的玫瑰了，{name}：好看，碰不得。"
L["Thorns, {name}. I grew them myself, so do be polite to them."] = "荆棘，{name}。我亲手种的，对它们客气点。"
L["A hedge you can wear, {name}. Neatly trimmed; I'm not a barbarian."] = "能穿的树篱，{name}。修剪整齐了，我又不是野蛮人。"
L["Nature never turns the other cheek, {name}. It grows spikes on it."] = "大自然不讲以德报怨，{name}。只讲以刺报怨。"
L["Raptors learn slowly, {name}. This teaches them one bite at a time."] = "迅猛龙学得慢，{name}。这个教它们：咬一口，长一智。"
L["Prickly on the outside, {name}. What's inside is your own business."] = "外头带刺，{name}。里头软不软，你自己知道。"
L["Mind your cloak, {name}. Wool and brambles never did get along."] = "当心你的斗篷，{name}。羊毛和荆棘向来不对付。"
L["Blessing of Kings, {name}. No crown, no throne, no taxes owed."] = "王者祝福，{name}。没王冠，没王座，还免税。"
L["Long may you reign, {name}. For the next while, anyway."] = "吾王万岁，{name}。好吧，至少这一阵。"
L["A little more of everything, {name}. Kings never did settle for less."] = "样样都多一点，{name}。国王向来不肯将就。"
L["A king's blessing, {name}. Worn by better heads than mine, and some worse."] = "王者的祝福，{name}。戴过的脑袋有比我强的，也有差的。"
L["Every strength a little higher, {name}. Kings like to hedge their bets."] = "各项能力都高一点，{name}。国王喜欢多手准备。"
L["Crown not included, {name}. Everything else is, a little."] = "王冠不含在内，{name}。其他的都含一点。"
L["All of you, only more so, {name}. That's what they mean by the royal 'we'."] = "你全方位加强了，{name}。从今往后，可以自称“朕”了。"
L["A blessing fit for royalty, {name}. You'll have to do your own waving."] = "王室级别的祝福，{name}。挥手致意得你自己来。"
L["Stronger, cleverer, hardier, {name}. Kings had advisers for that; you have me."] = "更强、更聪明、更耐打，{name}。国王靠谋臣，你靠我。"
L["Royal treatment, {name}, minus the courtiers and the poisoned wine."] = "王室待遇，{name}，只是没有朝臣，也没有毒酒。"
L["Might doesn't make right, {name}, but it does help the argument."] = "拳头大不代表有理，{name}，但说话更响。"
L["A firmer swing for you, {name}. The Light loves a good follow-through."] = "挥得更有力了，{name}。圣光就爱看漂亮的收招。"
L["Stronger arms, {name}. Kindly point them at something that deserves it."] = "胳膊更有劲了，{name}。麻烦对准该挨揍的东西。"
L["Blessing of Might, {name}. It'll surprise you. It'll surprise them far more."] = "力量祝福，{name}。你会吓一跳，它们会吓得更厉害。"
L["Swing away, {name}. The Light will take the credit if it goes well."] = "尽管挥，{name}。打得好，功劳算圣光的。"
L["Hit harder, {name}. Them, I mean. Not me. Never the paladin."] = "打狠点，{name}。我说打它们。圣骑士打不得。"
L["More weight behind every swing, {name}. The Light calls it conviction."] = "每一挥都更有分量，{name}。圣光管这叫信念。"
L["Doors, crates and ogres will all give way easier now, {name}."] = "门、箱子和食人魔，现在都更容易让路了，{name}。"
L["Your weapon will feel lighter, {name}. It isn't. You're just holier."] = "武器会感觉轻了，{name}。其实没轻，是你更神圣了。"
L["The Light's own elbow grease, {name}. Put it somewhere useful."] = "圣光亲自出力，{name}。使在该使的地方。"
L["Wisdom for you, {name}. I kept a little back for myself. Very little."] = "给你智慧，{name}。我给自己留了一点。很少一点。"
L["Wisdom for your mana, {name}. The other kind still comes from bad decisions."] = "这份智慧管法力值，{name}。另一种，还得吃一堑长一智。"
L["Your mana creeps back on its own now, {name}, like a cat that's forgiven you."] = "法力值现在会自己慢慢回来，{name}，像只原谅了你的猫。"
L["Fewer sips between fights, {name}. The innkeepers will be heartbroken."] = "战斗间少喝几口水，{name}。旅店老板要伤心了。"
L["Drink less, cast more, {name}. The Light's own budget advice."] = "少喝水，多施法，{name}。圣光牌理财建议。"
L["Blessing of Wisdom, {name}: the one blessing that pays for itself."] = "智慧祝福，{name}：唯一能自己回本的祝福。"
L["Mana, {name}, not judgement. Judgement's a separate seal, and I'm keeping it."] = "是法力，{name}，不是判断力。审判是另一个圣印，我留着自用。"
L["Wisdom usually comes with age, {name}. This comes with a paladin. Quicker."] = "智慧通常随年纪来，{name}。这份随圣骑士来，快多了。"
L["The blessing is wise, {name}. The decisions are still entirely ours."] = "祝福很睿智，{name}。主意还得咱自己拿，这就难说了。"
L["A wise blessing for a wise choice, {name}: keeping a paladin around."] = "明智的祝福，配明智的选择，{name}：身边留个圣骑士。"
L["A blessing of quiet, {name}. Monsters will forget whose fault it was."] = "一份安静的祝福，{name}。怪物会忘了是谁惹的祸。"
L["Blessing of Salvation, {name}. You are now somebody else's problem."] = "拯救祝福，{name}。你现在是别人的麻烦了。"
L["Saved, {name}. Not your soul, mind. Just your hide."] = "得救了，{name}。灵魂不管，只保皮肉。"
L["Hit hard, {name}. If anything turns round, look innocent. The Light will."] = "狠狠打，{name}。有东西回头就装无辜。圣光也会装。"
L["The monsters will find you forgettable now, {name}. Today, that's a compliment."] = "现在怪物会觉得你毫无存在感，{name}。今天这是夸你。"
L["Go on, hit it, {name}. It'll blame whoever's wearing the most plate."] = "放心打，{name}。它只会去找板甲最厚的那位算账。"
L["The art of being in the fight, {name}, and out of the argument."] = "输出有你，仇恨没你，{name}。这是门艺术。"
L["The Light's kindest alibi, {name}. Use it often."] = "圣光最贴心的不在场证明，{name}。尽管常用。"
L["The Light will find you easier now, {name}. Try not to squint."] = "圣光现在更容易找到你了，{name}。尽量别眯眼。"
L["Holy Light lands harder on you now, {name}. Please don't make me prove it."] = "圣光术现在对你更有效了，{name}。拜托别逼我验证。"
L["You'll heal easier, {name}. The Light appreciates a willing patient."] = "你更好治了，{name}。圣光就喜欢配合的病人。"
L["Blessing of Light, {name}. Saving you is simpler now. Not that you'll need it."] = "光明祝福，{name}。现在救你更省事了。当然，你用不着。"
L["The Light knows the way to you now, {name}. Let's keep its visits social."] = "圣光现在认得去你那儿的路了，{name}。希望它只是来串门。"
L["A blessing that makes my job easier, {name}. Generous and lazy all at once."] = "一份让我省事的祝福，{name}。又大方又偷懒，两全其美。"
L["Holy Light fits you better now, {name}, like a well-cut tabard."] = "圣光术现在更合你身了，{name}，像件剪裁得体的战袍。"
L["Mending you just got cheaper, {name}. Not that I'd ever send a bill."] = "现在治你更省了，{name}。虽说我从不开账单。"
L["Block a blow now, {name}, and the Light hits back for you. It's petty."] = "现在你格挡一下，{name}，圣光就替你还手。它挺记仇的。"
L["Every blow lands softer now, {name}. Complaints go to the Light."] = "每一击都轻了，{name}。有意见请找圣光投诉。"
L["All the shelter of a temple, {name}, and none of the roof repairs."] = "有神殿的庇护，{name}，却不用修屋顶。"
L["Claim sanctuary, {name}. It's easier when you bring your own."] = "申请庇护吧，{name}。自带庇护所方便多了。"
L["Every blow is a little less rude now, {name}. The Light teaches manners."] = "每一击都客气了点，{name}。圣光教它们懂礼貌。"
L["Nobody can evict you from this sanctuary, {name}. I checked the deeds."] = "这庇护所谁也赶不走你，{name}。房契我查过了。"
L["An ogre's club lands like a pillow now, {name}. A heavy, angry pillow."] = "食人魔的棒子现在跟枕头似的，{name}。又沉又生气的枕头。"
L["Instructions, {name}: hit things harder. There is no page two."] = "说明书，{name}：使劲打。没有第二页。"
L["Your sword arm is sorted, {name}. For the rest of you, see a priest."] = "持剑的胳膊搞定了，{name}。其他部位请找牧师。"
L["Battle Shout, {name}. Not a spell, really. A strongly worded suggestion."] = "战斗怒吼，{name}。其实不算法术，算是措辞强硬的建议。"
L["RAAAGH! That one was for you, {name}. Everyone else just overheard."] = "吼啊啊啊！这声是给你的，{name}。别人只是顺便听到。"
L["Priests pray, mages study, {name}. I clear my throat."] = "牧师祈祷，法师苦读，{name}。我清清嗓子。"
L["Words matter, {name}. Mostly the loud ones."] = "话语有分量，{name}。尤其是嗓门大的。"
L["The shout lasts a few minutes, {name}. The ringing in your ears, rather longer."] = "怒吼持续几分钟，{name}。耳鸣可就久多了。"
L["There were words in that shout once, {name}. They slowed it down."] = "这声吼里原本有词，{name}。嫌拖慢速度，删了。"
L["A little breath from the damned, {name}. They weren't using it."] = "从亡魂那儿匀来一口气，{name}。反正他们用不着。"
L["Unending Breath, {name}. The fish will have so many questions."] = "无尽呼吸，{name}。鱼会有一肚子问题。"
L["Stay down as long as you like, {name}. Something else is holding its breath."] = "想在水下待多久都行，{name}。反正憋气的是别的东西。"
L["Swim deep, {name}. If a murloc asks, you're only visiting."] = "往深处游吧，{name}。鱼人问起，就说串门。"
L["Air from a place where air isn't strictly air, {name}. Breathe it anyway."] = "从一个空气不太算空气的地方弄来的，{name}。照吸不误。"
L["The Vile Reef awaits, {name}. Try not to find out how it earned the name."] = "邪恶海礁在等你，{name}。别去弄清它为啥叫这名儿。"
L["Dropped something in a lake, {name}? Now's your chance."] = "有东西掉湖里了，{name}？现在正好去捞。"
L["No gills, {name}. I read the small print; gills were extra."] = "没有鳃，{name}。条款小字我看了，鳃得加钱。"
L["Folk will think we're duelling, {name}. Thanks for the {gift}."] = "别人要以为我们在决斗了，{name}。谢谢你的{gift}。"
L["{gift} for {buff}. No auctioneer's cut, {name}."] = "{gift}换{buff}，{name}，拍卖行不抽成。"
L["Beaten to it, {name}! Your {gift} was quicker than my manners."] = "被你抢先了，{name}！你的{gift}比我的礼数还快。"
L["{gift} in, {buff} out. Finest economy in all Azeroth."] = "{gift}进，{buff}出。艾泽拉斯最健康的经济。"
L["{gift}, for me? All I have is this, {name}, but it's heartfelt."] = "{gift}，给我的？我只有这个，{name}，但是真心的。"
L["Your {gift} fits perfectly, {name}. Did you measure me?"] = "你的{gift}太合身了，{name}。你量过我尺寸？"
L["A treaty in spells, {name}: {gift} for {buff}."] = "法术条约，{name}：{gift}换{buff}。"
L["{gift}! I feel taller already. Have some {buff}."] = "{gift}！我感觉都长高了。回你点{buff}。"
L["I was about to ask for {gift}, {name}. You read my mind."] = "我正想要{gift}呢，{name}。你会读心吗？"
L["Your {gift} still fizzes, {name}. Here's some fizz back."] = "你的{gift}还在冒泡，{name}。回你点泡泡。"
L["Such a kind {gift}, {name}. I'll tell the whole inn. Twice."] = "{gift}真贴心，{name}。全旅店都得听我讲两遍。"
L["You cast {gift} first, {name}? My mother would despair of me."] = "你先给了我{gift}，{name}？我娘准骂我没礼数。"
L["I'll remember your {gift} fondly, {name}. Until it wears off."] = "我会深情铭记你的{gift}，{name}。直到它消失。"
L["{gift} for {buff}, free. Somewhere, a goblin weeps."] = "{gift}换{buff}，免费。某处有个地精在哭。"
L["Your {gift}, my {buff}. We'll be unbearable now."] = "你的{gift}，我的{buff}。这下要飘了。"
L["Thanks for the {gift}, {name}. I'll earn it before it fades."] = "谢谢你的{gift}，{name}。它消失前我会对得起它。"
L["For {gift} I'd hand you both moons, {name}. This'll have to do."] = "为{gift}，两个月亮都摘给你，{name}。先拿这个吧。"
L["You brought {gift}, I brought {buff}. Now it's a party."] = "你带{gift}，我带{buff}。派对开始。"
L["{gift} means 'good luck'. {buff} means 'you too'."] = "{gift}是说“祝好运”，{buff}是说“你也是”。"
L["Your {gift} came first; my {buff} tries twice as hard."] = "你的{gift}先到，我的{buff}加倍卖力。"
L["If anyone asks, {buff} came before {gift}. Deal?"] = "有人问起，就说{buff}在{gift}之前。成交？"
L["{gift} made my day; {buff} should make your hour."] = "{gift}让我乐了一整天，{buff}够你乐一个钟头。"
L["Saved my {buff} for someone special. Then came {gift}."] = "{buff}本想留给特别的人。然后{gift}就来了。"
L["Your {gift} went to my head; my {buff} goes to yours."] = "你的{gift}让我上头，我的{buff}换你上头。"
L["{gift} on me, {buff} on you. We wear each other's work."] = "我身披{gift}，你身披{buff}，互为裁缝。"
L["{gift} and {buff} fade. Kindness lasts. Well, longer."] = "{gift}和{buff}会消失，情谊长存。好吧，存得久一点。"
L["You shared {gift}; I share {buff}. Next, snacks."] = "你分我{gift}，我分你{buff}。下次分零食。"
L["{gift} caught me empty-handed. Not any more: {buff}."] = "{gift}来时我两手空空。现在不了：{buff}。"
L["{gift}, best thing all day. {buff}, my bid for second."] = "{gift}，今天最棒的事。{buff}，争个第二。"
L["{gift} deserves a statue. I'm no sculptor, so: {buff}."] = "{gift}值得立座雕像。我不会雕，就回{buff}吧。"
L["{gift} for {buff}? Keep this up and we'll draw a queue."] = "{gift}换{buff}？再这样下去要排起长队了。"
L["{gift} was kind. {buff} is kind back, and competitive."] = "{gift}是好意，{buff}是回礼——还带点较劲。"
L["{gift} came like good news. {buff}, by return post."] = "{gift}如喜报传来，{buff}火速回信。"
L["{gift}, meet {buff}. Do get along, you two."] = "{gift}，这位是{buff}。你俩好好相处。"
L["Trade you {buff} for {gift}? Ah, you've already paid."] = "拿{buff}换你的{gift}？啊，你已经付过了。"
L["{gift} and {buff}. The inn will say we rehearsed."] = "{gift}配{buff}。旅店的人会说我们彩排过。"
L["{gift}! I just had three clever thoughts, {name}. This was one."] = "{gift}！我刚冒出三个好点子，{name}。这是其一。"
L["With {gift}, {name}, I finally understand my own notes. Thanks."] = "有了{gift}，{name}，我终于看懂自己笔记了。谢谢。"
L["Cleverer already, {name}. Clever enough to know I owe you one. Here."] = "已经变聪明了，{name}。聪明到知道欠你一个人情。给。"
L["Your {gift} found me the word for this, {name}: 'thanks'."] = "你的{gift}帮我找到了那个词，{name}：“谢谢”。"
L["{gift}! I understood a goblin contract, {name}. I'm appalled."] = "{gift}！我居然看懂了地精的合同，{name}。吓坏我了。"
L["{gift}! I finally get last week's mage joke, {name}. Thanks."] = "{gift}！上周那个法师笑话我终于懂了，{name}。谢谢。"
L["I'll use your {gift} for more than arguing, {name}. Probably."] = "你的{gift}我不光拿来吵架，{name}。大概吧。"
L["Thank you, {name}. My next spell gets three extra syllables, just to show off."] = "谢谢你，{name}。下个法术我多念三个字，就为显摆。"
L["{gift}, {name}? I'll stand at the front for once. Briefly."] = "{gift}，{name}？那我就站前排一回。一小会儿。"
L["Knees, elbows and pride, {name}: all fortified. Thank you."] = "膝盖、肘子和自尊，{name}：全加固了。谢谢。"
L["Hit me now, {name}. Actually, don't. But thank you; I'd survive it."] = "来打我吧，{name}。算了，别打。但谢谢你，我扛得住。"
L["Nigh unbreakable now, {name}. Let's never test the 'nigh'. Thank you."] = "现在几乎打不坏了，{name}。“几乎”二字咱就别验证了。谢谢。"
L["{gift}! My healer owes you a letter, {name}. I owe you this."] = "{gift}！我的治疗欠你一封感谢信，{name}。我欠你这个。"
L["Every bruise I don't get today, {name}, I owe to your {gift}."] = "今天每块没挨上的淤青，{name}，都得归功于你的{gift}。"
L["I could lose an argument with an ogre now and live, {name}. Thank you."] = "现在跟食人魔吵输了我都能活，{name}。谢谢你。"
L["Thank you, {name}. I feel like a castle wall. A grateful one."] = "谢谢你，{name}。我感觉自己像堵城墙。一堵知恩的城墙。"
L["Thank you, {name}. The next boar to charge me is in for a long afternoon."] = "谢谢你，{name}。下一头冲我来的野猪，有个漫长的下午要熬了。"
L["{gift}! My spirits are lifted, {name}. Literally, it seems."] = "{gift}！精神振作了，{name}。字面意义上的。"
L["I feel twice as calm and half as grumpy, {name}. Thank you."] = "我平静了一倍，暴躁少了一半，{name}。谢谢你。"
L["Your {gift} nearly made me sing, {name}. Take this. It's kinder."] = "你的{gift}差点让我唱起来，{name}。收下这个吧，比我唱歌仁慈。"
L["{gift}, {name}? I've forgiven three people already. Thank you."] = "{gift}，{name}？我已经原谅三个人了。谢谢你。"
L["I was on fumes, {name}. Your {gift} was a hot meal and a hearth."] = "我本来快油尽灯枯了，{name}。你的{gift}就是热饭加炉火。"
L["I've stopped counting mana between fights, {name}. Thank you."] = "打完架不用再数法力值了，{name}。谢谢你。"
L["My spirit's topped up, {name}, and the rest of me is grateful too."] = "我的精神加满了，{name}，其余部分也很感激。"
L["Shadow-proof, thanks to you, {name}. The whispers are furious."] = "多亏你，我能防暗影了，{name}。那些低语气坏了。"
L["Nothing dark gets in now, {name}. Here's something bright going the other way."] = "黑暗进不来了，{name}。回你一点亮的。"
L["{gift}! Shadowfang Keep can keep its shadows, {name}. Thank you."] = "{gift}！影牙城堡的影子，让它自己留着吧，{name}。谢谢。"
L["The next shadow bolt's in for a letdown, {name}. Thank you."] = "下一发暗影箭要大失所望了，{name}。谢谢你。"
L["On your {gift} I'll brave Duskwood tonight, {name}. Or tomorrow."] = "有你的{gift}，我今晚就闯暮色森林，{name}。要不明天。"
L["{gift}! A squirrel just nodded at me, {name}. Here's yours."] = "{gift}！松鼠刚冲我点头，{name}。这是你的。"
L["Tougher hide, sharper senses, {name}. I may have to fight the urge to forage."] = "皮更厚，感官更灵，{name}。我得忍住别去刨食了。"
L["I feel all wild and leafy, {name}. Thank you. Sorry if I shed bark."] = "枝繁叶茂，野性十足，{name}。谢谢，掉了树皮莫怪。"
L["Thicker skin from your {gift}, {name}. Arrows and insults both."] = "有了你的{gift}，我皮厚了，{name}。箭和挖苦都扎不进。"
L["{gift}! A bird tried to nest on me, {name}. Thanks, I think."] = "{gift}！有只鸟想在我身上筑巢，{name}。谢谢……吧。"
L["Half a tree now, {name}, the better half. Thanks for the {gift}."] = "我现在半个是树了，{name}，是好的那半。谢谢你的{gift}。"
L["Thank you, {name}. I've an urge to stand in the rain and grow. I'll resist."] = "谢谢你，{name}。我好想站在雨里长个儿。忍住了。"
L["Every bramble in the Barrens will think twice now, {name}. Thank you."] = "贫瘠之地的荆棘现在都得掂量掂量了，{name}。谢谢你。"
L["Thank you, {name}. Even my boots feel like they've put down roots."] = "谢谢你，{name}。连我的靴子都像扎了根。"
L["{gift}, {name}! Nobody's hugging me today. Have this instead."] = "{gift}，{name}！今天没人抱我了，送你这个吧。"
L["Prickly now, thanks to you, {name}. More than usual, I mean."] = "多亏你，我浑身是刺了，{name}。比平时还扎人。"
L["Your {gift}, {name}! Let the next kobold try for my candle."] = "你的{gift}，{name}！下个狗头人敢碰我的蜡烛试试。"
L["{gift}! I'm a thicket with opinions now, {name}. Thank you."] = "{gift}！我现在是一丛有主见的灌木了，{name}。谢谢。"
L["Thank you, {name}. The next thing that bites me will need a moment to reflect."] = "谢谢你，{name}。下个咬我的，得边挨反伤边反省。"
L["{gift} from you, {name}? I'll try not to found a dynasty."] = "你给的{gift}，{name}？我尽量不开创个王朝。"
L["A little better at everything, {name}. Is this how kings feel? No wonder."] = "样样都强了一点，{name}。当国王就是这感觉？难怪。"
L["Your {gift}! My first decree, {name}: thank you."] = "你的{gift}！朕的第一道圣旨，{name}：谢谢你。"
L["{gift} on a commoner, {name}? I'll try to look regal."] = "{gift}给我这平头百姓，{name}？我尽量装得有王者风范。"
L["With your {gift} I could rule a small kingdom, {name}. Westfall."] = "有了你的{gift}，我能统治个小王国了，{name}。西部荒野那种。"
L["Thank you, {name}. I'm a little better at everything now, gratitude included."] = "谢谢你，{name}。我样样都强了一点，包括道谢。"
L["Stronger arms already, {name}. I'll try not to hug anyone. Thank you."] = "胳膊已经有劲了，{name}。我尽量不抱任何人。谢谢你。"
L["With {gift} I could lift a kodo, {name}. I won't, but thank you."] = "有了{gift}能举科多兽，{name}。不举，但谢谢你。"
L["Your {gift} has my arms very confident, {name}. Thank you."] = "你的{gift}让我胳膊自信爆棚，{name}。谢谢。"
L["{gift}! Opened a jar I've fought since Stranglethorn, {name}."] = "{gift}！从荆棘谷拧到现在的罐子，终于开了，{name}。"
L["Thank you, {name}. My next swing is dedicated to you. So is the dent."] = "谢谢你，{name}。下一击献给你。砸出的坑也是。"
L["{gift} from you, {name}, and my first wise act is this."] = "收了{gift}，{name}，头一件明智事就是这个。"
L["Wiser already, {name}. Wise enough to know a kindness when I see one."] = "已经更睿智了，{name}。睿智到一眼认出好意。"
L["My mana thanks you for {gift}, {name}. It's the shy one of us."] = "我的法力值谢谢你的{gift}，{name}。它比较害羞，我代它说。"
L["Your {gift} refills me faster than I spend, {name}. Nearly."] = "你的{gift}回得比我花得还快，{name}。差不多吧。"
L["Your {gift}, {name}: mana back, and an urge to give advice."] = "你的{gift}，{name}：法力回来了，还特想给人出主意。"
L["{gift}! The monsters forgot me at once, {name}. I won't."] = "{gift}！怪物全忘了我，{name}。我忘不了你。"
L["Nothing wants to fight me now, {name}. It's lovely. Thank you."] = "现在谁都不想跟我打了，{name}。真美好。谢谢你。"
L["{gift}! Nothing's glared at me in minutes, {name}. Thank you."] = "{gift}！好几分钟没被东西瞪了，{name}。谢谢。"
L["{gift}! A mouse at a dragon's feast, {name}: unseen, well fed."] = "{gift}！龙宴上的老鼠，{name}：没人看见，吃得饱饱。"
L["Thanks to {gift} I'm just a rumour in a fight, {name}."] = "多亏{gift}，战场上只剩我的传说，{name}。"
L["The Light finds me easier now, {name}. It says thank you, and so do I."] = "圣光更容易找到我了，{name}。它说谢谢，我也是。"
L["Easier to heal now, thanks to you, {name}. My healer thanks you too."] = "多亏你，我更好治了，{name}。我的治疗也谢谢你。"
L["With your {gift}, {name}, every heal feels like a homecoming."] = "有了你的{gift}，{name}，每次治疗都像回家。"
L["{gift}! The Light and I are on first-name terms now, {name}."] = "{gift}！我跟圣光现在称兄道弟了，{name}。"
L["With {gift} the Light hears me first, {name}. No need to shout."] = "有了{gift}，圣光先听见我，{name}。不用喊了。"
L["Blows land softer on me now, {name}. My bruises thank you, and so do I."] = "现在挨揍都轻了，{name}。我的淤青谢谢你，我也谢谢你。"
L["Every hit gentler, thanks to you, {name}. I'll make sure they notice."] = "多亏你，每一击都温柔了，{name}。我会让它们知道的。"
L["Your {gift} softens every blow, {name}. I'm upholstered."] = "你的{gift}让每一击都软了，{name}。我都包上软垫了。"
L["{gift}! Now the Light takes every hit personally, {name}."] = "{gift}！现在我挨的每一下，圣光都记仇，{name}。"
L["With your {gift} I'm half fortress, half chapel, {name}."] = "有了你的{gift}，我一半是堡垒，一半是礼拜堂，{name}。"
L["You shouted at me, {name}, and I've never felt so encouraged. Here."] = "你冲我吼了，{name}，我从没这么受鼓舞过。给。"
L["My ears are ringing, {name}, and my arms feel twice as strong. Thank you!"] = "我耳朵嗡嗡响，{name}，胳膊力气翻倍。谢谢你！"
L["{gift}, {name}! I felt that in my teeth. In a good way."] = "{gift}，{name}！震得我牙都麻了。好的那种。"
L["I'll answer your {gift} quietly, {name}. Somebody should."] = "我就小声回应你的{gift}吧，{name}。总得有人小声点。"
L["Your {gift} nearly had me charging a wall, {name}. Here, calmly."] = "你的{gift}差点让我冲去撞墙，{name}。给，冷静地回你。"
L["All Azeroth heard your {gift}, {name}. Only I get to thank you."] = "全艾泽拉斯都听见了你的{gift}，{name}。道谢的名额归我。"
L["Your shout's still ringing, {name}, and so is my sword arm. Thank you."] = "你的吼声还在回响，{name}，我的剑臂也还在嗡嗡响。谢谢。"
L["I didn't catch the words, {name}, but my arms did. Thank you!"] = "你吼的啥我没听清，{name}，但胳膊听懂了。谢谢！"
L["Thank you, {name}. I'll hit the next thing twice as hard and blame you."] = "谢谢你，{name}。下个倒霉蛋我加倍使劲揍，然后赖你。"
L["I can breathe underwater, {name}! I may never need to, but thank you."] = "我能在水下呼吸了，{name}！可能永远用不上，但谢谢你。"
L["Lungs like a murloc, thanks to you, {name}. Mrgl. Sorry. Thank you."] = "多亏你，肺活量堪比鱼人，{name}。Mrgl。抱歉，谢谢。"
L["With {gift} I'll raid every sunken wreck, {name}. Half's yours."] = "有了{gift}，每艘沉船我都去搜一遍，{name}。分你一半。"
L["I won't ask where {gift} gets its air, {name}. Just: thanks."] = "{gift}的空气哪来的，我不问，{name}。只说：谢谢。"
L["With {gift} I'll cross Lordamere Lake, {name}. Underneath."] = "有了{gift}，我要横渡洛丹米尔湖，{name}。从湖底。"
L["We have to stop meeting like this, {name}. Actually, no, we don't."] = "我们不能再这样见面了，{name}。其实，也不是不行。"
L["Again, {name}? Splendid. I've been practising since last time."] = "又见面了，{name}？太好了。上次之后我一直在练。"
L["You again, {name}? People will start saying we're friends."] = "又是你，{name}？别人要说我们是朋友了。"
L["Same face, same spell, {name}. I do love a tradition."] = "老面孔，老法术，{name}。我就爱这传统。"
L["Another round, {name}? I'm keeping score, and we're both winning."] = "再来一轮，{name}？我在记分，我们俩都赢着呢。"
L["Ah, {name}! My favourite repeat customer."] = "啊，{name}！我最喜欢的回头客。"
L["Our paths keep crossing, {name}. I think the road is dropping hints."] = "我们总是碰上，{name}。这条路怕是在给咱俩牵线。"
L["Hello again, {name}. Do stop me if you've heard this one."] = "又见面了，{name}。这段听过的话，打断我。"
L["I kept some aside, {name}, in case you came back. Good instinct, mine."] = "我给你留了一份，{name}，就怕你回来。看来我直觉不错。"
L["Back already, {name}? I'm starting to think you like me."] = "又回来啦，{name}？我开始觉得你喜欢我了。"
L["Again, {name}? At this rate I'll have to learn your middle name."] = "又是你，{name}？照这样，我得打听你小名了。"
L["Once is kindness, twice is a habit, {name}. I've never broken a habit yet."] = "一次是好意，两次是习惯，{name}。我还从没改掉过哪个习惯。"
L["Encore, {name}. The crowd demanded it. The crowd is you."] = "安可，{name}！观众强烈要求的。观众就是你。"
L["One more of these, {name}, and we'll have to draw up a guild charter."] = "再来一回，{name}，咱俩就得填公会登记表了。"
L["I'd know your footsteps anywhere now, {name}. Handy; I'm terrible with faces."] = "现在我在哪儿都认得出你的脚步声，{name}。正好，我脸盲。"
L["Us again, {name}. The world must be running out of other people."] = "又是我们俩，{name}。这世界怕是没别人了。"
L["Last time went so well, {name}, I've changed nothing. Not even my expression."] = "上回太顺利了，{name}，我啥都没改。连表情都没改。"
L["I know where you stand now, {name}. Literally; I've aimed at it before."] = "我摸清你的立场了，{name}。字面意义上——我瞄准过那块地。"
L["Oh, it's you, {name}. Good. I hate giving these to strangers."] = "哦，是你啊，{name}。那就好，我最不爱给陌生人这个。"
L["{name}, at this point we should just share a reagent pouch."] = "{name}，到这份上，我们干脆合用一个材料包吧。"
L["Same time tomorrow, {name}? I'll bring {buff}. You bring you."] = "明天老时间，{name}？我带{buff}，你带上你自己。"
L["I've lost count, {name}, and I've decided that's a compliment."] = "我已经数不清了，{name}，我决定把这当成夸奖。"
L["Keep this up, {name}, and the bards will write a very dull song about us."] = "照这样，{name}，吟游诗人会给我们写首很闷的歌。"
L["I could do this one in my sleep by now, {name}. I may have."] = "这活儿我睡着都能干，{name}。可能真干过。"
L["{name}, the usual? Of course the usual. It's always the usual."] = "{name}，老样子？当然是老样子。一直都是老样子。"
L["We ought to have a secret handshake by now, {name}. Next time, perhaps."] = "我们早该有个秘密握手暗号了，{name}。下次吧。"
L["By now, {name}, I think we've built a small economy between us."] = "到现在，{name}，我俩之间都有个小经济体了。"
L["Old friends by now, {name}. Well, old acquaintances with excellent timing."] = "都是老朋友了，{name}。好吧，是时机特别好的老熟人。"
L["Let the record show: {name} and I, undefeated at being prepared."] = "记录在案：{name}和我，论有备无患，从无败绩。"
L["My spellbook opens to your page on its own now, {name}."] = "我的法术书现在自己就翻到你那页了，{name}。"
L["If you stopped turning up, {name}, I'd report you missing to the guards."] = "你要是不来了，{name}，我就去找卫兵报失踪。"
L["So much has passed between us, {name}, I've lost track of whose is whose."] = "我俩之间来来往往太多，{name}，都分不清谁是谁的了。"
L["We're a local landmark now, {name}. Travellers give directions by us."] = "我们都成本地地标了，{name}。路人指路都拿我们当参照。"
L["The innkeepers ask after you now when I come in alone, {name}."] = "现在我一个人进旅店，老板都要问你去哪了，{name}。"
L["The guards wave us both through now, {name}. They assume we're a set."] = "卫兵现在直接放我俩过，{name}。以为我们是套装。"
L["Folk ask which of us taught the other, {name}. I say you, to be polite."] = "有人问我俩谁教的谁，{name}。出于礼貌，我说是你。"
L["I'd miss this if it stopped, {name}. So let's not stop."] = "要是停了我会想念的，{name}。那就别停。"
L["Somewhere a tavern has heard all about us, {name}. Mostly from me."] = "某家酒馆早把我俩的事听了个遍，{name}。多半是我讲的。"
L["I hum a little when I see you coming now, {name}. Nobody else gets the hum."] = "现在看见你来，我会哼两句，{name}。别人可没这待遇。"
L["Safe walls, warm beds, and now {buff}. You're spoiled, {name}."] = "墙高床暖，还有{buff}。你被宠坏了，{name}。"
L["The guards have it covered, {name}, but I like to be thorough."] = "卫兵们都守着呢，{name}，但我喜欢做全套。"
L["Careful, {name}. Look this capable in town and folk will ask you favours."] = "当心，{name}。在城里看着这么能干，会有人找你帮忙的。"
L["Not a monster for miles, {name}. Still, one never knows about the cooking."] = "方圆几里一个怪物都没有，{name}。不过，饭菜就难说了。"
L["For the crowds, {name}. In town, they're the real danger."] = "防人群的，{name}。城里最危险的就是人群。"
L["Rest easy, {name}. I'll count that my good deed and go find a pint."] = "安心休息吧，{name}。今天的好事做完了，我找酒喝去。"
L["Even in town, {name}, a dragon has been known to drop in. Better safe."] = "就算在城里，{name}，也有龙突然造访过。小心为上。"
L["Best do it in here, {name}. Out there, nobody stands still long enough."] = "最好在这儿弄，{name}。出了城，谁都不肯站着别动。"
L["Mind the pickpockets, {name}. This is the one thing on you they can't lift."] = "小心扒手，{name}。你身上就这个他们偷不走。"
L["City rules, {name}: no blades drawn, no spells thrown. This one's allowed."] = "城里规矩，{name}：不许拔刀，不许施法。这个例外。"
L["Nothing to fight here but the queue at the mailbox, {name}. Take this anyway."] = "这儿唯一要打的仗是邮箱前排队，{name}。还是拿着吧。"
L["For the walk to the bank, {name}. It's always further than it looks."] = "去银行的路上用，{name}。那段路总比看着远。"
L["Put that on before the banker sees, {name}. They'll want to charge interest."] = "趁银行职员没看见赶紧用上，{name}。不然要收利息。"
L["The watch keeps the peace, {name}. I just keep you in one piece."] = "卫兵负责治安，{name}。我负责你的平安。"
L["For the stairs, {name}. Whoever built this place never met a short way up."] = "爬楼梯用的，{name}。修这地方的人压根不知道啥叫近路。"
L["Everything else in town has a price, {name}. This slipped past the merchants."] = "城里啥都要钱，{name}。就这个，商人漏掉了。"
L["Buy nothing from anyone who calls you 'friend', {name}. Except me."] = "叫你“朋友”的人，东西一律别买，{name}。我除外。"
L["Out here everything wants to eat you, {name}. Now it'll need a bigger fork."] = "野外什么都想吃你，{name}。现在它们得换把更大的叉子了。"
L["No guards for miles, {name}, and the boars know it. Take this."] = "几里内没卫兵，{name}，野猪心里有数。拿着。"
L["Nobody out here but us and the wildlife, {name}. Let's be the tougher half."] = "这儿只有我们和野兽，{name}。咱们得当更狠的那一半。"
L["If a bear asks, {name}, you were like this when I found you."] = "熊要是问起，{name}，就说我发现你时你就这样。"
L["The wolves have been eyeing you, {name}. This should give them pause."] = "狼一直在盯着你，{name}。这下它们该掂量掂量了。"
L["Wild country, {name}. Best not to meet it armed with good intentions alone."] = "荒郊野外，{name}。光靠一片好心可不够。"
L["Map, canteen, {buff}. Now you can get lost properly, {name}."] = "地图、水壶、{buff}。这下能好好迷路了，{name}。"
L["Camp's a long way off, {name}. Consider this a roof you can carry."] = "营地还远着呢，{name}。就当这是个随身带的屋顶。"
L["Murlocs, raptors, bandits, rain, {name}. This handles one of those. You pick."] = "鱼人、迅猛龙、强盗、下雨，{name}。这个能对付其中一样。你挑。"
L["Nearest inn's a day's walk, {name}. The nearest thing with teeth is closer."] = "最近的旅店要走一天，{name}。最近的尖牙利齿可近多了。"
L["Two hills and a swamp to the next town, {name}. The swamp has opinions."] = "离下个镇子还隔着两座山、一片沼泽，{name}。沼泽很有意见。"
L["Camp carefully, {name}. Every nice clearing has an owner, and it has claws."] = "扎营当心，{name}。每块好空地都有主，主人还长爪子。"
L["Out here the only law is the food chain, {name}. You've just moved up a rung."] = "野外只认食物链，{name}。你刚往上爬了一格。"
L["Something's following you, {name}. Probably a boar. This is in case it isn't."] = "有东西在跟着你，{name}。多半是野猪。这个防万一不是。"
L["Stay on the road, {name}. The road has guards. Some of the time."] = "走大路，{name}。大路上有卫兵。有时候有。"
L["Rain's coming, {name}, and so are the wolves. One of those I can help with."] = "要下雨了，狼也要来了，{name}。雨我可管不了。"
L["Somewhere in here a villain is rehearsing a speech, {name}. Let's interrupt."] = "这里面有个反派正在排练台词，{name}。咱们去打断他。"
L["Whatever waits at the end of this place, {name}, let's make it regret it."] = "不管尽头等着什么，{name}，都让它后悔。"
L["They say nobody leaves here alive, {name}. Let's be rude and prove them wrong."] = "听说没人能活着出去，{name}。咱们就不给面子，活着出去。"
L["Our host had years to prepare, {name}. We have {buff}."] = "东道主备战多年，{name}。我们有{buff}。"
L["Nobody builds a dungeon with a back door, {name}. Take this instead."] = "没人给地下城修后门，{name}。拿这个将就吧。"
L["Dark halls, old traps, worse tempers. At least you're ready, {name}."] = "暗厅、老陷阱、更坏的脾气。好在你有准备，{name}。"
L["Better I hand you this now, {name}, than a eulogy later."] = "现在给你这个，{name}，总比以后念悼词强。"
L["There's treasure in here, {name}, and something very large sat on it."] = "这里有宝藏，{name}，上面还坐着个大家伙。"
L["If a door slams shut behind us, {name}, that's tradition. Take this first."] = "身后的门要是砰地关上，{name}，那是老传统。先拿着这个。"
L["Mind the patrols, {name}. They walk the same loop forever and resent it."] = "小心巡逻怪，{name}。天天绕同一个圈，怨气大着呢。"
L["Whoever built this place, {name}, spent it all on skulls and nothing on lamps."] = "修这地方的人，{name}，钱全花在骷髅上，灯一盏没买。"
L["The last lot through here were never seen again, {name}. They lacked this."] = "上一队进来的再也没出去，{name}。他们就缺这个。"
L["Check the ceiling, {name}. In places like this, something always drops in."] = "抬头看看，{name}。这种地方，总有不速之客从天而降。"
L["If we meet a talking skull, {name}, let me do the talking."] = "要是碰上会说话的骷髅，{name}，耍嘴皮子交给我。"
L["If the walls start whispering, {name}, don't answer. It only encourages them."] = "墙要是开始低语，{name}，别搭理。越理它越来劲。"
L["Touch nothing that glows, pull nothing that clicks, {name}. Wear this."] = "发光的别碰，咔哒响的别拉，{name}。把这个穿上。"
L["Stick together in here, {name}. Echoes carry, and so do grudges."] = "在这里面别走散，{name}。回声传得远，仇也记得久。"
L["Flags, towers, graveyards, {name}. Whatever we're fighting over, take this."] = "旗子、塔楼、墓地，{name}。不管这次抢的是什么，拿着这个。"
L["Win or lose, {name}, nobody will say you went in unprepared."] = "输赢不论，{name}，没人能说你毫无准备。"
L["The graveyard's just over there, {name}. Let's both not visit it."] = "墓地就在那边，{name}。咱俩都别去串门。"
L["Honour's on the line, {name}. So is the flag. Mostly the flag."] = "荣誉悬于一线，{name}。旗子也是。主要是旗子。"
L["Stay with the group, {name}. Lone heroes end up in the other side's songs."] = "跟紧大部队，{name}。独行的英雄最后都进了对面的歌里。"
L["Our banner looks better with you under it, {name}. Stand tall."] = "咱们的旗下有你才好看，{name}。站直了。"
L["Keep your head down and your colours up, {name}."] = "头要低，旗要高，{name}。"
L["Hold the line, {name}. The songs are always about the ones who stood."] = "守住阵线，{name}。歌里唱的，都是站着没倒的人。"
L["The spirit healer knows my face by now, {name}. Let's keep yours a stranger."] = "灵魂医者早认得我这张脸了，{name}。你可别跟它混熟。"
L["Drums are for courage, {name}. This is for everything else."] = "战鼓管勇气，{name}。其余的归这个管。"
L["The quartermaster counts marks, {name}. I count friends. You're on my list."] = "军需官数奖章，{name}，我数朋友。你在我名单上。"
L["Fight for the banner, {name}, but come back for the singing. Mine's dreadful."] = "为旗帜而战，{name}，但记得回来听歌。我唱得可难听了。"
L["Early bird, {name}? Here's something better than a worm."] = "早起的鸟儿有虫吃，{name}。给你个比虫强的。"
L["Good morning, {name}. Consider this your first cup of something strong."] = "早上好，{name}。就当这是你今天的第一杯浓茶。"
L["Early start, {name}. The day hasn't had a chance to go wrong yet."] = "起得真早，{name}。今天还没来得及出岔子。"
L["Not even lunch yet, {name}, and you're already better prepared than I am."] = "还没到午饭时间，{name}，你就比我准备得更充分了。"
L["Morning, {name}. Somewhere, the monsters are still yawning."] = "早，{name}。怪物们这会儿还在打哈欠呢。"
L["A fresh day and a fresh {buff}, {name}. Let's not waste either."] = "崭新的一天，崭新的{buff}，{name}。哪个都别浪费。"
L["Up with the sun, {name}? Show-off. Here; the sun doesn't get one."] = "跟太阳一起起床，{name}？显摆。给，太阳可没这个。"
L["Rise and shine, {name}. Well, rise. The shining can wait till after breakfast."] = "起床，精神点，{name}！呃，先起床，精神等早饭后再说。"
L["Dawn, {name}. Everything's golden and nobody's shouted yet. Let's enjoy it."] = "天亮了，{name}。遍地金光，还没人嚷嚷。享受一下吧。"
L["Too early for heroics, {name}? Nonsense. Heroics go best before lunch."] = "嫌太早当不了英雄，{name}？胡说，英雄就该趁午饭前当。"
L["The birds are singing, {name}. They haven't seen what's out there yet."] = "鸟儿在唱歌，{name}。它们还没见识过外面有什么。"
L["Morning, {name}. Here's the first good deed of the day. It's all downhill now."] = "早，{name}。今天第一件好事送上。接下来只会走下坡路了。"
L["Still yawning, {name}? This works faster than tea."] = "还在打哈欠，{name}？这个比茶提神还快。"
L["Early, {name}. The dawn patrol looks at us like we've lost our minds."] = "真早啊，{name}。晨间巡逻的卫兵看咱们像看疯子。"
L["Out this late, {name}? The night is hungrier than the day. Take this."] = "这么晚还在外面，{name}？黑夜比白天更饿。拿着。"
L["Past bedtime, {name}. The sensible folk are asleep, which leaves us."] = "该睡觉了，{name}。明白人都睡了，就剩咱们。"
L["Can't sleep either, {name}? Then let's be well-protected insomniacs."] = "你也睡不着，{name}？那就当一对全副武装的失眠者吧。"
L["Mind the dark, {name}. Not everything out there is as friendly as I am."] = "小心黑暗，{name}。外面的东西可不都像我这么友善。"
L["It's late, {name}. This should keep you going till the sun remembers us."] = "夜深了，{name}。这个够你撑到太阳想起我们。"
L["Only the owls and us awake, {name}, and the owls get no {buff}."] = "夜猫子只剩咱们和猫头鹰，{name}。猫头鹰没{buff}。"
L["The inns have locked up, {name}. This is the only thing still being served."] = "旅店都打烊了，{name}。就我这儿还营业。"
L["It's the hour for ghost stories, {name}. Take this, in case one is true."] = "正是讲鬼故事的时辰，{name}。拿着，万一哪个是真的呢。"
L["Candles low, stars high, {name}. A good hour for small kindnesses."] = "烛光低，星光高，{name}。正适合做点小小的好事。"
L["Quiet hour, {name}. Every creak sounds like an ambush. Most of them aren't."] = "夜深人静，{name}。每声吱呀都像埋伏。多半不是。"
L["This late, {name}, even the guards are talking to themselves."] = "这么晚了，{name}，连卫兵都在自言自语。"
L["This is the hour things climb out of graves, {name}. Take this; walk briskly."] = "这个时辰，坟里会爬出东西来，{name}。拿着，走快点。"
L["Tomorrow you'll wonder why you stayed up, {name}. This is one good reason."] = "明天你会纳闷自己为啥熬夜，{name}。这就是个好理由。"
L["Takes one to know one, {name}. Takes one to do it properly, too."] = "同行最懂同行，{name}。同行做得也最地道。"
L["From one of our trade to another, {name}. No need to check my work."] = "同行送同行，{name}。不用检查我的活儿。"
L["Professional courtesy, {name}. We don't charge each other."] = "行规，{name}：同行不收钱。"
L["Two of a kind, {name}. Between us we could write the manual."] = "一路人，{name}。咱俩合起来能写本教材。"
L["Don't look so surprised, {name}. Same trainer, I expect."] = "别惊讶，{name}。估计是同一个训练师。"
L["I'd critique your technique, {name}, but mine looks exactly the same."] = "本想点评你的手法，{name}，可我的跟你一模一样。"
L["Don't tell the others, {name}, but ours really is the finest calling."] = "别告诉别人，{name}，咱们这行确实是最好的。"
L["Look at us, {name}. Two experts, making it look easy. It isn't, is it?"] = "瞧咱俩，{name}，举重若轻。其实挺重的吧？"
L["Between colleagues, {name}: I also have no idea how half of it works."] = "同行之间说句实话，{name}：一半原理我也不懂。"
L["Same trade, {name}, so you know exactly how hard that was. Let's say very."] = "都是同行，{name}，你懂这有多难。就说非常难吧。"
L["If anyone asks, {name}, we trained each other."] = "有人问起，{name}，就说咱俩互为师徒。"
L["Calling to calling, {name}. We should compare notes. Mine are mostly doodles."] = "同道中人，{name}，该对对笔记。我的大多是涂鸦。"
L["Colleague, {name}. We should found a society. Dues, minutes, a very small hat."] = "同行，{name}，办个协会吧：会费、纪要，外加一顶小帽子。"
L["We'd be twins, {name}, if I were a touch better-looking."] = "要是我再好看一点点，{name}，咱俩就像双胞胎了。"
L["I'd shout some encouragement, {name}, but you do that far better."] = "本想吼两声给你鼓劲，{name}，可你吼得比我好多了。"
L["Charge in as usual, {name}. I'll simply feel better about it now."] = "照常冲锋吧，{name}。现在我心里踏实点了。"
L["For the one who goes in first, {name}. Somebody has to, and it's never me."] = "给第一个冲进去的人，{name}。总得有人冲，反正不会是我。"
L["You take the hits so the rest of us don't, {name}. It's the least I can do."] = "你替我们挨打，{name}。这是我起码能做的。"
L["Go on, {name}, charge. I'll be right behind you. Quite a long way behind."] = "去吧，{name}，冲！我就在你身后。很远的身后。"
L["For the one who fixes every problem by hitting it, {name}. It usually works."] = "给什么问题都靠一顿揍解决的人，{name}。通常还真灵。"
L["I'd shake your hand, {name}, but both of yours are holding something sharp."] = "本想跟你握个手，{name}，可你两只手都拿着利器。"
L["A little help for a lot of armour, {name}. I hope it fits under there."] = "一身重甲，一点心意，{name}。希望塞得进盔甲里。"
L["You'll charge something enormous soon, {name}. I'm just helping it lose."] = "你马上又要冲锋个大家伙，{name}。我只是帮它输得快点。"
L["Save the bubble for later, {name}. This one's from me."] = "无敌先留着，{name}。这层是我给的。"
L["You bless everyone else all day, {name}. Here's one going the other way."] = "你整天给别人祝福，{name}。这次反过来。"
L["The Light already likes you, {name}. Consider this a second opinion."] = "圣光本来就喜欢你，{name}。就当这是第二诊疗意见吧。"
L["Even the Light's own champion needs a hand now and then, {name}."] = "就算是圣光的勇士，{name}，偶尔也需要搭把手。"
L["I'd ask for a blessing back, {name}, but then we'd be here all day."] = "想让你回个祝福，{name}，可那样就得耗一整天了。"
L["For the one who carries a hammer and a conscience, {name}. Heavy load."] = "给扛着锤子又背着良心的人，{name}。担子不轻啊。"
L["Don't thank the Light for this one, {name}. It had the day off. This was me."] = "这次别谢圣光，{name}。它今天休息，是我干的。"
L["No need to kneel, {name}. I know it's a habit."] = "不用跪，{name}。我知道你习惯了。"
L["One for you, {name}, and a pat on the head for your companion."] = "这个给你，{name}，再摸摸你伙伴的头。"
L["You watch everyone's back from range, {name}. I've got yours."] = "你在远处照看大家，{name}。你的后背归我。"
L["Hunter's Mark for them, {buff} for you, {name}. Much nicer."] = "猎人印记归它们，{buff}归你，{name}。好多了。"
L["Aim true, {name}. And if it charges you anyway, run towards the rest of us."] = "瞄准点，{name}。要是它还是冲你来了，就往我们这边跑。"
L["Your pet was looking at me hopefully, {name}. This is for you; tell it sorry."] = "你的宠物眼巴巴看着我，{name}。这是你的，替我跟它道歉。"
L["Nothing for the pet this time, {name}. It's already had three of my sandwiches."] = "这次宠物没份，{name}。它已经吃了我三个三明治。"
L["I'd have brought arrows, {name}, but I never know which kind you like."] = "本想给你带箭，{name}，可我总搞不清你爱用哪种。"
L["You can track anything, {name}, but you never saw this one coming."] = "你什么都追踪得到，{name}，这个却没料到吧。"
L["For the one I never see coming, {name}. Meant as the highest praise."] = "给神出鬼没的你，{name}。这是最高赞誉。"
L["Quick, {name}, before you vanish again."] = "快，{name}，趁你还没再次消失。"
L["Poison on the blades, {buff} on you. Very thorough, {name}."] = "刀上抹毒，身上有{buff}。真周全，{name}。"
L["I'd slip it in your pocket, {name}, but you'd notice. You always notice."] = "本想偷偷塞你口袋里，{name}，可你会发现的。你总能发现。"
L["For the one who opens every locked box, {name}. This one comes unlocked."] = "给能撬开所有锁箱的人，{name}。这份不上锁。"
L["Nobody sees you coming, {name}. Now it's even worse news when they do."] = "没人看得见你来，{name}。现在等他们看见，就更惨了。"
L["Take this, {name}. Very discreet. It even walks quietly."] = "拿着，{name}。很低调，走路都没声儿。"
L["I'd have wrapped it, {name}, but you'd only pick the knot."] = "本想给你包起来，{name}，反正你也会把结撬开。"
L["Keep this one, {name}. You don't even have to steal it."] = "这个收下，{name}。连偷都不用偷。"
L["For once, {name}, somebody's looking after the priest."] = "难得一回，{name}，有人照顾牧师了。"
L["Save your prayers for the rest of us, {name}. This one's already answered."] = "祷告留给别人吧，{name}。这次的已经应验了。"
L["Light or Shadow, {name}, I don't ask which. This suits both."] = "圣光还是暗影，{name}，我不问。两边都合适。"
L["Sit down after this fight, {name}. That's an order, from a grateful patient."] = "打完这场坐下歇歇，{name}。这是命令，来自感激的病人。"
L["You keep us all standing, {name}. Here's a little of it coming back."] = "你让我们都站得住，{name}。这里还你一点。"
L["You've knelt beside all of us, {name}. Stand tall a minute."] = "你在我们每个人身边跪过，{name}。站直一会儿吧。"
L["Something that needed no prayer, {name}. You've said plenty of those today."] = "这个不用祷告，{name}。你今天祷告得够多了。"
L["No voice in your head comes with this one, {name}. Refreshing, isn't it?"] = "这个不附带脑内声音，{name}。挺清爽的，对吧？"
L["The Ebon Blade asks no favours, {name}. I'm giving one anyway."] = "黑锋骑士团不求人情，{name}。我偏要送一个。"
L["A little warmth, {name}. I know you don't feel the cold. It's the thought."] = "一点温暖，{name}。我知道你不怕冷，心意到了就好。"
L["You came back from the dead, {name}. The least I can do is help you stay back."] = "你从死亡中归来，{name}。我起码能帮你别再回去。"
L["Runes, plague and frost, {name}. Take this too; it completes the set."] = "符文、瘟疫和冰霜，{name}。再加上这个，凑齐一套。"
L["A skeletal horse and a sword that talks back, {name}. Here's something normal."] = "骷髅马，还有会顶嘴的剑，{name}。给你点正常的东西。"
L["No need to drag me over on a chain, {name}. I was coming anyway."] = "不用死亡之握拽我，{name}，我本来就要过来。"
L["Welcome back to the land of the living, {name}. Well, its general direction."] = "欢迎回到活人的世界，{name}。呃，大致方向吧。"
L["The elements look after you, {name}, but they don't make house calls."] = "元素们照看着你，{name}，但它们不上门服务。"
L["Tell the spirits I said hello, {name}. They never write back."] = "替我向众灵问好，{name}。它们从不回信。"
L["Plant a totem in my honour, {name}. A small one. I'm modest."] = "为我插根图腾吧，{name}。小的就行，我很谦虚。"
L["Earth, fire, water, air and me, {name}. Admittedly the least of the five."] = "土、火、水、风，加上我，{name}。我承认是五个里最弱的。"
L["Totems up already, {name}? Then this goes next to them. Don't plant it."] = "图腾插好了，{name}？这个放旁边就行，别插地上。"
L["The wind would have brought you this, {name}, but it's flighty. I'm reliable."] = "风本可以给你捎来，{name}，可它说变就变。我不会。"
L["Tell the earth I said thanks, {name}. It's done so much for my feet."] = "替我谢谢大地，{name}。它一直在我脚下默默支持我。"
L["The spirits said you'd earned this, {name}. I didn't ask; they volunteered."] = "众灵说这是你应得的，{name}。我没问，它们自己说的。"
L["A gift for a mage, {name}? Like bringing water to... well, you."] = "给法师送礼，{name}？好比给……算了，给你送水。"
L["You solve most problems with sheep, {name}. This covers the rest."] = "大多数问题你用变羊解决，{name}。剩下的交给这个。"
L["You could teleport out of any trouble, {name}. This is for the trouble first."] = "什么麻烦你都能传送走，{name}。这个管传送之前的那段。"
L["For the clever one, {name}. Please don't thank me by making me a sheep."] = "送给聪明人，{name}。拜托别把我变成羊来道谢。"
L["Blink wherever you like, {name}. This comes too."] = "想闪到哪儿都行，{name}。这个跟着你。"
L["Stand a little back from the fire you're about to start, {name}. Here."] = "待会儿放火时站远点，{name}。给你这个。"
L["You keep us all fed and watered, {name}. Your turn to be looked after."] = "你管大家吃喝，{name}。这回轮到你被照顾了。"
L["Portal fees are steep, {name}. Call this a down payment on my next one."] = "传送门可不便宜，{name}。这个就当下一次的定金。"
L["Entirely demon-free, {name}. I checked."] = "不含恶魔，{name}。查过了。"
L["Your imp may be jealous, {name}. Tell it there's plenty to go round."] = "你的小鬼可能会吃醋，{name}。告诉它人人有份。"
L["No contract, no fine print, {name}. Just a gift."] = "无契约，无条款，{name}。就是份礼物。"
L["For the one who hands out healthstones, {name}. Nobody ever thanks you."] = "给那个发治疗石的人，{name}。从来没人谢过你。"
L["Here, {name}. Summon the rest of us later and we'll call it even."] = "给，{name}。待会儿把我们都拉过来，就算扯平。"
L["Your voidwalker can stop hovering, {name}. I mean well."] = "让你的虚空行者别在旁边飘了，{name}。我是好意。"
L["Your felhunter eats magic, {name}. Keep it off this one; it's for you."] = "你的地狱猎犬吃魔法，{name}。别让它碰这个，这是给你的。"
L["Keep your imp downwind, {name}, and we'll call it even."] = "让你的小鬼待在下风处，{name}，咱们就扯平了。"
L["Carrying a bag of souls all day, {name}? Your shoulders must need this."] = "整天背着一袋灵魂，{name}？你的肩膀肯定需要这个。"
L["Roll wherever you like, {name}. This rolls with you."] = "想滚到哪儿都行，{name}。这个跟着你滚。"
L["Brew first or fight first, {name}? Either way, take this."] = "先喝酒还是先打架，{name}？总之拿着。"
L["Inner peace for you, {name}, and outer peace too, as long as this lasts."] = "给你内心的平静，{name}，只要它还在，外面也平静。"
L["Chi flows better with a little help, {name}. Or so a monk once told me."] = "真气有人帮一把，流得更顺，{name}。某位武僧说的。"
L["Kick, flip, roll, {name}. I'll just stand here and do this bit."] = "踢、翻、滚，{name}。我就站这儿负责这一小部分。"
L["Teach me to flip without spilling my drink, {name}, and we're even."] = "教我翻跟头还不洒酒，{name}，咱们就扯平。"
L["Tea, meditation and this, {name}. The three pillars of a good day."] = "喝茶、冥想，再加这个，{name}。美好一天的三大支柱。"
L["Tell the bear this is for them too, {name}."] = "告诉熊，这个也是给它的，{name}。"
L["Hold still, {name}. I've never once managed to catch you as a cheetah."] = "别动，{name}。你变成猎豹时我一次都没追上过。"
L["Nature looks after you already, {name}. Today she sent me to help."] = "大自然已经在照顾你了，{name}。今天她派我来帮忙。"
L["Whatever shape you're in next, {name}, this goes with you."] = "不管下个形态是什么，{name}，它都跟着你。"
L["For the forest's friend, {name}. Give my regards to the trees."] = "给森林之友，{name}。替我向树木问好。"
L["It's the least we can do for somebody who is also a bear, {name}."] = "对一位兼职当熊的人，{name}，这是起码的心意。"
L["I'd hand it to the cat, {name}, but it would only knock it off the table."] = "本想交给猫，{name}，可猫只会把它从桌上拍下去。"
L["Say hello to your moonkin form for me, {name}. It always looks so startled."] = "替我向你的枭兽形态问好，{name}。它总是一脸受惊。"
L["You were not prepared, {name}. Now you are."] = "自寻死路？现在不是了，{name}。"
L["Ten thousand years in a cell, {name}. You've earned a small kindness."] = "被囚禁了一万年，{name}。你值得一点小小的善意。"
L["You gave up so much to fight the Legion, {name}. Here's a little back."] = "为了对抗燃烧军团，你付出了太多，{name}。还你一点。"
L["For the one who leaps first, {name}. Do land somewhere friendly."] = "给第一个跳下去的人，{name}。记得落在友善的地方。"
L["Fel and fury, {name}, and now a little kindness. It'll balance out."] = "邪能与怒火，{name}，现在再加点善意。正好平衡一下。"
L["I'd ask if you saw this coming, {name}, but you see everything."] = "本想问你料到没，{name}，可你蒙着眼都能看见一切。"
L["You can see souls, {name}. Mine's the one being generous."] = "你看得见灵魂，{name}。正大方着的那个就是我的。"
L["Illidan never let anyone help him, {name}. You're wiser than your teacher."] = "伊利丹从不让人帮忙，{name}。你这是青出于蓝。"
L["A demon inside and a Legion outside, {name}. Here's one thing on your side."] = "内有恶魔，外有军团，{name}。这个站你这边。"
L["For you, {name}. Please don't breathe on it."] = "给你，{name}。拜托别对着它吐息。"
L["A little help for a dragon, {name}. I'll be telling my grandchildren."] = "帮了龙一把，{name}。这事我要讲给孙子听。"
L["The Aspects sent you out into the world, {name}. I'm making it friendlier."] = "守护巨龙派你来到这世上，{name}。我让它变得友善一点。"
L["Take to the skies after this, {name}. I'll wave from down here."] = "拿了这个就飞上天吧，{name}。我在地上朝你挥手。"
L["A dragon on our side, {name}. I've never felt safer being generous."] = "有条龙站在我们这边，{name}。慷慨从没这么安全过。"
L["A gift for a dragon, {name}. Normally folk bring gold and hope to leave again."] = "给龙送礼，{name}。一般人都是带着金子来，只求能活着走。"
L["For the one who could fly me to the next town, {name}. Not asking. Hinting."] = "给能驮我飞到下个镇子的你，{name}。不是请求，是暗示。"
L["I've met a few dragons, {name}. You're the first I didn't run from."] = "我见过几条龙，{name}。你是第一条我没逃跑的。"
L["For the world's youngest ancient, {name}."] = "送给世上最年轻的上古生灵，{name}。"
L["{buff} for a mage, {name}. Like lending a library a book."] = "给法师上{buff}，{name}，纯属班门弄斧。"
L["Mage to mage, {name}: I won't ask you for water if you won't ask me."] = "法师对法师，{name}：你不问我要水，我也不问你要。"
L["Two mages, {name}. Between us we can portal anywhere and still be late."] = "两个法师，{name}。我们能传送到任何地方，照样迟到。"
L["A mage for a mage, {name}. The Kirin Tor would call this peer review."] = "法师给法师，{name}。肯瑞托管这叫同行评审。"
L["A mage enchanting a mage, {name}. We'll both pretend we needed it."] = "法师给法师加持，{name}。咱俩都假装需要吧。"
L["Neither of us will admit which spells we still read off the page, {name}."] = "哪些法术咱俩还得照着书念，{name}，谁都不会承认。"
L["One mage is a scholar, {name}. Two is an argument. Here's my opening point."] = "一个法师是学者，{name}，两个就是辩论。这是我的开场论点。"
L["We both know this spell backwards, {name}. Luckily I cast it forwards."] = "这法术咱俩都倒背如流，{name}。幸好我是正着施放的。"
L["More mana for you, {name}. Try not to spend it all on one fireball."] = "给你更多法力值，{name}。别一个火球全花光。"
L["Priest to priest, {name}: who blesses the blessers? Today, me."] = "牧师对牧师，{name}：谁来祝福祝福者？今天我来。"
L["Between us priests, {name}, we'll both pretend the tank listens."] = "咱们牧师之间，{name}，就一起假装坦克会听话吧。"
L["A priest looking after a priest, {name}. It feels almost forbidden."] = "牧师照顾牧师，{name}。感觉像是犯了什么禁忌。"
L["Two priests, {name}. Twice the praying and half the panic."] = "两个牧师，{name}。祷告加倍，慌张减半。"
L["Two priests, {name}. If it goes wrong, we're the last ones standing. Kneeling."] = "两个牧师，{name}。万一翻车，最后站着的是咱俩。哦不，跪着。"
L["Your prayers can take a break, {name}. Mine are covering the shift."] = "你的祷告歇会儿吧，{name}。我的来顶班。"
L["I'd preach to you, {name}, but you've heard it. You've probably given it."] = "本想给你布道，{name}，可你早听过了。说不定还讲过。"
L["Same vows and same sore knees, {name}. Here's something for yours."] = "同样的誓言，同样的膝盖疼，{name}。给你的膝盖补补。"
L["If I fall, {name}, you know the words. If you fall, so do I. Let's neither."] = "我倒了你知道该念啥，{name}；你倒了我也知道。咱俩都别倒。"
L["Two druids, {name}. The Cenarion Circle would call this a quorum."] = "两个德鲁伊，{name}。塞纳里奥议会会说这够开会了。"
L["Druid to druid, {name}: bear or cat, I'd know you by the leaves in your hair."] = "同为德鲁伊，{name}：熊也好猫也好，看头上树叶就认得。"
L["From one shapeshifter to another, {name}: this one fits every shape."] = "变形者送变形者，{name}：这个每种形态都合身。"
L["No handshake, {name}. Two druids, and neither of us has the right shape for it."] = "不握手了，{name}。两个德鲁伊，谁都不是有手的形态。"
L["Between us, {name}, we've a shape for every problem. Mostly bears."] = "咱俩加起来，{name}，每个问题都有对应的形态。多半是熊。"
L["Fellow druid, {name}? Then you know the trees told me you were coming."] = "同为德鲁伊，{name}？那你知道，是树告诉我你要来的。"
L["If you see me as a cat later, {name}, pretend you don't know me. Dignity."] = "待会儿看见我变成猫，{name}，就装不认识我。给点面子。"
L["Paladin to paladin, {name}: I won't mention the bubble if you don't."] = "圣骑士对圣骑士，{name}：你不提无敌，我也不提。"
L["A blessing for a paladin, {name}. Now we're both insufferably radiant."] = "给圣骑士的祝福，{name}。这下咱俩都亮得让人受不了。"
L["Two paladins, {name}. Somewhere, a priest is quietly relieved."] = "两个圣骑士，{name}。某处有个牧师悄悄松了口气。"
L["One of us should be humble about this, {name}. Neither of us will be."] = "我们俩总得有一个谦虚点，{name}。可谁都不会。"
L["Same oath, different polish, {name}. Yours is shinier; I noticed."] = "同一誓言，不同光泽，{name}。你的更亮，我注意到了。"
L["Between us, {name}, we could light a cathedral. Or a small, very holy room."] = "咱俩合力，{name}，能照亮一座大教堂。或一间很神圣的小屋。"
L["Two suits of plate, {name}. Nobody will hear us sneak up. Nobody ever does."] = "两身板甲，{name}。咱俩悄悄摸过去，谁也听不见。哐当，哐当。"
L["Your libram and mine agree on this one, {name}. Rare, that."] = "你的圣契和我的在这事上意见一致，{name}。难得。"
L["Warlock to warlock, {name}: keep your imp away from mine. They gossip."] = "术士对术士，{name}：小鬼们别凑一块，它们爱八卦。"
L["Fellow warlock, {name}? Then you know this one's actually harmless. Honestly."] = "同为术士，{name}？那你知道这个是真的无害。说真的。"
L["Two warlocks, {name}. Let's not compare soul shards in public."] = "两个术士，{name}。别在大庭广众下比灵魂碎片。"
L["Between us, {name}, the demons do all the work. This bit I do myself."] = "私下说，{name}，活儿都是恶魔干的。这下我亲自来。"
L["Another warlock, {name}. Let's be polite; I've seen what you summon."] = "又一个术士，{name}。客气点好，我见过你召唤的东西。"
L["A spell from one warlock to another, {name}. Check it for curses. I would."] = "术士送术士的法术，{name}。查查有没有诅咒，换我也会查。"
L["Fellow warlock, {name}. The only one who won't ask where this came from."] = "同为术士，{name}。只有你不会问这是哪儿来的。"
L["Two warlocks, one kind deed, {name}. The Burning Legion must be livid."] = "两个术士，一件好事，{name}。燃烧军团肯定气炸了。"
L["I'd summon you a drink, {name}, but we both know how summoning goes."] = "本想给你召唤杯酒，{name}，可召唤出来的从来不是酒。"
L["Two warriors, {name}. Somewhere, a healer just sighed."] = "两个战士，{name}。某处有个治疗叹了口气。"
L["Warrior to warrior, {name}: first into the fight buys the drinks. I'm buying."] = "战士对战士，{name}：先冲进去的请喝酒。这轮我请。"
L["Shout for shout, {name}. We'll deafen the whole place together."] = "吼对吼，{name}。咱们一起把这儿的人都震聋。"
L["No plan, {name}? Perfect. We'll get along."] = "没计划，{name}？完美，合得来。"
L["Warriors, {name}: the only folk who think shouting is a spell. We're right."] = "只有咱们战士觉得吼一嗓子就算法术，{name}。咱们没错。"
L["One warrior to another, {name}: whoever's hit first gets angriest. Lucky them."] = "战士对战士，{name}：谁先挨打谁最怒。算他走运。"
L["You know this one, {name}. You've probably shouted it at me already."] = "这招你熟，{name}。说不定已经冲我吼过了。"
L["Our trainer would be proud, {name}. He'd shout it, but he'd be proud."] = "训练师会为咱俩骄傲的，{name}。用吼的，但确实骄傲。"
L["Fellow warrior? Then you know the blacksmith's first name too, {name}."] = "同为战士？那你肯定也知道铁匠叫什么，{name}。"
L["No mana to fill, {name}. It'll just stand about being clever, like me."] = "没法力值可补，{name}。它就站那儿显得很聪明，跟我一样。"
L["Intellect on a warrior, {name}. The Kirin Tor would call it research."] = "给战士上智力，{name}。肯瑞托管这叫学术研究。"
L["I only know the one spell for friends, {name}. Rage or mana, you're getting it."] = "对朋友我只会这一个法术，{name}。怒气还是法力，照给不误。"
L["Your rage doesn't need this, {name}, but I'd feel rude walking past you."] = "你的怒气用不上这个，{name}，可我路过不给就太失礼了。"
L["No mana, I know, {name}. Use it on locks. They're only puzzles with opinions."] = "没法力值，我懂，{name}。拿去开锁吧，锁只是有脾气的谜题。"
L["It's meant for mana, {name}. You'll find a use. Rogues always find a use."] = "这本是补法力的，{name}。你总能派上用场，潜行者总能。"
L["Energy, not mana, I know, {name}. Call it a very clever lockpick."] = "是能量不是法力，我懂，{name}。就当是把聪明的开锁器。"
L["Aye, {name}, ye only had to ask. Hold still now!"] = "好嘞，{name}，开口就成。站着别动！"
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "喏，{name}，一点小意思，保你站得稳稳当当！"
L["My thanks, {name}. Allow me to return the kindness."] = "多谢，{name}。请容我回报这份好意。"
L["Of course, {name}. Stand fast a moment."] = "当然，{name}。原地稍候片刻。"
L["The road ahead is long, {name}. Take this with you."] = "前路漫长，{name}。带上这个吧。"
L["Ishnu-alah, {name}. Your kindness is returned."] = "Ishnu-alah，{name}。你的好意，我来回报。"
L["Elune-adore, {name}. Walk softly beneath the stars."] = "Elune-adore，{name}。愿你在星光下轻步而行。"
L["The Light rewards kindness, {name}, and so shall I."] = "圣光会回报善意，{name}，我也会。"
L["Of course, {name}. May the Naaru guide your steps."] = "当然，{name}。愿纳鲁指引你的脚步。"
L["The Light is with you, {name}. Go in peace."] = "圣光与你同在，{name}。平安前行吧。"
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "多谢，{name}。吉尔尼斯永不忘恩。"
L["Lok'tar ogar, {name}! Take this into battle."] = "Lok'tar ogar，{name}！带着它上战场！"
L["The Earth Mother sees your kindness, {name}. I return it."] = "大地母亲看见了你的善意，{name}。我来回报。"
L["Of course, {name}. Stand tall and be at peace."] = "当然，{name}。昂首站立，心平气和。"
L["Walk with the Earth Mother, {name}."] = "与大地母亲同行吧，{name}。"
L["Sure ting, {name}. Hold still now."] = "小事一桩，{name}。别乱动咯。"
L["Da loa be watchin' over ya, {name}."] = "洛阿在守着你咧，{name}。"
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "礼数周全，难能可贵，{name}。Anar'alah belore。"
L["Anar'alah belore, {name}. May the sun guide you."] = "Anar'alah belore，{name}。愿太阳指引你。"
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "你的慷慨我记住了，{name}。苏拉玛不忘朋友。"
L["Thank you, {name}! The caravan always repays a kindness."] = "谢谢你，{name}！商队向来知恩图报。"
L["Every traveller needs something for the road, {name}."] = "旅人上路总得带点东西，{name}。"
L["Of course, {name}. Patience, and it is done."] = "当然，{name}。耐心些，这就好。"
L["Take this, {name}. Even a dragon needs allies."] = "拿着，{name}。就算是龙也需要盟友。"
L["Thank you, {name}. The Alliance looks after its own."] = "谢谢你，{name}。联盟会照顾自己人。"
L["Of course, {name}. Allies help each other."] = "当然，{name}。盟友就该互相帮助。"
L["For the Alliance, {name}! Stay strong out there."] = "为了联盟，{name}！在外面挺住！"
L["Strength and honour, {name}. Your kindness is repaid."] = "力量与荣誉，{name}。这份好意，我还了。"
L["Consider it done, {name}. For the Horde."] = "包在我身上，{name}。为了部落。"
L["For the Horde, {name}! Go with strength."] = "为了部落，{name}！愿力量与你同行！"
L["Thank you, {name}. Good hearts are found everywhere."] = "谢谢你，{name}。好心人哪里都有。"
L["Gladly, {name}, whatever banner you fly."] = "乐意之至，{name}，不论你打着哪面旗帜。"
L["Friends can come from any side, {name}."] = "朋友可以来自任何一方，{name}。"
L["Safe travels, {name}. Take some {buff} with you."] = "一路平安，{name}。带上些{buff}吧。"
L["Returning a favour:"] = "还人情："
L["Answering a request:"] = "回应请求："
L["In your group:"] = "你的队友："
L["Offering unasked:"] = "主动推荐："
L["Returning a favour of %s:"] = "还人情（%s）："
L["Meeting somebody a third time:"] = "第三次遇到同一个人："
L["(nothing -- speech off, or no usable lines)"] = "（无——发言已关闭，或没有可用的台词）"
L["In character"] = "入戏"
L["an in-character line"] = "一句入戏台词"
L["Favour ledger"] = "人情账本"
L["Close (Escape works too)"] = "关闭（也可按Esc）"
L["No favours recorded today."] = "今天没有记录到人情。"
L["Nothing you cast could return today's favours."] = "你施放的法术都还不了今天的人情。"
L["Returned %d of 1 favour today."] = "今天已还%d份人情（共1份）。"
L["Returned %d of %d favours today."] = "今天已还%d份人情（共%d份）。"
L["1 favour still owed."] = "还欠1份人情。"
L["%d favours still owed."] = "还欠%d份人情。"
L["You gave 1 buff unprompted today."] = "你今天主动加了1个增益。"
L["You gave %d buffs unprompted today."] = "你今天主动加了%d个增益。"
L["All time -- received: %d, returned: %d, given to your group: %d, to strangers: %d"] = "累计——收到：%d，已还：%d，给队友：%d，给陌生人：%d"
L["All time"] = "累计"
L["received"] = "收到"
L["returned"] = "已还"
L["to your group"] = "给队友"
L["to strangers"] = "给陌生人"
L["%d-%d of %d"] = "第%d-%d条，共%d条"
L["Everything"] = "全部"
L["Favours"] = "人情"
L["Buffs you gave"] = "你给出的增益"
L["Nothing recorded. When somebody buffs you it is listed here, and so is what you give back and who you buff unprompted."] = "暂无记录。有人给你加增益时会列在这里，你还的人情和你主动给谁加了增益也会列在这里。"
L["No favours recorded. When somebody buffs you, they are listed here."] = "暂无人情记录。有人给你加增益时，对方会列在这里。"
L["No buffs given unprompted. When the prompt buffs somebody who did not buff you first, it is listed here."] = "暂无主动加的增益。提示框给没有先给你加增益的人加增益时，会列在这里。"
L["Nothing is recorded while Manners is switched off."] = "Manners关闭期间不会记录任何内容。"
L["Nothing is recorded while the prompt has nothing to cast on this character."] = "提示框在此角色上没有可施放的法术时，不会记录任何内容。"
L["Favours are not recorded while \"People who buff me\" is off, on the Who to buff tab."] = "“给谁加增益”标签页的“给我加增益的人”关闭时，不会记录人情。"
L["Clear"] = "清空"
