L["Calm (less movement)"] = "柔和（减少动效）"
L["Keep the prompt dim and still in combat"] = "战斗中让提示框保持暗淡静止"
L["It stays on screen in combat because your key binding would still cast; this only stops the flashes that say what a click did, red if it failed."] = "战斗中它仍会留在屏幕上，因为你的快捷键仍会施法；此项只会停止表示点击结果的闪光（失败时为红色）。"
L["Play a sound"] = "播放音效"
L["When a new person appears on the prompt."] = "提示框上出现新的人时。"
L["Sound"] = "音效"
L["%s |cff808080(not loaded)|r"] = "%s |cff808080（未加载）|r"
L["Only for people who buff me"] = "仅限给我加增益的人"
L["Off, every new person makes a sound, passers-by included."] = "关闭时，每出现一个新的人都会播放音效，包括路人。"
L["%s is silent. Pick a sound above."] = "“%s”为静音。请在上方选择一个音效。"
L["Text"] = "文字"
L["Font"] = "字体"
L["Font size"] = "字体大小"
L["Text colour"] = "文字颜色"
L["Left at white, text turns dark on a light panel by itself. Other colours are used as picked, except for names while this is on:"] = "保持白色时，文字在浅色面板上会自动变深。其他颜色会照所选使用，但开启下面这项时名字除外："
L["Colour names by class"] = "按职业为名字着色"
L["Show a second line"] = "显示第二行"
L["Needs a prompt at least %d pixels tall."] = "提示框高度需至少%d像素。"
L["Prompt wording"] = "提示框措辞"
L["Icon and waiting list"] = "图标和等待列表"
L["Show spell icon"] = "显示法术图标"
L["Icon size"] = "图标大小"
L["Kept inside the prompt -- make it taller or wider first for a bigger icon."] = "图标不会超出提示框——想要更大的图标，请先把提示框调高或调宽。"
L["This look sizes the icon from the prompt's height: %d at %d high. Make the prompt taller for a bigger icon."] = "此外观按提示框高度决定图标大小：%d（高度%d）。把提示框调高可以让图标更大。"
L["The icon is held at %d to fit a prompt %d wide."] = "图标被限制在%d，以适应宽度为%d的提示框。"
