L["Timing"] = "计时"
L["Don't repeat a spell on someone for (seconds)"] = "同一法术对同一人的重复间隔（秒）"
L["In case the cast failed; right-clicking the prompt skips the person for this long."] = "以防施法失败；右键点击提示框会在这段时间内跳过此人。"
L["Check for people every (seconds)"] = "扫描间隔（秒）"
